const _explanations: Record<number, string> = {
  // ── Grundlagen (bereits vorhanden, IDs 1–50) ───────────────────────────
  1: "Praxis: Druck in bar, Temperatur in °C. Physikalisch (SI): Druck in Pascal (1 bar = 100.000 Pa), Temperatur in Kelvin. Temperaturdifferenzen IMMER in Kelvin – 1 K Differenz entspricht 1 °C Differenz.",
  2: "Temperatur misst die mittlere kinetische Energie der Moleküle. Je höher die Temperatur, desto schneller bewegen sich die Moleküle. Gemessen mit Thermometer in °C oder K.",
  3: "Obwohl absolute Temperaturen in °C angegeben werden, gelten Differenzen immer in Kelvin (K). Beispiel: 20 °C – 5 °C = 15 K. Kelvin ist die SI-Einheit.",
  4: "Absolutdruck = 0 bar bedeutet vollständiges Vakuum. Alle Dampfdrucktabellen und log(p),h-Diagramme arbeiten mit Absolutdruck! Prüfungsfalle: Manometer zeigt Überdruck, nicht Absolutdruck.",
  5: "Atmosphärendruck auf Meereshöhe ≈ 1,013 bar. Unterdruck = jeder Druck unter dem Atmosphärendruck. Manometer mit negativem Bereich können Unterdruck (Vakuum) anzeigen.",
  6: "Manometer messen den Druck relativ zur Atmosphäre (Überdruck). Absolutdruck = Manometerdruck + Atmosphärendruck (≈ 1 bar). Wichtige Umrechnung für Tabellen!",
  7: "Manometer zeigen 0 bar, wenn in der Anlage genau Atmosphärendruck herrscht. Das Gerät misst den Überdruck gegenüber der Umgebung.",
  8: "Formel: p_abs = p_man + p_atm (≈ 1 bar). Beispiel: Manometer zeigt 3,5 bar → Absolutdruck = 4,5 bar. Nötig für alle Tabellen-Ablesungen.",
  9: "Dampfdrucktabellen und log(p),h-Diagramme verwenden grundsätzlich Absolutdruck, da Siedepunkt, Enthalpie und Dichte physikalisch absolut definiert sind.",
  10: "Gay-Lussac: p/T = konst. bei V = konst. Praxisbedeutung: Höherer Saugdruck → höhere Verdampfungstemperatur → besserer COP, aber auch höhere Verdichtertemperaturen.",
  11: "Absolutdruck = 1,2 bar (Manometer) + 1 bar (Atmosphäre) = 2,2 bar abs. Dann Dampfdrucktabelle R-513A aufschlagen: bei 2,2 bar abs liegt t₀ ≈ –10,6 °C.",
  12: "Merksatz: Wärme ZUFÜHREN → Schmelzen und Verdampfen (endotherm). Wärme ABFÜHREN → Erstarren und Verflüssigen (exotherm). Der Kältekreislauf nutzt genau diesen Phasenwechsel.",
  13: "Wirkungsgrad η = Nutzen / Aufwand (immer ≤ 1). In der Kältetechnik: COP = Q₀ / P. Ein COP von 3 bedeutet: 3 kW Kälte für 1 kW Antriebsleistung.",
  14: "1. Hauptsatz: Energie bleibt erhalten. Q₀ + P = Q_C. Der Verflüssiger muss also mehr Wärme abführen als der Verdampfer aufnimmt – die Differenz ist die Verdichterleistung.",
  15: "2. Hauptsatz: Wärme fließt immer von warm nach kalt. Daher gilt zwingend: t₀ < Kühlraumtemperatur und t_C > Umgebungstemperatur. Ohne diese Temperaturdifferenzen kein Wärmefluss!",
  16: "0 K = –273,15 °C ist die kältestmögliche Temperatur (absoluter Nullpunkt). Umrechnung: T[K] = T[°C] + 273,15. Wichtig für Gay-Lussac und alle thermodynamischen Berechnungen.",
  17: "Enthalpie h [kJ/kg] = gespeicherte Wärmeenergie je Kilogramm Kältemittel. Im log(p),h-Diagramm liest man h ab. Kälteleistung pro kg: q₀ = h₁ – h₄.",
  18: "Kleiner k-Wert = gute Dämmung (Kühlraumwand, z. B. 0,2 W/(m²K)). Großer k-Wert = guter Wärmedurchgang (Verdampfer/Verflüssiger, z. B. 30 W/(m²K)). Einheit: W/(m²·K).",
  19: "Ohne Zwangsbelüftung sinkt der Wärmeübergangskoeffizient α stark. Der k-Wert des Verdampfers sinkt → weniger Wärme wird übertragen → Kälteleistung nimmt deutlich ab.",
  20: "Sensibel = mit Temperaturänderung (Überhitzungszone im Verdampfer). Latent = ohne Temperaturänderung, beim Phasenwechsel (Verdampfungszone bei t₀ = const.).",
  21: "Höherer Druck → höherer Siedepunkt. Die Dampfdruckkurve zeigt diesen Zusammenhang grafisch. Grundprinzip der Kompressionskältemaschine: Druck regelt die Verdampfungstemperatur.",
  22: "2. Hauptsatz: Wärme fließt nur von warm nach kalt. Damit der Verflüssiger Wärme an die Umgebung abgeben kann, muss t_C > t_Umgebung sein. Nur durch Verdichtung wird t_C hoch genug.",
  23: "2. Hauptsatz: Damit der Verdampfer Wärme aus dem Kühlraum aufnehmen kann, muss t₀ < t_Kühlraum sein. Durch Drosselung sinkt der Druck und damit die Verdampfungstemperatur.",
  24: "Wärmestrom Q = k · A · ΔT. Dieser Strom fließt nur, wenn ΔT positiv ist (warm → kalt). Daher muss immer t_C > t_Außen gelten – ansonsten kein Wärmeübergang im Verflüssiger.",
  25: "Wärmestrom fließt nur von warm nach kalt. Damit der Verdampfer Wärme aus dem Kühlraum aufnehmen kann, muss t₀ niedriger als die Kühlraumtemperatur sein.",
  26: "Faustregel: Temperaturdifferenz (ΔT) zwischen Kühlraum und Verdampfer ≈ 10 K. Bei Kühlraum 0 °C → t₀ ≈ –10 °C. Größeres ΔT = mehr Wärmedurchgang, aber schlechterer COP.",
  27: "Faustregel: Temperaturdifferenz zwischen Verflüssiger und Umgebung ≈ 10 K. Bei 33 °C Außentemperatur → t_C ≈ 43 °C. Prüfung: Höhere t_C = schlechterer COP.",
  28: "Taupunkt: Temperatur, bei der Luft mit Wasserdampf gesättigt ist – Kondensation beginnt. Feuchtkugeltemperatur: niedrigste erreichbare Temperatur durch Verdunstungskühlung (Kühlgrenztemperatur).",
  29: "Überhitzung = Erwärmung des gesättigten Dampfes über t₀ hinaus. Messung: ΔT = t_Rohr – t₀(aus Manometer). Schützt den Verdichter vor Flüssigkeitsschlägen.",
  30: "Verdichter komprimieren NUR Gas – Flüssigkeiten sind inkompressibel. Flüssiges Kältemittel im Verdichter → Flüssigkeitsschlag → Ventile, Kolben und Kurbelwelle werden zerstört.",
  31: "Die Überhitzung findet im letzten Abschnitt des Verdampfers statt (Überhitzungszone). Dort ist das Kältemittel bereits vollständig verdampft und wird weiter als Gas erwärmt.",
  32: "TEV (Thermostatisches Expansionsventil) oder EEV (Elektronisches Expansionsventil) regeln durch Veränderung der Kältemittelmenge die Überhitzung. Kapillarrohr: feste Drossel, keine Regelung!",
  33: "TEV-Sollwert: 7–8 K. EEV-Sollwert: 4–6 K. Zu wenig Überhitzung → Flüssigkeitsschlag. Zu viel Überhitzung → Verdampferfläche wird für Überhitzung statt Verdampfung genutzt → Kälteverlust.",
  34: "Verdichter: Saugseite (ND) und Druckseite (HD). Expansionsorgan: Hochdruckflüssigkeit tritt ein, Niederdruckgemisch tritt aus. Beide erzeugen den Druckunterschied im Kreislauf.",
  35: "Praxis: Manometer an ND-Seite ablesen → Absolutdruck → t₀ aus Dampfdrucktabelle. Kontaktthermometer an Saugleitung befestigen → t_Rohr. Überhitzung = t_Rohr – t₀.",
  36: "Zu wenig Überhitzung: Flüssiges Kältemittel gelangt in den Verdichter → Flüssigkeitsschlag → Ventilfeder bricht, Kolbenkopf beschädigt, Öl verdünnt. Gefährlichste Betriebsstörung!",
  37: "Zu viel Überhitzung: Der hintere Teil des Verdampfers wird für Überhitzung verbraucht → weniger Fläche für Verdampfung → Kälteleistung sinkt, Verdichtertemperatur steigt, COP sinkt.",
  38: "Unterkühlung = Abkühlung der Flüssigkeit unter t_C. Voraussetzung: 100 % Flüssigkeit (kein Zweiphasengemisch). Vorteil: Mehr Kälteleistung, keine Dampfblasen vor dem Expansionsorgan.",
  39: "Blasen im Kältemittel vor dem Expansionsorgan: schlechte Regelfähigkeit, reduzierte Kälteleistung, Kavitationsgeräusche. Blasenfreie Flüssigkeit (durch Unterkühlung) = stabiler Betrieb.",
  40: "Praxis: Manometer an HD-Seite vor Expansionsorgan → Absolutdruck → t_C aus Tabelle. Kontaktthermometer an Rohr → t_Rohr. Unterkühlung = t_C – t_Rohr.",
  41: "Druckverluste in langen Flüssigkeitsleitungen oder bei Höhenunterschieden: p sinkt → Siedepunkt sinkt → Dampfblasen entstehen → Fehlregelung, reduzierte Kälteleistung.",
  42: "Nutzbare Unterkühlung ist nur möglich, wo 100 % Flüssigkeit vorhanden ist (nach dem Sammler). Möglichkeiten: externer Unterkühler, innerer Wärmeübertrager (IWT/Liquid-Line-Suction-Line HX).",
  43: "Im Verflüssiger ist noch Zweiphasengemisch vorhanden → keine nutzbare Unterkühlung möglich (kein 100 % Flüssigkeitsbereich). Erst nach dem Sammler ist eine sichere Unterkühlung möglich.",
  44: "Durch Wärmeabgabe der Flüssigkeitsleitung an die kühlere Umgebung: ca. 1–3 K Unterkühlung. Im Sommer oder bei Sonneneinstrahlung auf die Leitung kann dieser Effekt gegen null gehen.",
  45: "Höchste Temperatur: Verdichteraustritt (Heißgas, verdichteter Dampf weit über t_C). Niedrigste Temperatur: Verdampfereintritt (nach Drosselung, Kältemittel ca. bei t₀ mit Flüssigkeitsanteil).",
  46: "Enthitzung = Abkühlung des überhitzten Heißgases auf Kondensationstemperatur t_C (sensibel). Findet in der Druckleitung und im ersten Teil des Verflüssigers statt, bevor die Verflüssigung beginnt.",
  47: "Beide sind Wärmeübertrager mit Phasenwechsel des Kältemittels. Unterschied: Verdampfer nimmt Wärme auf (Niederdruckseite, t₀), Verflüssiger gibt Wärme ab (Hochdruckseite, t_C).",
  48: "Beide trennen HD von ND. Verdichter saugt ND an und drückt HD heraus (mit Arbeitsaufwand). Expansionsorgan lässt HD-Flüssigkeit durch Drossel auf ND-Niveau entspannen (ohne Arbeit).",
  49: "Verdampfer = Wärmeübertrager auf der Niederdruckseite. Er nimmt Wärme aus dem Kühlgut/Kühlraum auf. Das Kältemittel verdampft dabei bei konstanter, niedriger Temperatur t₀.",
  50: "Trocken: Kältemittel verlässt Verdampfer überhitzt → geregelt durch TEV/EEV. Überflutet: Verdampfer mit Flüssigkeit durchflutet, Austritt als Nassgas → kein Expansionsventil nötig, aber Flüssigkeitsabscheider erforderlich.",

  // ── Kältemittel & Kältemaschinenöle (51–100) ──────────────────────────
  51: "Im Trocken-Verdampfer gibt es zwei klar trennbare Zonen: Zuerst die Verdampfungszone (latente Wärme, Temperatur konstant = t₀), dann die Überhitzungszone (sensible Wärme, Temperatur steigt). Das TEV regelt den Grenzpunkt.",
  52: "Latente Wärme findet ohne Temperaturänderung statt (Phasenwechsel flüssig→gasförmig). Sensible Wärme ändert die Temperatur des Dampfes. Im Verdampfer ist die Verdampfungszone energetisch wesentlich effizienter als die Überhitzungszone.",
  53: "Direkte Kühlung: das Kältemittel strömt selbst durch den Verdampfer im Kühlraum. Indirekte Kühlung: ein Zwischenkreislauf mit Sole/Glykol überträgt die Kälte. Vorteil indirekt: Kältemittelmenge und -risiko geringer, dafür geringerer Wirkungsgrad.",
  54: "Lamellenver­dampfer sind am häufigsten (Kühlräume, Vitrinen). Plattenwärmeübertrager werden bei Kaltwassersätzen eingesetzt. Rohrbündelwärmeübertrager für große industrielle Anlagen. Jede Bauform hat unterschiedliche α-Werte (Wärmeübergangszahlen).",
  55: "Verschmutzung (Staub, Fett, Reif) auf den Lamellen erhöht den Wärmedurchgangswiderstand. Der k-Wert sinkt, die nutzbare Fläche nimmt ab → weniger Kälteleistung, höherer Saugdruck­abfall → ND-Störung möglich.",
  56: "Ohne Ventilator fällt die Zwangskonvektion weg → nur noch Naturkonvektion → α-Wert sinkt drastisch → k-Wert sinkt → Kälteleistung bricht ein, Verdampfer beginnt zu vereisen, da Luft nicht mehr abgetaut wird.",
  57: "Eis leitet Wärme schlechter als Metall (Wärmeleitfähigkeit Eis ≈ 2,2 W/(mK) vs. Aluminium ≈ 200 W/(mK)). Jede mm Eisschicht erhöht den Wärmedurchgangswiderstand enorm → regelmäßige Abtauung ist zwingend.",
  58: "Abtaumethoden: Elektrisch (Heizstäbe, einfach aber teuer), Heißgas (effizient, KM-Kreislauf umgekehrt), Kaltgas (Kompressor aus, Druckausgleich), Umluft (nur bei t₀ > –4 °C), Warmsole (indirekte Anlage). Wahl abhängig von Raumtemperatur und Energiekosten.",
  59: "Bei Temperaturen unter 0 °C kondensiert Luftfeuchtigkeit direkt als Reif (Sublimation). Reif­schichten wachsen rasch und isolieren → Leistungsverlust. Eis kann auch Lamellen beschädigen und Rohre blockieren.",
  60: "Reif ist ein ausgezeichneter Wärmedämmer. Bereits 1 mm Reif kann die Kälteleistung um 10–20 % senken. Regelmäßige, bedarfsgerechte Abtauung sichert konstante Leistung und Energieeffizienz.",
  61: "Zeitgesteuerte Abtauung: feste Zyklen (einfach, aber oft unnötig). Bedarfsabtauung: Sensor erkennt Vereisungsgrad (Temperaturdifferenz oder Luftmengenmessung) → effizienterer Betrieb, weniger Energieverbrauch.",
  62: "Stille (natürliche) Kühlung verzichtet auf Ventilator → keine Luftbewegung → weniger Austrocknung empfindlicher Waren → ideal für Blumen, Käse, feines Gemüse. Nachteil: geringerer Wärmeübergang → größere Verdampferfläche nötig.",
  63: "Drucktaupunkt: Temperatur, bei der ein Gasstrom unter Betriebsdruck zu kondensieren beginnt. Wichtig für Druckluftleitungen und Schutzgassysteme. Unterschied zum atmosphärischen Taupunkt: Druck verschiebt den Taupunkt.",
  64: "Kälteleistung Q₀ = ṁ × (h₁ – h₄). ṁ = Massenstrom des Kältemittels, h₁ = Enthalpie am Verdampferaustritt, h₄ = Enthalpie nach dem Expansionsorgan. Je größer die Enthalpiedifferenz, desto mehr Kälteleistung pro kg Kältemittel.",
  65: "Kältezahl (COP) = Q₀ / P_el. Ein COP von 3,5 bedeutet: Für 1 kW elektrische Leistung werden 3,5 kW Kälteleistung erzeugt. Höherer COP = effizienter Betrieb. Ziel: möglichst hoher COP.",
  66: "Verflüssigungsleistung Q_C = Q₀ + P. Sie ist immer größer als die Kälteleistung, da die Verdichterleistung ebenfalls als Wärme abgeführt werden muss. Wichtig für die Auslegung des Verflüssigers.",
  67: "Leistungszahl (Wärmepumpe) = Q_H / P. Sie gibt an, wie viel Heizwärme pro kW Strom erzeugt wird. Wärmepumpen-JAZ (Jahresarbeitszahl) berücksichtigt saisonale Temperaturschwankungen.",
  68: "HFKW (R-134a, R-404A): kein ODP, aber hoher GWP. FCKW (R-12, R-11): hoher ODP und GWP – verboten. HFCKW (R-22): mittlerer ODP – Auslaufphase. Natürliche KM (CO₂, NH₃, Propan): ODP = 0, GWP niedrig.",
  69: "R-22 (HFCKW) hat ODP = 0,055 – schädigend für Ozonschicht → seit 2015 Verwendungsverbot in der EU (Ozonschichtverordnung). Neue Anlagen dürfen seit 2000 nicht mehr mit R-22 befüllt werden.",
  70: "Zeotrope Gemische: Siedetemperatur ändert sich während des Phasenwechsels (Temperaturglide). Azeotrope Gemische: verhalten sich wie ein Reinstoff (kein Glide). Bei zeotropen Gemischen darf NUR Flüssigkeit nachgefüllt werden, da sonst die Zusammensetzung verschoben wird.",
  71: "Zeotropes Gemisch: Hat einen Temperaturglide (Siedetemperatur steigt beim Verdampfen und fällt beim Kondensieren). Das bedeutet: Am Verdampfer gibt es einen Temperaturunterschied zwischen Eintritt und Austritt des Kältemittels auch im Phasenwechsel.",
  72: "Azeotropes Gemisch: Verhält sich wie ein Reinstoff – kein Temperaturglide. R-507A und R-502 sind Beispiele. Vorteil: einfachere Auslegung von Wärmeübertragern. Kann wie Reinstoff als Gas oder Flüssigkeit nachgefüllt werden.",
  73: "Zeotropes Gemisch darf NUR als Flüssigkeit nachgefüllt werden (stehende Flasche, Flüssigphase entnehmen). Als Gas würde nur die leichter siedende Komponente austreten → Zusammensetzung verschiebt sich → Anlage arbeitet mit falscher KM-Mischung.",
  74: "Kältemaschinenöle müssen: thermisch stabil sein (kein Abbrand), Korrosionsschutz bieten, gute Schmiereigenschaften haben, mit dem Kältemittel mischbar sein (damit Öl aus dem Verdampfer zurücktransportiert wird) und einen niedrigen Stockpunkt haben.",
  75: "Mineralöl: kompatibel mit FCKW/HFCKW (R-12, R-22). POE (Polyolester): für HFKW (R-134a, R-404A, R-410A) – vorgeschrieben. PAG: für Kfz-Klimaanlagen (R-134a, R-1234yf). AB (Alkylbenzol): für R-22.",
  76: "Mischung verschiedener Öltypen ist verboten, da dies zu chemischen Reaktionen, Ablagerungen, Verstopfungen und Lagerungsschäden führen kann. Beim Umrüsten auf ein anderes Kältemittel muss auch das Öl vollständig getauscht werden.",
  77: "Wassergehalt im Öl und Kältemittel führt zu Säurebildung (Hydrolyse der Ester), die Kupferplattierung und Korrosion verursacht. POE-Öle sind besonders hygroskopisch → Anlage nie unnötig offen lassen, sofort evakuieren.",
  78: "Ölrückführung: Öl muss aus dem Verdampfer zurück zum Verdichter transportiert werden. Bei schlechter Rückführung: Ölmangel im Verdichter → Lagerschäden. Sicherstellung durch korrekte Rohrdimension, Sauggassteigleitungen mit Ölmitnahmeöffnung.",
  79: "Zu viel Öl im Verdampfer bildet einen isolierenden Ölfilm auf den Rohrinnenoberflächen → k-Wert sinkt → Kälteleistung nimmt ab → Ölabscheider vor dem Verdampfer sinnvoll bei großen Anlagen.",
  80: "Ölabscheider trennt Öl vom Heißgas nach dem Verdichter und führt es direkt zurück zum Verdichterölsumpf. Wichtig bei NH₃-Anlagen (Öl nicht mischbar) und bei langen Rohrleitungen. Schützt Verdampfer vor Ölverschmutzung.",
  81: "Kältemittel lösen sich im Öl → beim Start sinkt der Druck → gelöstes KM entgast schlagartig → Öl schäumt → Schmierwirkung nachlässt kurzfristig → Lagerschäden möglich. Kurbelwannenheizung verhindert KM-Anreicherung im Öl bei Stillstand.",
  82: "Dichtigkeit des Öls verhindert einen Ölfilm auf den Wärmeübertragungsflächen. Öl im Kreislauf ist technisch nicht vollständig vermeidbar, aber ein Ölabscheider minimiert den Öleintrag in den Kreislauf.",
  83: "Säurezahl (TAN – Total Acid Number) gibt den Säuregehalt im Öl an (mg KOH/g). Hoher Wert: chemischer Abbau, Kupferplattierung möglich. Grenzwert je nach Hersteller: ca. 0,1–0,5 mg KOH/g. Regelmäßige Ölanalysen empfohlen.",
  84: "Wasserabscheider (Trockner/Filter-Dryer) enthält Trockenmittel (Molekularsieb) und Schmutzfilter. Er entfernt Wasser und Fremdpartikel aus dem Kältemittelkreislauf, die Korrosion und Eisbildung im Expansionsorgan verursachen würden.",
  85: "Schauglas mit Feuchtigkeitsindikator: Grün = trocken (Wasser < 30 ppm). Gelb/Ocker = feucht. Sofortiger Trockner-Tausch erforderlich, wenn gelb! Außerdem zeigt das Schauglas blasenfreie Flüssigkeit (bei korrekter Unterkühlung).",
  86: "ODP (Ozone Depletion Potential) = Ozonabbaupotenzial. Referenz: R-11 = 1. HFKW haben ODP = 0. GWP (Global Warming Potential) = Treibhauspotenzial. Referenz: CO₂ = 1. Beide Werte wichtig für die Kältemittelauswahl unter F-Gase-VO und Ozonschicht-VO.",
  87: "R-134a: GWP = 1430, ODP = 0. Ziel: Ersatz durch R-1234yf (GWP = 4) oder R-513A (GWP = 573). Phase-Down erzwingt schrittweise Reduktion von HFKW mit hohem GWP ab 2015.",
  88: "Natürliche Kältemittel: CO₂ (R-744): GWP = 1, ODP = 0, nicht brennbar, aber sehr hohe Drücke. NH₃ (R-717): GWP = 0, ODP = 0, hohe Effizienz, aber toxisch und brennbar. Propan (R-290): GWP = 3, ODP = 0, sehr brennbar.",
  89: "R-290 (Propan): Sicherheitsklasse A3 = gering toxisch, aber leicht brennbar (Zündgrenze 1,7–10,9 Vol%). Besondere Sicherheitsmaßnahmen: Füllmengenbeschränkung, kein Zündfunkenquellen in der Nähe, Leckagealarm.",
  90: "R-744 (CO₂): Überkritischer Betrieb bei Hochdruck (> 73,8 bar). Vorteile: ODP = 0, GWP = 1, nicht brennbar. Nachteile: sehr hohe Drücke (bis 150 bar), Transkritisch-Kreislauf komplexer als subcritical, höhere Anforderungen an Armaturen.",
  91: "R-32: GWP = 675, ODP = 0, Sicherheitsklasse A2L (schwer entflammbar, Mindestzündenergie > 1000 mJ). Breite Verwendung in Split-Klimaanlagen. Geringere Füllmenge nötig als R-410A. Wichtig: kein offenes Feuer bei Wartung.",
  92: "Kältemittelleck: Sicherheitsgefahr (Erstickung, Vergiftung NH₃, Brandgefahr Propan), Umweltschaden (GWP), Leistungsverlust. Methoden: elektronischer Leckdetektor, UV-Kontrastmittel, Lecksuchspray, Blasentest (nur bei ND).",
  93: "Rückgewinnung ist gesetzlich vorgeschrieben (F-Gase-VO). Kältemittel darf nicht in die Atmosphäre abgelassen werden. Rückgewinnungsgerät saugt KM aus der Anlage, verdichtet es in Sammelflasche. Getrennt nach KM-Typ.",
  94: "Kältemittelflaschen sind farbcodiert: R-134a = hellblau, R-404A = orange, R-410A = rosa, R-290 = orange-rot, CO₂ = grau-silber. Immer Etikett prüfen – Farbe kann variieren. Niemals fremdes KM einfüllen!",
  95: "Kältemittelkreislauf-Drücke: Bei R-410A: Saugdruck bei –10 °C ≈ 6,1 bar, Kondensationsdruck bei 45 °C ≈ 27,6 bar. Deutlich höher als R-22. Rohrleitungen, Armaturen und Verdichter müssen für diese Drücke ausgelegt sein.",
  96: "Mindestdrehzahl bei Inverter-Verdichtern: Hersteller schreiben eine Mindestfrequenz vor (typisch 25–30 Hz). Bei zu niedriger Drehzahl liefert die Ölpumpe nicht mehr genug Öldruck → Mangelschmierung der Lager und Kolben → Verdichterausfall. Zusätzlich können mechanische Resonanzschwingungen auftreten, die Bauteile beschädigen.",

  // ── Verdichter (97–150) ────────────────────────────────────────────────
  97: "Verdichter ist das Herzstück der Kälteanlage: Er hebt das Kältemittel vom Nieder­druckniveau (Saugseite, t₀) auf das Hochdruckniveau (Druckseite, t_C). Dabei steigt auch die Temperatur des Kältemittels weit über t_C hinaus (Verdichtungsendtemperatur).",
  98: "Hubkolbenverdichter: gut für hohe Druckverhältnisse, robust, bewährt. Scrollverdichter: leiser, ölärmer im Betrieb, effizienter bei Teillast. Schraubenverdichter: für große Leistungen, stufenlose Regelung möglich. Turboverdichter: große Kälteleistung, keine Kolben.",
  99: "Hermetisch: Verdichter und Motor im geschlossenen Gehäuse → keine Wellendichtung nötig → geringe Leckagegefahr, aber nicht öffenbar (Einwegverdichter). Halbhermetisch: schraubbarer Deckel → Ventile und Motor wartbar. Offen: Welle aus dem Gehäuse geführt → externe Dichtung nötig.",
  100: "Liefergrad η_v = tatsächlich geförderter Volumenstrom / theoretischer Hubvolumen-Strom. Werte: 0,6–0,9 je nach Druckverhältnis und Bauart. Hoher Liefergrad = effizienter Verdichter. Sinkt bei hohem Druckverhältnis durch Rück­expansion aus dem schädlichen Raum.",
  101: "Schädlicher Raum = Totvolumen zwischen Kolbenkopf und Ventilen. Das dort verbleibende Hochdruckgas muss sich erst rück-expandieren, bevor neues Sauggas angesaugt werden kann. Je größer der schädliche Raum, desto niedriger der Liefergrad.",
  102: "Druckverhältnis π = p_HD / p_ND (Absolutdrücke!). Bei π = 5 (z.B. p_ND = 2 bar, p_HD = 10 bar) muss der Verdichter mehr Arbeit leisten. Hohe Druckverhältnisse → schlechterer Liefergrad, höhere Verdichtungsendtemperatur, schlechterer COP.",
  103: "Öldruckschalter (Öl-Differenzdruckwächter): Misst die Druckdifferenz zwischen Ölpumpenausgang und Kurbelwannendruck. Fällt die Differenz unter einen Mindestwert (typisch 0,5–1 bar), wird der Verdichter abgeschaltet (Lagerschaden droht). Zeitverzögerung 60–120 s.",
  104: "Motorschutz (Thermistorschutz/Klixon): Temperaturfühler (PTC) in den Motorwicklungen. Bei Übertemperatur steigt der PTC-Widerstand sprunghaft → Auslösegerät schaltet Verdichter ab. Schützt vor Wicklungsbrand durch Überlast, Anlaufprobleme oder Blockierung.",
  105: "Ölstand im Schauglas des Verdichters: Mitte des Schauglases im Betrieb = korrekt. Unter Mitte = Ölmangel (Leckage, schlechte Rückführung). Über Mitte = Öl verschäumt oder KM löst sich im Öl. Immer im Betrieb ablesen!",
  106: "Zu hohe Verdichtungsendtemperatur (>120–130 °C): Schmierölabbrand, Verkokung, Ventilschäden, Kolbenringverschleiß. Ursachen: hohes Druckverhältnis, hohe Überhitzung, unzureichende Kühlung, zu geringe Kältemittelmenge.",
  107: "Scrollverdichter: Zwei ineinandergreifende Spiralen – eine fest, eine exzentrisch. Gas wird schrittweise zur Mitte hin komprimiert. Vorteile: laufruhiger, effizienter bei Teillast (Inverter), weniger bewegliche Teile → zuverlässiger.",
  108: "Schraubenverdichter: Zwei ineinandergreifende Schraubenrotoren komprimieren das Gas. Für mittlere bis große Leistungen (30–5000 kW). Stufenlose Kapazitätsregelung durch Schieberventil. Öleinspritzung zur Kühlung und Dichtigkeitssicherung.",
  109: "Inverter-Verdichter = drehzahlgeregelter Verdichter (EC-Motor + Frequenzumrichter). Anpassung der Drehzahl an den Bedarf → kein Takten → konstantere Temperaturen, höhere Effizienz, weniger Anlaufstrom, längere Lebensdauer.",
  110: "Kapazitätsregelung beim Hubkolbenverdichter: Zylinder-Abschaltung (Solenoidventil hält Saugventil offen → Zylinder pumpt nicht), Drehzahlregelung (Inverter), Heiß­gasbypass (ineffizient). Schrauben­verdichter: Schieberventil.",
  111: "Sauggas-Mantelkühlung (bei halbhermetischen Verdichtern): Das Sauggas strömt am Motorgehäuse vorbei und kühlt den Motor. Vorteil: kein separater Kühlventilator. Nachteil: Das Sauggas wird aufgeheizt → geringerer Liefergrad, leicht erhöhte Verdichtungsendtemperatur.",
  112: "Ölabscheider direkt nach dem Verdichter: Heißgas + Öl → Ölabscheider → Öl fließt zurück zum Verdichter­ölsumpf, ölärmes Heißgas weiter zum Verflüssiger. Wichtig bei langen Leitungen, NH₃-Anlagen und wenn Verdampfer unterhalb des Verdichters liegt.",
  113: "Flüssigkeitsschlag: Flüssiges KM oder Öl wird komprimiert → schlagartige Druckspitze → Ventilfedern biegen sich, Kolbenstangen oder Kurbelwellenlager brechen. Erkennbar durch metallisches Klopfen beim Start. Ursache: zu niedrige Überhitzung oder KM im Kurbelgehäuse.",
  114: "Nasskompression: Flüssigkeitstropfen im Sauggas. Weniger gefährlich als Flüssigkeitsschlag, aber schädigt Ventile und verdünnt Öl. Ziel: immer trockener, überhitzter Dampf in den Verdichter.",
  115: "Kurbelwannenheizung verhindert bei Stillstand die KM-Anreicherung im Öl. Im Betrieb ist das KM gasförmig und löst sich kaum im Öl. Im Stillstand sinkt die Öltemperatur, das KM kondensiert und löst sich → beim nächsten Start schäumt Öl.",
  116: "Mehrkreisanlage: mehrere unabhängige Kältekreise, oft mit gemeinsamem Verflüssiger (Rack-System). Vorteil: Redundanz (ein Kreislauf kann ausfallen), individuelle Regelung. Typisch in Supermärkten.",
  117: "Verdichter-Anlaufstrom: 4–8× Nennstrom → Spannungsabfall im Netz → Sicherungen müssen ausreichend dimensioniert sein. Sanftanlauf oder Stern-Dreieck-Schaltung reduziert den Anlaufstrom.",
  118: "Stern-Dreieck-Anlauf: Beim Anlauf in Sternschaltung fließt nur 1/3 des Dreieckstroms → geringere Netzbelastung. Nach Hochlaufen Umschaltung in Dreieck. Nachteil: Anlaufmoment auch nur 1/3 → nicht bei schwer anlaufenden Lasten.",
  119: "Für eine korrekte Messung des Öldruckes darf der Messort nicht am Eingang der Ölpumpe (Ölsumpf), sondern muss am Ausgang der Ölpumpe liegen. Der Differenzdruckschalter vergleicht Ölpumpenausgangsdruck mit Kurbelwannendruck.",
  120: "Verdichterleistung P = ṁ × (h₂ – h₁). Reale Leistung höher als ideal (isentrop) durch innere Verluste (Reibung, Wärmeübergang). Wirkungsgrad: η_is = P_is / P_real. Typisch: 0,6–0,85 je nach Bauart und Druckverhältnis.",

  // ── Verflüssiger & Verdampfer (121–165) ───────────────────────────────
  121: "Luftgekühlter Verflüssiger: Heißgas → Wärme an Luft. Einfach, wartungsarm, aber stark von Außentemperatur abhängig. Wassergekühlter Verflüssiger: konstantere, höhere Effizienz, aber Wasserversorgung nötig. Verdunstungsverflüssiger: kombiniert Luft- und Verdunstungskühlung.",
  122: "Luftgekühlter Verflüssiger: Je höher die Außentemperatur, desto höher muss t_C sein → schlechterer COP. Im Winter niedrigere t_C → besserer COP, aber HD-Mindestdruck für Expansionsorgan beachten.",
  123: "Wassergekühlter Verflüssiger: Konstante Wassertemperatur (z.B. 20 °C) → niedrigere, stabilere t_C → besserer COP als luftgekühlt. Nachteil: Wasserverbrauch, Legionellenrisiko bei Rückkühler, Wasseraufbereitung nötig.",
  124: "Rohrbündelverflüssiger: KM kondensiert auf Außenseite der Rohre (Shell-and-Tube), Kühlwasser innen. Hohe Kapazität, robust. Plattenwärmeübertrager: kompakter, besser k-Wert, aber weniger druckstabil. Beide für Kaltwassersätze.",
  125: "Kühlturm/Rückkühler: gibt die Wärme des Kühlwassers an die Umgebungsluft ab. Nass: durch Verdunstung → sehr effizient, aber Legionellenrisiko, Wasserbedarf. Trocken: nur Luftkühlung → weniger effizient. Hybrid: kombiniert beide.",
  126: "Verflüssigerdruck steigt bei Verschmutzung (Schmutz, Kalk, Biofilm auf Rohren) → k-Wert sinkt → Wärme kann nicht mehr vollständig abgeführt werden → t_C steigt → HD-Pressostat kann ansprechen. Regelmäßige Reinigung (chemisch oder mechanisch) notwendig.",
  127: "Mindestverflüssigungsdruck: Das Expansionsorgan (TEV) benötigt einen Mindestdifferenzdruck (typisch 2–3 bar). Zu niedriger HD → ungenügende Durchflussmenge → Kälteleistung bricht ein. Druckhalteventil am Verflüssiger verhindert zu niedrigen HD.",
  128: "Enthitzungszone: Heißgas kühlt sich vom Verdichtungsaustritt bis auf t_C ab (sensibel). Verflüssigungszone: Kondensation bei konstant t_C (latent). Unterkühlungszone: Flüssigkeit kühlt unter t_C ab (sensibel). Alle drei Zonen im Verflüssiger vorhanden.",
  129: "Lamellenverflüssiger mit Ventilatoren: Ventilatoren zwingen Luft quer durch die Lamellen. Bei Ventilatorausfall steigt der Verflüssigungsdruck → HD-Pressostat schaltet ab. Schmutz auf Lamellen hat denselben Effekt → regelmäßige Reinigung!",
  130: "Verdampferarten nach Kühlmedium: Luftkühler (Lamellen), Brine-Kühler (Sole/Glykol im Rohrbündel), Kaltwassersätze (Plattenapparat), Eiswassererzeuger (überfluteter Verdampfer). Jede Bauart hat spezifische Anforderungen an Öl­rückführung.",
  131: "Überflutet­er Verdampfer: KM füllt den gesamten Verdampfer mit Flüssigkeit, Dampf wird am oberen Ende abgezogen. Hohe Effizienz (ganzer Verdampfer im Zweiphasengebiet), aber Ölrückführung schwierig → Ölabscheider und separate Rückführung nötig.",
  132: "Rohrbündelver­dampfer: KM auf der Außenseite der Rohre (Shell-and-Tube Falling-Film oder Shell-and-Tube Flooded). Kühlwasser innen. Vorteil: robust, druckfest. Nachteil: schwer zu reinigen. Bei Plattenwärmeübertrager-Verdampfern: hoher k-Wert, kompakt, aber druckempfindlicher.",
  133: "Verdampfungstemperatur t₀ sollte ca. 5–10 K unter der gewünschten Kühltemperatur liegen. Zu kleine Differenz → Verdampfer zu groß nötig. Zu große Differenz → schlechterer COP. Optimum: energetische vs. investive Abwägung.",
  134: "Abtauung beim Plattenver­dampfer: Elektrisch oder Heißgas. Wichtig: Abtauwasser muss vollständig abgeleitet werden, sonst friert es erneut ein und beschädigt die Rohre.",
  135: "Wärme­übertragung im Verdampfer: Q = k × A × ΔTLM (logarithmische Mitteltemperatur). Je größer k und A, desto mehr Kälteleistung bei gleicher Temperaturdifferenz. Vereisung und Verschmutzung reduzieren k.",

  // ── Expansionsorgane & Regelung (136–200) ─────────────────────────────
  136: "Thermostatisches Expansionsventil (TEV): Fühler am Verdampferaustritt misst Überhitzung. Öffnungsgrad des Ventils regelt Kältemitteleinspritzmenge so, dass Überhitzung konstant bleibt (Sollwert ca. 7–8 K).",
  137: "TEV mit internem/externem Druckausgleich: Intern: Ausgleichdruck = Eintrittsdruck des Verdampfers. Extern: Ausgleichdruck = Austrittsdruck. Bei großem Druckabfall im Verdampfer IMMER extern verwenden, sonst ungenügende Überhitzungsregelung.",
  138: "Kapillarrohr: feste Drossellänge und Innendurchmesser → fixer Druckabfall. Keine Regelung möglich. Einsatz: kleine, kompakte Geräte (Haushaltskühlschränke, kleine Split-Klimaanlagen) mit konstanter Last. Nachteil: bei variierender Last instabil.",
  139: "Elektronisches Expansionsventil (EEV): Schrittmotor regelt den Öffnungsquerschnitt stufenlos. Überhitzungsregler + Drucktransmitter + Temperaturfühler → präzisere Überhitzungsregelung (4–6 K), besserer COP, besonders bei Inverter-Anlagen.",
  140: "Druckhalteventil (HD): Verhindert zu niedrigen Verflüssigungsdruck (z.B. im Winter). Hält Mindestdruck aufrecht, damit TEV ausreichend Differenzdruck hat. Sonst: Kälteleistungseinbruch.",
  141: "Schwimmerventil: für überfluteten Verdampfer. Hält den Flüssigkeitsspiegel konstant. Mechanisch (Kugel-Schwimmer) oder elektronisch. Bei zu hohem Niveau: Flüssigkeit tritt in Saugleitung → Gefahr für Verdichter.",
  142: "Heißgasbypassventil: Öffnet bei zu niedrigem Saugdruck → führt Heißgas direkt zur Saugseite → Verdichter bleibt in Betrieb ohne abzuschalten. Ineffizient (Energie wird sinnlos verbraucht), aber schützt Verdichter vor Takten und Kurzhubbetrieb.",
  143: "Solenoidventil (Magnetventil): Elektromagnetisch gesteuertes An/Zu-Ventil. In Kälteanlagen für: Pump-down-Steuerung (leert Verdampfer vor Verdichter-Stopp), Saugleitungsabsperrung, Mehrkreisanlagen (Schalten einzelner Kreise).",
  144: "Pump-down: Solenoidventil in der Flüssigkeitsleitung schließt bei Thermostatanforderung → Verdichter saugt restliches KM aus dem Verdampfer → schaltet bei ND-Abschaltdruck aus. Vorteil: Verdampfer KM-frei bei Stillstand → kein Flüssigkeitsschlag beim Start.",
  145: "4-Wege-Ventil bei Wärmepumpen: Kehrt den Kältemittelfluss um. Im Kühlbetrieb: Innengerät = Verdampfer, Außengerät = Verflüssiger. Im Heizbetrieb: Innengerät = Verflüssiger, Außengerät = Verdampfer.",
  146: "Filtriertrockner (Filter-Dryer): Kombiniert Trockenmittel (Molekularsieb, 3A oder 4A) und Schmutzfilter. Pflicht in jedem Kältekreislauf. Wechseln wenn Schauglas-Feuchtigkeitsindikator gelb zeigt oder nach größeren Eingriffen.",
  147: "Rückschlagventil: Verhindert KM-Rückfluss (z.B. bei mehrstufigen Anlagen, Parallelkompressoren, nach Pump-down). Einbaurichtung beachten (Pfeil)!",
  148: "Ölregelventil: Hält den Ölstand im Verdichter-Kurbelgehäuse konstant (z.B. bei Rack-Systemen mit gemeinsamem Ölsumpf). Druckdifferenz treibt Öl vom höheren zum niedrigeren Ölstand.",
  149: "Kälteleistungsregelung: Stufenlose Drehzahlregelung (Inverter) ist am effizientesten. Stufige Regelung: Zylinderabschaltung (Hubkolben) oder Schieberventil (Schrauben). Heißgasbypass: ineffizient, aber einfach. Verdampfungsdruckregler: hält ND konstant.",
  150: "Verdampfungsdruckregler (VDR/EPR): Hält den Verdampfungsdruck auf einem Mindestwert. Wichtig bei Mehrverdampfer-Anlagen mit unterschiedlichen Temperaturniveaus (z.B. +4 °C und –20 °C an einem Verdichter).",

  // ── Kältekreislauf & Diagramme (151–235) ──────────────────────────────
  151: "Im log(p)-h-Diagramm: X-Achse = spezifische Enthalpie h [kJ/kg], Y-Achse = lg(p) [bar abs]. Der Kreisprozess ist ein Viereck: 1→2 Verdichtung (senkrecht rechts), 2→3 Verflüssigung (waagrecht links), 3→4 Drossel (senkrecht links), 4→1 Verdampfung (waagrecht rechts).",
  152: "Kälteleistung pro kg: q₀ = h₁ – h₄. Verdichterarbeit pro kg: w = h₂ – h₁. COP = q₀ / w = (h₁ – h₄) / (h₂ – h₁). Je größer q₀ und je kleiner w, desto besser der COP.",
  153: "Siedelinie (x = 0): Grenze nasser Dampf → gesättigte Flüssigkeit. Taulinie (x = 1): Grenze nasser Dampf → gesättigter Dampf. Im Nassdampfgebiet liegt das KM als Zweiphasengemisch vor. x = Dampfgehalt (0 = 100% Flüssigkeit, 1 = 100% Dampf).",
  154: "Isenthalpe Drosselung: Im log(p)-h-Diagramm senkrechte Linie nach unten (Enthalpie konstant, Druck sinkt). Physikalisch: keine Wärmeübertragung, keine Arbeit → Enthalpie bleibt, aber Temperatur und Druck fallen, Dampfgehalt steigt.",
  155: "Isentrope Verdichtung: Im log(p)-h-Diagramm entlang der Isentropenlinie nach rechts-oben. Idealer Verdichter = isentrop (adiabatisch, verlustfrei). Realer Verdichter: Linie flacher geneigt → Enthalpiezunahme größer → weniger effizient.",
  156: "Flashgas entsteht nach der Drossel (Kreuzung der Siedelinie). Im Nassdampfgebiet: Teil des Kältemittels ist bereits verdampft, leistet keine Kühlarbeit im Verdampfer. Flashgas-Anteil ≈ (h₄ – h₄') / (h₁ – h₄') wenn Unterkühlung vorhanden.",
  157: "Zweistufige Verdichtung: Bei großen Druckverhältnissen (TK-Anwendung, t₀ < –30 °C) ist einstufige Verdichtung unwirtschaftlich (Liefergrad sinkt, Endtemperatur zu hoch). Zwischenkühler kühlt Gas zwischen 1. und 2. Stufe → geringere Gesamtarbeit.",
  158: "Kaskaden-Anlage: zwei vollständig getrennte Kältekreisläufe in Serie. Hochtemperaturkreis kühlt Verflüssiger des Tieftemperaturkreises (Kaskadenwärmeübertrager). Sehr tiefe Temperaturen (< –60 °C) möglich. Verschiedene KM möglich (z.B. NH₃ oben, CO₂ unten).",
  159: "Kältemittelsammler (Receiver): Pufferspeicher für flüssiges Kältemittel hinter dem Verflüssiger. Gleicht Schwankungen in der Kältemittelmenge aus (Sommer/Winter, verschiedene Lastpunkte). Muss Dampf-Polster behalten (nie voll füllen).",
  160: "Sauggasabscheider (Akkumulator): Verhindert Flüssigkeitstropfen im Sauggas vor dem Verdichter. Flüssigkeit sammelt sich unten, Gas zieht oben ab. Wichtig bei Anlagen mit Überflutung, beim Einschalten nach längerem Stillstand.",
  161: "Innerer Wärmeübertrager (IWT/Liquid-Line-Suction-Line HX): Sauggas wird durch die wärmere Flüssigkeitsleitung vorgewärmt (mehr Überhitzung) → Flüssigkeit kühlt ab (mehr Unterkühlung). Doppelter Vorteil: sicherer Betrieb des Verdichters + mehr Kälteleistung.",
  162: "Wärmerückgewinnung: Die Verflüssigerwärme (Q_C = Q₀ + P) kann für Raumheizung, Warmwasserbereitung oder Prozesswärme genutzt werden. Effizienz steigt stark, weil die sonst nutzlos abgeführte Wärme eingesetzt wird.",
  163: "Carnot-COP = T₀ / (T_C – T₀) [in Kelvin!]. Dieser theoretische Maximalwert ist nie erreichbar, zeigt aber das Optimum. Realer COP liegt 40–70 % darunter. Maximierung des COP durch: t₀ erhöhen, t_C senken.",
  164: "EER (Energy Efficiency Ratio) = Kühlleistung / Strom­aufnahme (bei festem Lastpunkt). SEER (Seasonal EER) = Jahreswert bei Klimageräten. SCOP = saisonaler COP bei Wärmepumpen. COP und EER sind identisch, nur Bezeichnung variiert.",
  165: "Druckverluste in Rohrleitungen: Saugleitung: Druckabfall senkt Saugdruck → Verdichter muss stärker komprimieren → COP sinkt. Flüssigkeitsleitung: Druckabfall fördert Flashgas-Bildung → Probleme am TEV. Druckleitung: Druckabfall erhöht Verdichtungsarbeit.",

  // ── Wärmeübertragung & Isolierung (166–234) ───────────────────────────
  166: "Wärmedurchgangskoeffizient k = 1 / (1/α₁ + d₁/λ₁ + d₂/λ₂ + … + 1/α₂). Je dicker und besser die Dämmung (kleines λ), desto kleiner k. Bei Kühlraumwänden: k ≈ 0,2–0,3 W/(m²K). Bei Wärmeübertragern: k = 100–5000 W/(m²K).",
  167: "Wärmeleitung λ: Stoff­eigenschaft (W/(mK)). Luft: 0,025. PU-Schaum: 0,022–0,030. Stahl: 50. Kupfer: 400. Aluminium: 200. Eis: 2,2. Flüssiges Wasser: 0,6. → Metallische Wärmedurchführungen (Wärmebrücken) durch die Dämmung vermeiden!",
  168: "Wärmebrücken in Kühlraumkonstruktionen entstehen durch Metallprofile, Befestigungen oder Unterbrechungen der Dämmung. Hier kondensiert Feuchtigkeit → Schimmel, Strukturschäden. Abhilfe: thermisch getrennte Konstruktion, Dampfsperren.",
  169: "Kühlraumdämmung: Mindestdicke abhängig von Temperatur­differenz und gewünschtem k-Wert. PU-Sandwich-Elemente (Polyurethan) sind Standard. Tiefkühlraum: 150–200 mm PU. Kühlraum +4 °C: 80–120 mm PU. Dampfsperre auf der Warmseite erforderlich.",
  170: "Dampfsperre (Dampfbremse): Verhindert Einwandern von Feuchtigkeit aus der warmen Seite in die Dämmung. Bei fehlendem oder beschädigtem Dampfschutz: Kondensation innerhalb der Dämmung → Schimmel, Eisbildung, Verlust der Dämmeigenschaften.",
  171: "Türen in Kühlräumen: Dichtungsgummis, Türheizung (verhindert Einfrieren der Gummidichtung), Türvorhänge (Lamellen), Schleusenräume. Jedes Öffnen der Tür = Wärmeeintrag (Luftwechsel).",
  172: "Lüftungsanlage/Türöffnung: Einströmende warme, feuchte Luft wird im Kühlraum abgekühlt → kondensiert → Eisbildung auf Verdampfer und Wänden → Kältebedarf steigt. Kühlräume immer schnell schließen, Nachtblenden bei Vitrinen.",
  173: "Kältemittelrohrleitung (Saug­leitung) muss isoliert werden: Verhinderung von Kondensatbildung (Feuchteschäden), Vermeidung von Wärme­eintrag in das Sauggas (erhöht Überhitzung unnötig, senkt Liefergrad).",
  174: "Rohrdurchmesser­dimensionierung: Saugleitung: Druckabfall ≤ 0,5 K Sättigungstemperaturäquivalent. Druckleitung: Druckabfall ≤ 0,5 K. Flüssigkeitsleitung: Geschwindigkeit ≤ 1 m/s, kein Flashgas. Saugsteigleitungen: Ölmitnahmeöffnungen vorsehen.",
  175: "Schallschutz in Kälteanlagen: Körperschall (Vibration durch Verdichter, Ventilator) → entkoppeln (Schwingungsdämpfer, flexible Verbindungen). Luftschall → gedämmte Maschinenräume. Wichtig bei Anlagen in Wohngebäuden.",
  176: "Wärmeübertragungswiderstände in Reihe: R_ges = R_Innen + R_Wand + R_Dämmung + R_Außen. Der größte Einzelwiderstand bestimmt den Wärmefluss maßgeblich. Bei Verdampfer mit Eis ist der Eis­widerstand oft der limitierende Faktor.",
  177: "Konvektion (freie und erzwungene): Freie Konvektion = Auftrieb durch Dichteunterschiede (Kaltluft sinkt). Erzwungene Konvektion = Ventilator/Pumpe erzwingt Strömung. α_erzwungen >> α_frei → deutlich besser für Wärmeübergang.",
  178: "Strahlungswärme: Einfluss der Sonnenstrahlung auf außenliegende Kühlraumwände. Kann ΔT um 5–15 K erhöhen → erhöhter Kältebedarf. Abschätzung: Sonnenseite mit erhöhtem Transmissionszuschlag berechnen.",

  // ── Elektrotechnik & Steuerung (179–400) ──────────────────────────────
  179: "Speicherprogrammierbare Steuerungen (SPS) haben in modernen Kälteanlagen Relais-/Schützsteuerungen weitgehend ersetzt. Vorteile: einfache Programmänderungen, Diagnose­funktionen, Datenspeicherung, Fernwartung möglich.",
  180: "Thermostaten in Kälteanlagen: Kapillar-Thermostat (mechanisch, Fühler + Kapillarrohr), Elektronikregler (NTC/PT100-Fühler → digitale Anzeige, Kompensation möglich), Festkörper­thermostat. Elektronisch: präziser, wartungsärmer.",
  181: "Niederdruckpressostat: Überwacht den Saugdruck. Abschaltet bei zu niedrigem ND (Kältemittelmangel, verstopftes Expansionsorgan). Hochdruckpressostat: Abschaltung bei zu hohem HD (Verflüssigerausfall, Kältemittelfüllung zu viel).",
  182: "HD-Pressostat mit Hand­rückstellung (nicht automatisch): Ein zu hoher Hochdruck deutet auf eine schwerwiegende Störung hin (Verflüssigerproblem). Daher muss die Ursache erst behoben werden, bevor die Anlage manuell wieder freigegeben wird.",
  183: "ND-Pressostat mit Auto­rückstellung: Saugdruckabfall kann temporär sein (Anlaufphase, geringer Bedarf). Automatische Rückstellung ist zulässig, da kurzzeitig normaler Betrieb möglich.",
  184: "Differenzdruckpressostat: Misst den Unterschied zwischen zwei Drücken, z.B. HD – ND = Druckverhältnis, oder Ölpumpendruck – Kurbelwannendruck. Schützt bei zu geringem Differenzdruck.",
  185: "Steuerung einer Kälteanlage: Thermostat → Solenoidventil öffnet → Verdichter startet (verzögert). Thermostat aus → Solenoidventil schließt → Pump-down → Verdichter schaltet bei ND-Abschaltdruck ab.",
  186: "Abtausteuerung: Zeitschaltuhr oder Bedarfssteuerung (Verdampferfühler/Lufttemperaturfühler) startet Abtauung. Nach Abtauende: Abtauabschalter (Temperaturfühler am Verdampfer, typisch +10–15 °C) beendet Abtauung, Nachkühlzeit vor Lüfterbetrieb.",
  187: "Alarmfunktionen in Kälteanlagen: Temperaturalarm (Raumtemperatur zu hoch), HD-Alarm, ND-Alarm, Öldruckalarm, Motorschutzalarm. HACCP-konforme Anlagen müssen alle Alarme protokollieren und aufzeichnen.",
  188: "Sicherheitskette: Alle sicherheitsrelevanten Schalter (HD-Pressostat, ND-Pressostat, Motorschutz, Öldruck­differenzschalter, Thermistor­schutz) in Reihe im Steuerstromkreis. Öffnet einer → Verdichter-Schütz fällt ab → sofortiger Schutz.",
  189: "Frequenzumrichter (FU/Inverter): Ändert Frequenz und Spannung → regelt Motordrehzahl stufenlos. Vorteile: weicher Anlauf (kein Anlaufstrom), Energieeinsparung bei Teillast, weniger Verschleiß durch Takten.",
  190: "Motorschutz­schalter: thermischer Auslöser (Bimetall) für Überlast + magnetischer Auslöser für Kurzschluss. Einstellbar auf Motorbemessungsstrom. Muss alle drei Phasen überwachen.",
  191: "FI-Schutzschalter (RCD): Misst den Differenzstrom zwischen L und N (Summe aller Ströme muss 0 sein). Bei Fehlerstrom > 30 mA (Personenschutz) löst er in <40 ms aus. Schutz vor gefährlichen Körperströmen.",
  192: "Spannungsebenen: Niederspannung (NS) ≤ 1000 V AC. Drehstrom 400/230 V (österreichisches/europäisches Netz). Schutzkleinspannung SELV ≤ 50 V AC / ≤ 120 V DC (Steuerkreise). Hochspannung (HS) > 1000 V.",
  193: "Widerstandsmessung: Isolationsmessung mit Megohmmeter (500 V DC). Windungskurzschluss im Motor erkennbar. Motorwicklung: Widerstand zwischen Phasen gleich → kein Fehler. Stark unterschiedlich oder 0 Ω → Wicklungsschaden.",
  194: "Kondensatoren in Einphasenmotoren: Anlaufkondensator (hohe Kapazität, schaltet nach Start ab) und Betriebskondensator (bleibt in Betrieb). Defekter Kondensator → Motor läuft heiß, summt, dreht sich nicht (kein Anlaufmoment).",
  195: "Schütz für Kälteverdichter: AC-8a (manuell rückstellend) oder AC-8b (automatisch rückstellend) nach IEC. Dimensionierung nach Verdichteranlaufstrom (Gebrauchskategorie). Schütz nicht unterdimensionieren → Kontakt­verbrennen.",
  196: "Stern-Dreieck-Anlauf: Reduziert Anlaufstrom auf 1/3. Umschaltung von Stern auf Dreieck bei ca. 80–90 % der Nenndrehzahl. Zeitrelais (2–5 s) steuert Umschaltung. Schütz-Schema: Hauptschütz + Sternschütz + Dreieckschütz (Verriegelung!)",
  197: "Klemmen­bezeichnungen Motor: L1, L2, L3 = Außenleiter. U1/U2, V1/V2, W1/W2 = Motoranschlüsse. Stern: U2-V2-W2 brücken, L1→U1, L2→V1, L3→W1. Dreieck: L1→U1+W2, L2→V1+U2, L3→W1+V2.",
  198: "Phasenfolgekontrolle (Phasenfolge­relais): Überwacht die korrekte Reihenfolge der drei Phasen (L1→L2→L3). Falsches Drehen kann Verdichter beschädigen (Pumpt KM zurück). Bei Ausfall einer Phase: ebenfalls Abschaltung.",
  199: "Thermistor­motorschutz: PTC-Fühler in den Motorwicklungen, direkt am Wicklungsdraht. Reagiert auf Wicklungstemperatur schneller als externe Motorschutz­relais. Auslösung bei ca. 130–150 °C. Pflicht bei hermetischen Verdichtern.",
  200: "Elektrische Leistung: P = U × I × cos φ (Einphasen) oder P = √3 × U × I × cos φ (Dreiphasen). Blindleistung Q = U × I × sin φ. Scheinleistung S = U × I. cos φ = Leistungsfaktor (ideal 1, bei Motoren typisch 0,7–0,9).",

  201: "Kühlraum-Wärmebilanz: Q_gesamt = Q_Transmission + Q_Lüftung/Türen + Q_Kühlgut + Q_Beleuchtung + Q_Personen + Q_Maschinen + Q_Atmung (Obst/Gemüse). Alle Einzel­anteile aufaddiert = erforderliche Kälteleistung.",
  202: "Transmissions-Wärmestrom: Q = k × A × ΔT. Für jeden Wandabschnitt separat berechnen (Wände, Boden, Decke unterschiedliche k-Werte). ΔT = Temperaturdifferenz zwischen Umgebung und Kühlraum.",
  203: "Kühlgut-Wärme: Q = m × cp × ΔT (sensibel). Bei Gefrieren: zusätzlich latente Wärme (Schmelzwärme × Masse). Berechnungszeit: meist 24 h (tägliche Einbringung). Einbringtemperatur und gewünschte Lagertemperatur bestimmen ΔT.",
  204: "Luftwechselwärme beim Türöffnen: Abhängig von Türgröße, Öffnungshäufigkeit, -dauer, Temperatur- und Feuchtedifferenz. Tabellen aus EN 13861 oder Erfahrungswerte: Luftwechsel pro Stunde × Enthalpiedifferenz × Luftdichte × Raumvolumen.",
  205: "Lagertemperatur und rel. Feuchte: Fleisch 0–2 °C, 85–90 % rF. Fisch auf Eis 0 °C, 90–95 %. Obst 0–4 °C, 85–95 %. Tiefkühlware –18 °C bis –24 °C. Bananen 12–14 °C (kälteempfindlich!). Falsches Klima → Qualitätsverlust.",
  206: "Atmungswärme von Früchten und Gemüse: Biologische Oxidationsprozesse erzeugen Wärme und CO₂, auch im gekühlten Zustand. Ca. 5–50 W/t je nach Produkt und Temperatur. Berücksichtigung bei der Kühlbedarfs­berechnung wichtig.",
  207: "HACCP (Hazard Analysis and Critical Control Points): Lebensmittel­sicherheitssystem. Kritische Kontrollpunkte bei Kühltemperaturen. Kälteanlagen müssen Temperaturen dokumentieren, Alarme protokollieren. Pflicht in der Lebensmittelindustrie.",
  208: "IKV-Kurven (Iso-Kühlgut-Vorschriften): Lagertemperaturen für verschiedene Produkte. Kältebedarf berücksichtigt Kühlgut und Umgebung. In Österreich: Lebensmittelhygieneverordnung.",
  209: "Schockfroster: Schnelle Abkühlung von frisch produziertem Lebensmittel auf Tiefkühltemperatur. Verdampfertemperatur ca. –35 bis –40 °C. Vorteil: kleine Eiskristalle → bessere Lebensmittelqualität.",
  210: "Regelung Verflüssigungsdruck: Im Winter sinkt Außentemperatur → Verflüssiger wird effizienter → HD fällt zu stark → TEV bekommt zu wenig Differenzdruck → Kälteleistungseinbruch. Lösung: HD-Druckhalteventil, Ventilatordrehzahlregelung.",

  211: "Hochdruckpressostat­einstellung: Abschalt­druck typisch 25–28 bar (R-410A), 20–22 bar (R-404A), 18–20 bar (R-134a). Reset-Druck etwas niedriger. Handrückstellung verhindert Wiederanlauf ohne Fehlersuche.",
  212: "Niederdruckpressostat­einstellung: Abschaltdruck nahe dem Verdampfungsdruck bei minimaler Kühlraumtemperatur. Reset-Druck einige bar höher. Für Pump-down: Abschaltdruck = Verdampfungsdruck bei ca. t₀ – 5 K.",
  213: "Kalibrierung Drucksensoren: Manometer mit Referenzmessgerät vergleichen. Elektronische Drucktransmitter im eingebauten Zustand oder mit Kalibrier­pumpe prüfen. Abweichungen korrigieren oder Sensor ersetzen.",
  214: "Fernwartung/Gebäude­leit­technik (GLT): Kälteanlagen werden über BACnet, ModBus oder proprietäre Protokolle in übergeordnete Steuerung eingebunden. Ermöglicht Fernüberwachung, Alarmmanagement, Energieoptimierung.",
  215: "Abtau­abschalter: Fühler am Verdampfer (typisch +10–15 °C) beendet die Abtauung, sobald die Temperatur erreicht wird. Sicherheits­funktion: verhindert Überhitzen des Verdampfers und spart Energie bei bereits abgetautem Verdampfer.",
  216: "Zeitrelais: Zeitverzögerung beim Anlauf (Anlaufverzögerung, Abtauende → Lüfterbetrieb). Einschaltverzögerung: Relais zieht erst nach Ablauf der eingestellten Zeit an. Ausschaltverzögerung: Relais fällt erst nach Verzögerung ab. Wischrelais: kurzer Impuls.",
  217: "Schütz (Contactor): Elektromagnetisch betätigter Leistungsschalter. Hauptkontakte schalten den Leistungsstromkreis (Motor). Hilfskontakte steuern den Steuerstromkreis. Spule 24V, 230V oder 400V je nach Steuerkreis.",
  218: "Stern-Dreieck Zeitverzögerung: Zu kurze Zeit → Motor noch nicht auf Drehzahl → Umschaltstrom zu hoch. Zu lange Zeit → Motor unnötig lang in Stern mit reduziertem Drehmoment. Typisch: 3–7 s.",
  219: "Thyristoren/SCR in Sanftanlaufgeräten: Phasenschnitt der Spannung beim Anlauf → weicher Spannungsanstieg → Strom­begrenzung. Nach Hochlauf: Bypass-Schütz schließt (umgeht den Sanftanlauf im Betrieb, kein Verlust).",

  // ── Kühlung von Lebensmitteln und Hygiene (220–280) ───────────────────
  220: "Verdampfer in Gefriergeräten: Drahtverdampfer (direkt montiert, günstig), Lamellenver­dampfer (mit Abtauung), Bandverdampfer (eingehüllt in Gerätewand). Kühlschrank ohne Abtauung = stiller Kühler, mit = No-Frost-System.",
  221: "No-Frost-System: Erzwungene Konvektion durch Ventilator, automatische Abtauung (Heizstab + Timer). Vorteil: kein Eis, gleichmäßige Kühlung. Nachteil: mehr Energieverbrauch, Austrocknung empfindlicher Lebensmittel.",
  222: "Kühlvitrine (Offenfront): Luftvorhang trennt Kühlzone von Umgebung. Bei hoher Umgebungstemperatur und Feuchtigkeit: mehr Kondensation, mehr Abtauzyklen nötig, höherer Energieverbrauch.",
  223: "Supermarkt-Rack-System: Ein zentraler Verdichterverbund versorgt alle Kühlmöbel. Kältemittel direkt in den Möbeln (DX-System) oder über Sole als Sekundärkreis. Vorteil: zentrale Wartung, aber hohe KM-Füllmenge.",
  224: "Lebensmittelhygieneverordnung: Kühlpflicht für verderbliche Lebensmittel (Fleisch, Fisch, Milch, Eier). Lager­temperaturen gesetzlich vorgeschrieben. HACCP-Eigenkontrolle Pflicht. Kontrolle durch Lebensmittelinspektoren.",
  225: "Kühlkettenüberwachung: Lückenlose Dokumentation der Temperaturen von der Produktion bis zum Verbraucher. Data-Logger oder IoT-Sensoren. Unterbrechung der Kühlkette → rechtliche und gesundheitliche Konsequenzen.",
  226: "Tiefkühllagerung (–18 °C bis –24 °C): Mikrobakterielles Wachstum wird stark verlangsamt. Qualitätsverlust durch Oxidation und Kristall­wachstum bei längerem Lagern. Schockgefrorenes (–35 °C) ist besser als langsam gefrorenes Produkt.",
  227: "Relative Feuchte im Kühlraum: Zu trocken → Austrocknung, Gewichtsverlust, Qualitätsverlust. Zu feucht → Schimmel, Bakterien­bildung. Optimum: produktspezifisch, meist 85–95 %.",
  228: "Ethylen­gas bei Obst und Gemüse: Reifungsgas, produziert besonders von Äpfeln, Birnen. Beschleunigt Reife anderer Produkte (z.B. Tomaten, Kiwi). Daher nicht gemeinsam lagern mit empfindlichen Produkten. CA-Lagerung regelt O₂ und CO₂.",

  // ── F-Gase & Umweltrecht (401–450) ────────────────────────────────────
  401: "Energieeffizienz in der Kältetechnik verbessern: Drehzahlgeregelte Verdichter und Ventilatoren (Frequenzumrichter) sparen bei Teillast bis 50 % Energie. EEV statt TEV: präzisere Regelung. Wärmerückgewinnung: senkt Heizkosten.",
  402: "Nationale Gesetze in Österreich: KAV (Kälteanlagenverordnung) für Arbeitnehmerschutz und Anlagensicherheit. DDRV (Druckgeräteüber­wachungs­verordnung) für Druckbehälter. ASV (Arbeitsstätten­verordnung) für Klima-/Lüftungsanlagen.",
  403: "EU-Verordnungen: F-Gase-Verordnung (EU 517/2014): Phase-Down, Dichtheitskontrollen. Ozonschicht-Verordnung (EG 1005/2009): FCKW/HFCKW. Druckgeräterichtlinie (2014/68/EU): Sicherheit von Druckgeräten. Alle direkt in Österreich gültig.",
  404: "Bundesgesetzblatt (BGBl): Offizielles Kundmachungsorgan aller österreichischen Bundesgesetze und Verordnungen. Abrufbar über RIS (Rechtsinformationssystem des Bundes, www.ris.bka.gv.at). Kostenlos, verbindlich.",
  405: "ÖNORM vs. Gesetz: Gesetze/Verordnungen sind vom Staat erlassene Rechtsvorschriften – immer verbindlich. ÖNORMen sind Empfehlungen des Österreichischen Normen­instituts (ASI) – freiwillig, ABER: häufig durch Verordnungen für verbindlich erklärt.",
  406: "Freiwillig angewendete ÖNORMen gelten als Mindeststandard der Technik (Stand der Technik). Werden sie vereinbart oder vom Gesetz verwiesen, werden sie rechtsverbindlich. Abweichung dann nur mit gleichwertigem Nachweis möglich.",
  407: "EN 378 Teile 1–4: Teil 1 Grundlegende Anforderungen, Definitionen, Klassifikation. Teil 2 Konstruktion, Prüfung, Markierung. Teil 3 Aufstellungs­bedingungen. Teil 4 Betrieb, Wartung, Reparatur. Pflichtlektüre für Kältetechniker.",
  409: "Die KAV schützt sowohl die Arbeitnehmer, die mit Kälteanlagen arbeiten (Wartung, Betrieb), als auch Dritte in der Umgebung (Nachbarn, Mitarbeiter des Gebäudes) vor Gefahren durch Kältemittelaustritt oder Druckgefährdung.",
  410: "1,5 kg als Grenzwert der KAV: Unterhalb dieser Füllmenge gilt die KAV nicht. Typische Haushaltsklimageräte (< 1,5 kg R-410A) sind ausgenommen. Ab 1,5 kg: Prüfbuch, Typenschild, Abnahmeprüfung, wiederkehrende Überprüfung.",
  411: "Luft und Wasser: beide ungiftig, nicht brennbar, keine Treibhauswirkung → keine Gefährdung nach dem Schutzziel der KAV. Daher vom Geltungsbereich ausgenommen.",
  412: "Prüfbuch nach KAV: Führen, solange die Anlage in Betrieb ist. Inhalt: alle Überprüfungen mit Datum und Feststellungen. Aufbewahrung: beim Betreiber (vor Ort). Behörden (Arbeitsinspektorat) müssen jederzeit Einsicht nehmen können.",
  413: "Typenschildangaben nach KAV (§10): Errichter, Baujahr, KM-Art und Füllmenge, Kälteleistung, max. Betriebsdruck je Druckstufe. Müssen dauerhaft lesbar am Gerät angebracht sein.",
  414: "Jährliche Dokumentation: Überprüfungsergebnis = Aussage, ob die Anlage sicherheitstechnisch weiterhin betrieben werden kann. Muss von einer fachkundigen Person unterzeichnet werden.",
  415: "Pflicht-Sicherheitseinrichtung je Druckstufe: Sicherheitsventile oder Berstscheiben (mechanisch) oder Überdruckschalter (elektrisch). Schmelzpfropfen allein nicht ausreichend, da sie nicht für alle Druckgefahren ansprechen.",
  416: "Absperrbare Sammler oder Verdampfer können durch Erwärmung (Sonneneinstrahlung, Feuer) zum Druckbehälter werden → Sicherheitsventil oder Überdruckschalter ist dann zwingend.",
  417: "Druckprobe nach KAV: 1,5-facher max. Betriebsdruck, mindestens 1,5-facher Sattdampfdruck bei 40 °C. Prüfmedium: Stickstoff (kein Sauerstoff!). Dichtheits­prüfung und Funktionsprüfung der Sicherheitseinrichtungen.",
  418: "Typenschild bleibt dauerhaft an der Anlage. Muss alle Angaben nach §10 KAV enthalten. Bei Änderungen der Anlage (z.B. neues KM, Füllung geändert) muss Typenschild aktualisiert werden.",
  419: "Lüftungsvorschriften KAV: Kältemittel schwerer als Luft (z.B. R-134a, R-404A) → boden­nahe Absaugung. Kältemittel leichter als Luft (NH₃) → decken­nahe Absaugung. Maschinenkeller: künstliche Lüftung Pflicht, außer < 10 kg Gruppe 1.",
  420: "Elektrische Anlage im Kältemaschinenraum: nach ÖVE/ÖNORM (Elektrotechnikverordnung). Beleuchtung und Lüftung müssen unabhängig voneinander von außen schaltbar sein, auch bei abgeschalteter Kältemaschine.",
  421: "Probe vor Inbetriebnahme: Dichtheits­prüfung und Funktionsprüfung der Sicherheitseinrichtungen durch eine befugte, fachkundige Person. Dokumentation im Prüfbuch.",
  422: "Wiederkehrende Überprüfung nach §22 KAV: Umfang: alle sicherheitstechnischen Teile (Sicherheits­einrichtungen, Abdeckungen, elektrische Anlage, Korrosion, Rohrbefestigung). Keine Druckprobe nötig, außer nach größeren Reparaturen.",
  423: "Gefährdungen von Kälteanlagen: mechanisch (Druck, bewegliche Teile), thermisch (Verbrennungen durch heiße Teile, Erfrierungen durch Kältemittelspritzer), chemisch (Toxizität NH₃, Zersetzungsprodukte), elektrisch, Brandgefahr (A2L/A3-KM), Lärmschäden.",
  424: "Arbeitsstättenverordnung (ASTV): gilt für alle Arbeitsstätten in Österreich. Anforderungen an Raumtemperatur, Lüftung, Beleuchtung, Lärm. Klima-/Lüftungsanlagen müssen regelmäßig gewartet und deren Einwandfreiheit dokumentiert werden.",
  425: "ASTV (Bundes-Arbeitsstättenverordnung) und B-ASTV (Bunde­sdienststellen): für Kälte-/Klimatechnik kaum Unterschiede. Beide fordern regelmäßige Überprüfung und Dokumentation der Klima-/Lüftungsanlagen.",
  426: "§13 ASTV: mindestens 1× jährlich (max. 15 Monate zwischen zwei Prüfungen). Nach größeren Instandsetzungen oder Änderungen sofort. Bei begründeten Zweifeln am ordnungsgemäßen Zustand ebenfalls sofort.",
  427: "Überprüfung nach §13 ASTV umfasst: Sichtprüfung aller zugänglichen Teile, Funktionsprüfung (Luftmengen, Temperaturen), Wartungsprüfung (Filter, Zustand), Reinigung, Überprüfung der Aufzeichnungen/Protokolle.",
  428: "DGÜW-V regelt Art und Häufigkeit der wiederkehrenden Prüfungen von Druckbehältern im Betrieb. Unterscheidet nach Druckinhaltsprodukt und Fluidgruppe (gefährlich/nicht gefährlich).",
  429: "Druckinhaltsprodukt = PS [bar] × V [Liter]. Dimensionslose Zahl zur Einstufung der Gefährdung des Druckbehälters. Höheres Produkt = mehr Energie gespeichert = höheres Gefahrenpotenzial.",
  430: "Anlagen mit hohem Gefahrenpotenzial: erste Betriebsprüfung durch Kesselprüfstelle (notifizierte Stelle). Periodische Prüfungen häufiger als bei niedrigem Potenzial. Kostenintensiver, aber höhere Sicherheit.",
  431: "Fluidgruppe 1 (gefährliche Fluide = brennbar, explosiv, akut toxisch) + PS × V > 300 → hohes Gefahrenpotenzial. Fluidgruppe 2 (alle anderen, z.B. Wasser, Luft) + PS × V > 1000 → hohes Gefahrenpotenzial.",
  432: "Klassifikation nach KAV: ≤ 700 = Kleinanlage (einfaches grünes Prüfbuch). > 700 bis ≤ 3000 = Kleingewerbeanlage. > 3000 bis ≤ 6000 = Großgewerbeanlage. > 6000 = Industrieanlage (aufwändigste Anforderungen).",
  433: "Grenzwerte: F-Gruppe 1 (NH₃, Propan): > 300 → hoch. F-Gruppe 2 (R-134a, CO₂): > 1000 → hoch. Diese Grenzwerte bestimmen, ob eine notifizierte Stelle für die Erstprüfung erforderlich ist.",
  434: "Notifizierte Stelle (Kesselprüfstelle): amtlich anerkanntes Prüfinstitut (z.B. TÜV, OVE). Für hohe Gefahrenpotenziale zwingend. Kosten und Terminaufwand sind höher, aber Pflicht.",
  435: "Niedriges Gefahrenpotenzial: Betreiber oder seine bevollmächtigte fachkundige Person kann die Prüfung selbst durchführen. Prüfung muss trotzdem dem Umfang der DGÜW-V entsprechen und im Prüfbuch dokumentiert werden.",
  436: "Ozonschicht-Verordnung EG 1005/2009 regelt alle Stoffe mit ODP > 0: FCKW (R-11, R-12, R-113, R-115), HFCKW (R-22, R-141b), Halone. Verbot von Produktion und Inverkehrbringen. Nur Rückgewinnung und Wiederverwertung erlaubt.",
  437: "ODP-Stoffe: FCKW (vollhalogeniert, R-12) haben ODP bis 1,0. HFCKW (R-22) haben ODP 0,055. HFKW (R-134a, R-404A): ODP = 0 (kein Chlor). Natürliche KM: ODP = 0. Ziel: alle ODP-Stoffe ersetzen.",
  438: "Dichtheitskontrollen nach OzonschichtVO: ≥ 3 kg: jährlich. ≥ 30 kg: halbjährlich. ≥ 300 kg: vierteljährlich. Diese Intervalle gelten ZUSÄTZLICH zu den Anforderungen der F-Gase-VO. Hermetisch geschlossene Systeme < 6 kg: ausgenommen.",
  439: "Ozonschicht-VO: Kein Sonderwortlaut zu Leckageerkennungssystemen – daher kein verlängertes Intervall. Nur die F-Gase-VO sieht bei installiertem Leckageerkennungssystem eine Verdopplung des Intervalls vor.",
  440: "Hermetisch geschlossene Systeme: Bei ≥ 6 kg müssen sie trotz hermetischer Bauweise kontrolliert werden (außerhalb des Ausnahme­bereichs < 6 kg). Die Dichtheitsanforderung gilt, weil auch hermetische Systeme lecken können.",
  441: "Phase-Down-Ziel (F-Gase-VO EU 517/2014): HFKW-Menge in CO₂-Äquivalenten bis 2030 auf 21 % des Ausgangswertes (2015) reduzieren. Umsetzung durch Quotensystem für Hersteller und Importeure.",
  442: "F-Gase-VO erfasst alle H-FKW (fluorierte Kohlenwasserstoffe), PFKW (perfluoriert) und SF₆. Neuere Revisionen beziehen auch HFO (R-1234yf, GWP = 4) und manche natürliche KM ein, jedoch mit anderen Regelungen.",
  443: "OzonschichtVO und F-Gase-VO schließen sich nicht aus: R-22 fällt unter die OzonschichtVO (ODP > 0). HFKW fallen unter die F-Gase-VO (ODP = 0, aber GWP hoch). Manche Stoffe nur unter eine Verordnung.",
  444: "HFO (Hydro­fluoroolefine): R-1234yf (Kfz-Klimaanlagen), R-1234ze (Chillers). GWP < 10. ODP = 0. A2L-Klasse (schwer entflammbar). Werden zunehmend als Ersatz für R-134a und R-410A eingesetzt.",
  445: "Hermetisches System nach F-Gase-VO: Alle KM-führenden Verbindungen dauerhaft gelötet/geschweißt. Leckagerate < 3 g/Jahr (Fabrikstest). Ausnahme: Wartungszugänge (Schrader-Ventile) erlaubt. Vorteil: seltenere Dichtheitskontrollen.",
  446: "Phase-Down-Mechanismus: Quotenkontingente für HFKW in Tonnen CO₂-Äquivalent. Hersteller/Importeure können Quoten handeln. Ziel: Anreiz für Investition in Technologien mit niedrigem GWP.",
  447: "500 t CO₂-Äquivalent als Schwellenwert für Leckageerkennungssystem (F-Gase-VO). Beispiel: R-404A (GWP = 3922): 500/3,922 ≈ 128 kg Füllmenge. Bei R-32 (GWP = 675): 500/0,675 ≈ 741 kg.",
  448: "Leckageerkennungssystem (F-Gase-VO): Verdoppelt das Dichtheits­prüfintervall. Zum Beispiel: Bei > 300 t CO₂-Äq. normalerweise vierteljährlich → mit LES halbjährlich. Das System muss regelmäßig gewartet werden.",
  449: "Jährliche Prüfung des Leckageerkennungssystems ist gesetzlich vorgeschrieben. Dokumentation im Prüf- und Anlagenbuch. Funktionstest: Sensor auf KM-Dampf reagieren lassen (Test­gas oder zertifizierte Testmethode).",

  // ── EN 378 & Sicherheit (451–500) ─────────────────────────────────────
  451: "Ab 01.01.2020: Verbot des Einsatzes von KM mit GWP ≥ 2500 (R-404A, R-507A) für neue Anlagen. Für Wartung: bis 31.12.2029 nur noch recyceltes/aufbereitetes KM (bei > 40 t CO₂-Äq.), danach vollständiges Verbot.",
  452: "Zertifizierungsverordnung EU 303/2008: Alle Personen, die F-Gase handhaben (Einbau, Wartung, Dichtheitskontrolle, Rückgewinnung) müssen Personen­zertifikat besitzen. Unternehmen: Unternehmens­zertifikat.",
  453: "Personen­zertifikat ist personenbezogen, nicht übertragbar. Gilt für die in der Zertifizierungs-VO genannten Tätigkeiten an Anlagen mit F-Gasen. Kein Zertifikat → Tätigkeit an F-Gas-Anlage verboten.",
  454: "Unternehmens­zertifikat: Nachweis, dass ausreichend viele zertifizierte Personen beschäftigt sind und die notwendigen Werkzeuge/Verfahren vorhanden sind (Rückgewinnungsgerät, Leckdetektor, Vakuum­pumpe etc.).",
  455: "In Österreich: Positive Lehrabschluss­prüfung Kälte­anlagentechnik gilt als Äquivalent zur theoretischen Prüfung für das Personenzertifikat. Zusätzlich: Antrag bei der Wirtschaftskammer/Innung, Gebühr, Ausstellung des Zertifikats.",
  456: "Unternehmens­zertifikat in Österreich: Antrag an BMAW (Bundesministerium für Arbeit und Wirtschaft). Nachweis: ausreichend zertifizierte Mitarbeiter, Ausrüstungsliste (Werkzeuge und Messgeräte). Periodische Erneuerung.",
  457: "Unterschied: Personenzertifikat = F-Gase-rechtliche Voraussetzung für den Umgang mit F-Gasen. Lehrabschluss­prüfung = Berufsabschluss, bescheinigt umfassende technische Kompetenz. Nach KAV ist Fachkunde (Lehrabschluss) gefordert, nicht nur das F-Gas-Zertifikat.",
  458: "KAV-Gruppen: Gruppe 1 (z.B. R-134a, CO₂, FCKW): nicht brennbar, gering toxisch → geringstes Gefahrenpotenzial. Gruppe 2 (NH₃): entzündbar oder toxisch → mittleres Potenzial. Gruppe 3 (Propan, Butan): brennbar (UEG < 3,5 %) → höchstes Potenzial.",
  459: "Druckgeräte-Fluidgruppe unterscheidet sich von KAV-Gruppe: F-Gruppe 1 = explosiv/entzündbar/akut toxisch. F-Gruppe 2 = alle anderen. Relevant für die Prüfanforderungen nach DGÜW-V.",
  460: "ISO 817 Klassifikation: Buchstabe = Toxizität (A = NOAEL ≥ 400 ppm, B = NOAEL < 400 ppm). Zahl = Brennbarkeit (1 = keine, 2L = schwer, 2 = mäßig, 3 = leicht). Prüflingsfrage: Klasse von NH₃? → B2L.",
  461: "A1 (z.B. R-134a, R-513A, CO₂): sicherste Klasse. A2L (R-32, R-1234yf): geringe Brenngefahr (Mindestzünd­energie > 1000 mJ), bedingte Sicherheits­auflagen. A3 (R-290/Propan): leicht entflammbar → strenge Auflagen (Füllmenge, Zündquellen). B2L (NH₃): toxisch, aber schwer entflammbar.",
  462: "ADR-Handwerker­befreiung (Absatz 1.1.3.1): Keine Schulung, kein ADR-Fahrzeug erforderlich bei Transporten im Zusammenhang mit der Haupt­tätigkeit bis zu bestimmten Mengengrenzen. 1000-Punkte-Regel muss eingehalten werden.",
  463: "Stoffe unter Handwerkerbefreiung: verdichtete Gase (O₂, N₂, Ar), verflüssigte Gase (Propan), Lösemittel, Klebstoffe, Reiniger. Kältemittel-Druckgasflaschen (z.B. R-410A) fallen je nach Klassifikation auch darunter.",
  464: "1000-Punkte-Regel: Summe der Gefahrenpunkte (je Stoff: Nettomasse [kg] × Faktor aus ADR-Tabelle) ≤ 1000. Wenn Summe ≤ 1000: Handwerkerbefreiung möglich (zusätzlich Mengengrenzen je Stoff beachten).",
  465: "Handwerkerbefreiung gilt nur, wenn der Mitarbeiter die Stoffe selbst transportiert, um sie selbst einzusetzen (nicht zum Lagern oder Weitergeben). Lieferung an Kollegen oder Zustellung auf Bestellung eines Dritten = keine Befreiung.",
  466: "Interne Versorgung (Lager → Baustellen): Transport ist Bestandteil der gewerblichen Tätigkeit → keine Handwerkerbefreiung. Vollständige ADR-Anforderungen gelten: Fahrzeugkennzeichnung, Transportpapiere, Schulung.",
  467: "Vorschriften bei Handwerkerbefreiung: Ladegut sichern, Behälter dicht verschlossen, vor Wärme geschützt. Feuerlöscher (2 kg Pulver) mitführen. PSA (Handschuhe, Warnweste). Beipackzettel/Sicherheitsdatenblatt mitführen.",
  468: "Grünes Prüfbuch: Einfachere Dokumentation für Kleinanlagen (Druckinhaltsprodukt ≤ 700). Blaues Prüfbuch: für alle Anlagengrößen geeignet, enthält mehr Felder für komplexere Dokumentation. Blaues kann immer verwendet werden.",
  469: "Abgeschlossenes Prüfbuch: Letzten Eintrag vermerken 'Prüfbuch voll, Fortsetzung in neuem Prüfbuch'. Altes Prüfbuch bleibt beim neuen aufbewahrt (lückenlose Dokumentations­pflicht). Kunden schriftlich informieren und Angebot für neues Prüfbuch übermitteln.",
  470: "PS (Max. zulässiger Druck): Vom Hersteller für jede Druckstufe festgelegt. Entspricht dem Ansprechdruck des Sicherheitsventils. Betriebsdruck im normalen Betrieb liegt deutlich darunter.",
  471: "Unterweisung nach KAV: vor Inbetriebnahme und bei wesentlichen Änderungen. Themen: Bedienung, Sicherheitseinrichtungen, Verhalten bei Störungen, Erste Hilfe. Dokumentation im Prüfbuch (Datum, Teilnehmer, Themen, Unterschriften).",
  473: "Dampfpolster in KM-Flaschen: Bei 20 °C: ca. 80 % Flüssigkeit, 20 % Gasraum. Bei Temperaturanstieg dehnt sich Flüssigkeit aus (MEHR als das Volumen der Flasche zulässt, wenn voll) → Berstgefahr. Daher: max. Füllgrad einhalten.",
  474: "KM-Spritzer in die Augen: Sofort 15 Minuten mit fließendem Wasser spülen, Augenlider offenhalten, sofort zum Arzt. Bei Hautkontakt: Kleidung entfernen, Haut mit Wasser spülen. PSA (Schutzbrille, Handschuhe) ist Pflicht bei KM-Arbeiten.",
  475: "Klimafilter können mit Pilzen, Bakterien, Feinstaub, Pollen belastet sein. Bei Wechsel: FFP2-Maske (Schutz vor biologischen Aerosolen), Schutzbrille, Einweg-Handschuhe. Filter in Plastiksack entsorgen.",
  476: "Sicherheitsdruckschalter: Anschluss min. NID 4 mm (EN 378). Kapillarrohre (NID ≤ 2 mm) können durch Kältemittelöl oder Fremdkörper verstopfen → Schalter reagiert nicht mehr auf Überdruckbelastung → schwerwiegende Gefahr.",
  477: "Kältetechnisches Personal trägt Verantwortung gemäß KAV, F-Gase-VO, Arbeitnehmerschutz und Berufsrecht. Fehler können zu Personen­schäden, Umwelt­verschmutzung und rechtlichen Konsequenzen führen. Sorgfaltspflicht ist gesetzlich verankert.",
  478: "Vollklimaanlage: alle 4 Klimatisierungs­funktionen (Heizen, Kühlen, Befeuchten, Entfeuchten, Filtern). Teilklima: nur ein Teil der Funktionen (z.B. nur Kühlen/Entfeuchten). Komfortanforderungen bestimmen den Anlagentyp.",
  479: "Split-Klimaanlage: Trennung Innen/Außen ermöglicht ruhigeren Betrieb im Innenraum (Verdichter außen). Kupferrohre transportieren flüssiges/gasförmiges KM zwischen den Einheiten.",
  480: "Drosselventil im Außengerät: Einspritz­geräusche (Verdampfen durch Drossel) entstehen außen → leiseres Innengerät. Bei Einrohrsystem wäre das Drosselorgan innen → Lärm im Raum.",
  481: "4-Wege-Ventil: Funktionsprinzip: Steuert, welches Gerät als Verflüssiger und welches als Verdampfer arbeitet. Im Kühl­betrieb: Heißgas → Außengerät. Im Heiz­betrieb: Heißgas → Innen­gerät.",
  482: "Multi-Split: 1 Außengerät, mehrere Innengeräte (jeweils eigenes Kupferleitungs­paar). Einfacherer Aufbau als VRF, aber weniger effizient bei vielen Geräten. Jedes Innen­gerät läuft unabhängig.",
  483: "VRF/VRV: Stufenlose Leistungsregelung durch Inverter-Verdichter und Elektronische Expansionsventile in jedem Innen­gerät. Heizen und Kühlen gleichzeitig (Wärmerückgewinnung). Sehr effizient. Komplex in Auslegung und Inbetriebnahme.",
  484: "Siphon-Kondensatablauf verhindert Gerüche und Keime aus der Kanalisation durch den Geruchsverschluss (Wasserverschluss). Ohne Siphon: Legionellen, Schimmelsporen oder Kanalisationsgas gelangen in den Luftstrom des Geräts.",
  485: "Präzisionsklimaschrank: Für Server­räume/Rechenzentren kritisch → höchste Verfügbarkeit, enge Toleranzen für Temperatur (±0,1 K) und Feuchte (±0,5 % rF). Redundante Anlagen (N+1) für Ausfall­sicherheit.",
  486: "Inverter-Split-Klimaanlage: Regelung hält Verdampfungs­druck (Saugdruck) konstant durch Drehzahl­anpassung. Kältemittel­mangel → Regelung erhöht Drehzahl → Raum wird nicht mehr ausreichend gekühlt → steigende Ausblastemperatur als Indikator.",
  487: "Leitungslänge ist begrenzt durch: Druckverlust in der Saugleitung (senkt t₀ → schlechterer COP), Druckverlust in der Flüssigkeitsleitung (Flashgas-Bildung), Öl­rückführung (Öl muss zum Verdichter zurück). Herstellerangaben sind verbindlich.",
  488: "Wärmepumpe: Same Kreislauf wie Kältemaschine, aber die Nutz­wärme wird am Verflüssiger abgenommen (nicht die Kälte am Verdampfer). JAZ (Jahresarbeits­zahl) = Jahresheizenergie / Jahres­strombedarf. Typisch: 2,5–4.",
  489: "Luft-Wasser-WP: Außenluft als Wärme­quelle. Erdsonde (Geothermie): konstante Temperaturen (8–12 °C), hohe JAZ. Grundwasser-WP: sehr stabile Temp., aber Genehmigung nötig. Abwasser-WP: städtische Abwässer als Wärme­quelle (konstant warm).",
  490: "Luft-Wasser-WP Vorteil: niedrigste Investitions­kosten, überall installierbar. Nachteil: Der Bedarf ist im Winter am höchsten, aber die Effizienz am niedrigsten (niedrige Außentemperatur). Bivalenter Betrieb mit Zusatz­heizung empfohlen.",
  491: "Grundwasser-WP: Jahresmittel­temperatur Grundwasser 8–13 °C (stabil) → hohe, konstante JAZ. Genehmigung: Wasserrechts­verfahren erforderlich, nicht überall verfügbar (Wasserschutz­gebiete). Höhere Investition (Brunnen).",

  // ── Montage & Inbetriebnahme (492–550) ────────────────────────────────
  492: "Vor Inbetriebnahme: Druckprüfung (Stickstoff, 1,5× max. Betriebsdruck), Dichtheitsprüfung, Evakuierung (Trockenvakuum < 300 μm Hg), Kältemitteleinleitung, Ölstand prüfen, Schutzeinrichtungen funktionsprüfen, Erstdokumentation.",
  493: "Druckprüfung mit Stickstoff: Stickstoff ist inert (nicht reaktiv) und günstig. NIEMALS mit Sauerstoff prüfen (Explosionsgefahr mit Öl). Druckhalte­test: 24 h bei Prüfdruck, kein Druckabfall = dicht.",
  494: "Evakuierung: Vakuumpumpe erzeugt Tief­vakuum (< 300 μm Hg ≈ 0,4 mbar). Ziel: Entfernung von Wasser (Restfeuchte senken) und Luft (nicht kondensierbare Gase). Mindest-Evakuier­dauer: je nach Anlage­größe 1–4 h, manchmal länger.",
  495: "Befüllung der Anlage: Flüssig-Einfüllung über die Flüssigkeitsleitung (zeotrope Gemische immer flüssig!). Gas-Einfüllung über Saugseite zum Anlauf­test. Füllmenge nach Typenschild/Auslegung. Überfüllung → HD-Pressostat, Unterfüllung → ND-Pressostat.",
  496: "Erstinbetrieb­nahme: Sicherheits­einrichtungen auf richtige Einstellung und Funktion prüfen (HD/ND-Pressostat, Motorschutz, Thermistor). Ölstand, Öltemperatur, Überhitzung, Unterkühlung messen. Betriebsdaten aufzeichnen.",
  497: "Rohrleitung dimensionieren: Geschwindigkeit Sauggas: 4–12 m/s (Ölmitnahme). Druckgas: 8–18 m/s. Flüssigkeit: 0,5–1,5 m/s. Zu groß: Öl bleibt liegen. Zu klein: hoher Druckverlust → schlechter COP.",
  498: "Gefälle in Rohrleitungen: Saug­leitung zum Verdichter: Gefälle weg vom Verdichter → Kondensations­schutz. Horizontal­leitungen: kleines Gefälle in Strömungs­richtung. Ölmitnahme­öffnungen in Steigleitungen (unterer Teil der Leitung).",
  499: "Werkzeuge für Kälte­techniker: Rohrbiegegerät, Rohrschneider, Bördelgerät, Vakuumpumpe, Kältemittel-Rückgewinnungsgerät, Manifold (Kältemittel-Service­station), elektronischer Leckdetektor, Thermometer (Kontakt und Infrarot).",
  500: "Kupferrohr­verbindungen: Hart­löten (> 450 °C, Silber-Phosphor-Lot) für alle KM-Leitungen. Weich­löten nur für Wasser/Heizung (< 450 °C). Bördelverbindungen für abnehmbare Verbindungen (Manometer­anschlüsse). Press­fittings nur für Wasser.",
  501: "Kupferrohr in der Kälte­technik: Harte und weiche Qualität verfügbar. Innen sauber und ölfrei (für Kälte­technik geeignete Qualität EN 12735-1/-2). Nicht mit mineralöl­behafteten Rohren für HFKW-Anlagen verwenden.",
  502: "Rohre biegen: Rohrbiegegerät mit passendem Dorn verwenden. Mindest­biege­radius einhalten (> 2,5× Außendurchmesser). Knicken und Quetschen durch korrektes Biegen verhindern → Druckverlust und Ermüdungs­brüche vermieden.",
  503: "Rohrhalterungen: Schwingungsgedämpfte Schellen für Verbindungen mit Verdichter (Körperschall). Ausreichend Abstand zwischen Saugleitung und Heißgasleitung um Wärmeeintrag zu vermeiden. Dehnungsbogen für thermische Längenänderung.",
  504: "Befestigung Außengerät: Wandkonsolen (Schall­schutz), Standfüße (Ausrichtung, Drainage), ausreichend Luft­raum für Ansaugung und Ausblasrichtung. Abstände nach Hersteller­vorschrift einhalten.",
  505: "Sicherheits­absperrventile an Verdichterseite: Schrader-Ventile für Messanschlüsse. Absperr­hähne (Kugelventile oder Rota­ventile) für Wartungsarbeiten. Immer im offenen Zustand während des Betriebs!",
  506: "Kältemittel­schläuche: Hochdruck­schlauch (rot) und Niederdruck­schlauch (blau) am Manifold. Mittlerer Schlauch (gelb/grün): Vakuumpumpe oder KM-Flasche. Vor Öffnen von Schrader-Ventilen: Luft aus Schläuchen evakuieren!",
  507: "Manifold (Kältemittel-Servicestation): HD-Manometer (rot), ND-Manometer (blau), Absperr­hähne und Verbindungs­schläuche. Ermöglicht: Druck messen, KM nachfüllen, Vakuum ziehen, KM rückgewinnen.",
  508: "Rückgewinnung vor Öffnen des Kreislaufs: Kältemittel MUSS mit Rückgewinnungs­gerät in eine Flasche gesaugt werden. Einfaches Ablassen in die Atmosphäre ist verboten (F-Gase-VO, Strafbarkeit).",
  509: "Inbetrieb­nahme nach Instandsetzung: Neues Öl einfüllen (POE/PAG/AB je nach KM), neue Trockner, Kreislauf evakuieren (> 2 h), neues KM einfüllen, Betriebsdaten prüfen.",
  510: "Kältemittel­füllmenge prüfen: Schauglas beobachten (blasenfrei = ausreichend), Überhitzung messen (7–8 K TEV), Unterkühlung messen (3–8 K), HD/ND-Drücke mit Sollwerten vergleichen. Waage­methode für genaue Füllmenge.",
  511: "Wechselstrom (AC): Sinusförmige Spannung, Richtung wechselt 50×/s (50 Hz). Effektivwert = 0,707 × Spitzenwert. 230 V Nenn­spannung = 230 V Effektivwert, Spitzen­wert = 325 V.",
  512: "Elektrische Widerstand: R = U/I (Ohmsches Gesetz). Einheit: Ohm (Ω). Widerstand hängt von Material, Länge, Querschnitt und Temperatur ab. Leiter (Kupfer, Aluminium) haben kleinen R, Isolatoren (PVC, Gummi) großen R.",
  513: "Induktivität in Wechselstromkreisen: Spulen wirken als induktiver Widerstand (X_L = 2πfL). Bei 50 Hz: Motorwicklungen haben induktiven Anteil → cos φ < 1 → Blindleistung. Kondensatoren kompensieren: X_C = 1/(2πfC).",
  514: "Transformatoren: Übersetzt Spannungen (Primär/Sekundär). Steuertransformator: 400 V → 230 V oder 24 V. Trenntransformator: galvanische Trennung (Schutztrennung). Leistung: VA.",
  515: "Klemmen­belegung im Schaltschrank: Beschriftung Klemmen nach Schaltplan. DIN-Schiene, Reihenklemmen. Jede Klemme nummeriert. Schutzleiter immer grün-gelb. Brücken nur wo erlaubt. Luft­abstände einhalten.",
  516: "Leitungs­querschnitt: Zu klein → Überhitzung, Brand­gefahr, Spannungsabfall. Mindest­querschnitt nach Schutz­orga­nennstrom, Verlegebedingung (Rohr/frei), Länge, zulässigem Spannungsabfall (max. 3 % ÖVE).",
  517: "Sicherungs­automat (LS-Schalter): Schutz gegen Überlast (thermisch) und Kurz­schluss (magnetisch). Schalt­handlung (Ein/Aus) möglich. Strom­wert auf Klemme stellt nur thermischen Auslöser ein.",
  518: "Kabelkanal und Kabelbündel: Induktions­freie Verlegung Steuer- und Leistungs­kabel trennen (elektro­magnetische Störungen). Kabelbündel: Strom­belastbarkeit reduziert nach Bündelungs­faktor.",
  519: "Potenzial­ausgleich: Alle leitfähigen Teile (Gehäuse, Rohrleitungen, Maschinengestell) müssen mit dem Schutz­leiter (PE) verbunden sein. Verhindert Berührungs­spannung.",
  520: "Fehlersuche an elektrischen Anlagen: 1. Schaltplan studieren. 2. Sicherungen/FI prüfen. 3. Steuerstromkreis durchmessen (Spannung an Schütz­spule, Öffner/Schließer der Sicherheitskette). 4. Leistungskreis messen. 5. Sensoren prüfen.",
  521: "Erdungs­messung: Messung des Erdungs­widerstands mit Erdungs­messgerät. Anforderungen: < 5 Ω für Haupt­erdung, < 100 Ω für Blitz­schutz­erdung. Wichtig bei Außenanlagen und Erdsondenanlagen (WP).",
  522: "Spannungs­messung: Zwischen Außenleiter und Neutralleiter: 230 V (Sternspannung). Zwischen zwei Außenleitern: 400 V (Leiterspannung/Dreieck­spannung). Zwischen PE und N: < 1 V (im korrekten Betrieb). Über­mäßige N-PE-Spannung = Problem.",
  523: "Frequenz 50 Hz: Bedeutet 50 Schwingungen pro Sekunde. Für Motor­drehzahl: n = 60 × f / p (p = Polpaar­zahl). Bei 50 Hz und 2 Polpaaren: n = 1500 U/min (Synchron). Asynchronmotor: n etwas kleiner (Schlupf).",
  524: "Wenn Strom und Spannung in Phase: cos φ = 1 → nur Wirk­leistung, keine Blind­leistung. Ideal­fall. Bei ohmschem Widerstand (Heiz­stab) ist cos φ = 1. Bei Motoren immer cos φ < 1.",
  525: "Leistungs­faktor cos φ: 1 = optimal (rein ohmsch). < 1 = Blind­strom vorhanden (induktiv oder kapazitiv). Schlechter cos φ belastet das Netz (mehr Scheinleistung für gleiche Wirkleistung). EVU kann Blindstrom verrechnen.",
  526: "Drehstrom (Dreiphasenwechselstrom): 3 Spannungen je 230 V, je 120° phasenverschoben. Erzeugt stets gleichmäßiges Drehfeld → Asynchronmotor kann direkt anlaufen. Leistung: P = √3 × U_L × I × cos φ.",
  527: "Außenleiter­spannung 400 V = zwischen zwei Außenleitern (z.B. L1 und L2). Stern­spannung 230 V = zwischen einem Außenleiter und Sternpunkt (N). Verhältnis: U_L = √3 × U_N → 400 = √3 × 230 ≈ 1,732 × 230.",
  528: "Biologische Wirkungen des Stroms: 1 mA = wahrnehmbar. 10 mA = loslassen unmöglich (Muskel­krampf). 30 mA = Atemlähmung möglich. 80 mA = Kammerflimmern. Ab ca. 100 mA: hohe Todeswahrscheinlichkeit. Gleichstrom etwas weniger gefährlich als AC.",
  529: "Schutzmaßnahme FI (RCD 30 mA): Soll Strom unter der Schwelle für Herzkammerflimmern (ca. 50–80 mA) abschalten. 30 mA in ≤ 40 ms → Person überleben. Wechselstrom ab 50 V bereits gefährlich (bei > 10 mA an 50 Hz).",
  532: "Vor jeder Benutzung: Stecker, Kabel­einführung, Knickschutz auf mechanische Beschädigungen prüfen. Beschädigte Werkzeuge sofort außer Betrieb nehmen → Reparatur durch Elektro­fachkraft. Keine provisorischen Reparaturen (Klebeband)!",
  534: "Kurzschluss: sehr hoher Strom → enorme Wärmeentwicklung → Brand­gefahr. Sicherung/LS löst aus. Im Schrank: Lichtbogen­bildung möglich. Niemals Sicherung überbrücken → Überhitzung und Brand.",
  535: "Körperschluss: Berührung metallischer Gehäuseteile führt zu Strom­fluss. Bei Schutzklasse I: Strom über PE abgeleitet → Sicherung/FI löst aus. Ohne Schutz: Berührungs­spannung → Elektrounfall.",
  536: "Erdschluss: Leiter berührt Erde oder geerdetes Gehäuse direkt. Im TN-Netz: Kurzschluss zwischen Phase und Erde → hoher Strom → Sicherung löst aus.",
  537: "Isolations­fehler: verminderte Isolierung durch Beschädigung, Feuchtigkeit, Alterung. Erhöhter Kriech­strom möglich. FI-Schutz­schalter erkennt Isolation­fehler bevor Sicherung anspricht.",
  538: "Leiterschluss: zwei Leiter, die unter unterschiedlichen Spannungen stehen, berühren sich durch Isolation­schaden. Bei Phase-Phase: Kurzschluss. Bei Phase-N: Kurzschluss. Bei Phase-PE: Körper­schluss.",
  539: "Schutz­leiter (PE): Verbindet alle leitfähigen Teile mit Erde. Im Schuko­stecker: Mitte. Farbe grün-gelb. Niemals unterbrechen, wechseln oder als Neutral­leiter verwenden. Im Schutzkontakt­stecker ist PE der längste Kontakt.",
  541: "Schutz­klassen-Unterschiede: Klasse I (Haushalts­gerät mit Schuko) → braucht PE. Klasse II (Körper doppelt isoliert, kein PE-Anschluss, z.B. Haar­föhn, Rasier­er) → sicherer, aber nur wenn Doppel­isolierung intakt. Klasse III: Spannungen < 50 V.",
  545: "Schutz­isolierung (Klasse II): Doppelte oder verstärkte Isolierung eliminiert die Notwendigkeit eines Schutz­leiters. Kein PE-Kontakt. Typisch: Elektro­klein­geräte, Lade­teile, Adapter. Nachteil: bei Schaden an der Isolierung gefährlicher.",
  546: "Nullung: in TN-S/TN-C-Netzen (N und PE verbunden). Körper­schluss → Strom über PE oder PEN zur Neutral­punkt­erdung → Kurzschluss­strom → Sicherung löst aus. In modernen Anlagen: PE und N IMMER getrennt (TN-S).",
  547: "Kabel­farben: L1=braun, L2=schwarz, L3=grau (oder alle: braun), N=hell­blau, PE=grün-gelb. In alten Anlagen: L1-3=schwarz, N=hellblau, PE=grün-gelb. Bei Motor: U1,V1,W1 = Phasen­klemmen.",
  548: "Schutzleiter im Stecker länger: Bei heraus­reißen des Steckers (z.B. durch Zug am Kabel) trennt PE als Letztes → Gehäuse bleibt geerdet, auch wenn L und N bereits getrennt sind → Schutz gegen Berührungs­spannung bleibt länger aufrecht.",
  549: "IP-Schutzart: IP54 = 5 (geschützt gegen Berühr. mit Draht, gegen Staub) + 4 (gegen Spritzwasser aus jeder Richtung). IP65 = staubdicht + gegen Strahlwasser. IP67 = staubdicht + kurzzeitig tauchfähig. Für Außengeräte: mind. IP44.",
  550: "Haupt­schütz schützt Motorwicklungen durch zuverlässiges Schalten des Dreiphasenstroms mit hoher Schaltleistung. Hilfs­schütz im Steuer­stromkreis: geringe Last, wird für Meld­kontakte, Zeitrelais, SPS-Eingang verwendet.",

  // ── Fehlerdiagnose & Wartung (551–650) ────────────────────────────────
  551: "Schütz vs. Relais: Schütz hat separate Funken­löschkammern für hohe Ströme (Motoranlauf). Relais für Steuer­ströme (<10 A) hat einfachere Kontakt­geometrie. Beide erzeugen Schalt­geräusche → Hilfsschütz ist kleiner, billiger.",
  552: "AC-8a: Hermetischer Verdichter­motor mit manueller Rückstellung nach Auslösung. AC-8b: automatischer Reset. Wichtig: Kälte­verdichter sind schwer anlaufend → hoher Einschalt­strom → Schütz muss für diese Kategorie ausgelegt sein.",
  553: "Motor­lüfter: Eigenventilation. Bei Umkehr­betrieb (z.B. Kran­motor) müssen beide Dreh­richtungen Kühlung liefern → bidirektionaler Lüfter. Bei EC-Motoren oder Drehzahl­regelung: externe Fremd­belüftung bei niedriger Drehzahl erforderlich.",
  554: "Motortemperatur: bei 10 K Überschreitung der zulässigen Wicklungs­temperatur sinkt die Isolations­lebensdauer auf die Hälfte (Montsinger-Regel). Überlastung → Wicklungs­schaden in sehr kurzer Zeit.",
  555: "Leistungs­schild­angaben: cos φ und Wirkungsgrad η ermöglichen Berechnung von Wirk­leistung und Strom. Bei Stern: U = 230 V, I = Strom je Phase. Bei Dreieck: U = 400 V, I = Strom je Außenleiter. Drehzahl gibt Schlupf an.",
  556: "Anlauf­kondensator: größere Kapazität (z.B. 250 μF), kurze Einschalt­dauer. Erzeugt 90° Phasen­verschiebung in der Hilfs­wicklung → Drehfeld → Anlauf­moment. Wird nach dem Anlauf abgetrennt (z.B. durch Relais oder Zentrifugal­schalter).",
  557: "Zwei Kondensatoren: Anlauf­kondensator (groß, kurzzeitig) = hohes Anlauf­moment. Betriebs­kondensator (klein, dauerhaft) = verbessert cos φ, höheres Lauf­moment. Ohne Betriebs­kondensator: Motor wärmer, schlechterer Wirkungs­grad.",
  559: "Strom­abhängiges Anlauf­relais (PTC-Anlauf­relais): Während des Anlaufs ist der Strom hoch → Relais zieht an → Kondensator in Reihe mit Hilfs­wicklung. Nach dem Hochlauf sinkt der Strom → Relais fällt ab → Hilfs­wicklung getrennt.",
  560: "Stern-Dreieck: günstig, bewährt. Sanft­anlauf (Thyristor): reduziert Strom sanfter, besser für empfindliche Lasten. Frequenz­umrichter (FU): beste Lösung (stufenlos, energiesparend). Widerstands­anlauf: veraltet, verlustreich.",
  561: "Dreh­richtungs­änderung: Zwei Außenleiter tauschen (z.B. L1 und L3). Dabei muss Verdichter sofort auf richtige Dreh­richtung prüfen (Druck­aufbau auf HD-Seite). Falsche Dreh­richtung → Verdichter pumpt in falsche Richtung → kein Druck­aufbau.",
  562: "Anlaufstrom bei großen Motoren: Typisch 6–8× Nenn­strom über 1–3 s. Bei 22-kW-Motor: Nenn­strom ≈ 43 A → Anlauf­strom bis 300 A. Das verursacht merklichen Spannungs­abfall im Netz (Licht flackert). EVU-Vorschriften limitieren.",
  563: "Rechtslauf (gemäß IEC): Bei Anschluss L1-U1, L2-V1, L3-W1 dreht Welle im Uhrzeigersinn (von der Antriebsseite gesehen). Links­lauf: zwei Außenleiter tauschen. Korrekte Dreh­richtung für Kälte­verdichter ist durch Hersteller vorgegeben.",
  564: "Motorarten in der Kältetechnik: Drehstrom­asynchron­motor = Standard (Verdichter, Ventilatoren). EC-Motor (electronically commutated, Gleichstrom­bürstenlos) = Inverter-Ventilatoren, sehr effizient. Schrittmotor = EEV. Spaltpolmotor = kleine Ventilatoren.",
  565: "LS-Schalter (Leitungs­schutz­schalter): thermische Auslösung bei Überlast (Bimetall, träge). Magnetische Auslösung bei Kurzschluss (Elektromagnet, unverzögert). Manuelle Schalt­funktion. KEIN Motorschutz (kein einstellbarer Auslösewert)!",
  566: "Frei­auslösung: Sicher­heits­funktion. Auch wenn jemand den Schalter­hebel in EIN hält, löst der LS-Schalter bei Überlast oder Kurz­schluss aus. Verhindert, dass der Schalter in einem Fehlerfall erzwungen eingeschaltet bleibt.",
  567: "Thermischer Auslöser (Bimetall): Stromwärme biegt Bimetall → löst bei Überlast aus (Zeit > 10 s). Magnetischer Auslöser (Spule): Kurz­schluss­strom erzeugt starkes Magnet­feld → sofortige Auslösung (< 10 ms).",
  568: "FI-Prüf­taste erzeugt künstlichen Fehlerstrom über Prüf­widerstand → FI löst aus. Zeigt, dass FI mechanisch und elektronisch funktioniert. Monatliche Prüfung empfohlen. Der Schutz­wert von 30 mA wird dabei NICHT überprüft.",
  569: "FI-Kenndaten: Bemessungsstrom (z.B. 40 A) = maximaler Nenn­strom. Bemessungs­fehlstrom (z.B. 30 mA) = Auslösewert. Typ AC: nur Wechsel­fehlstrom. Typ A: auch pulsierender Gleich­fehlstrom (für Inverter­geräte). Typ B: auch glatter Gleichstrom.",
  570: "Selektivität bei 2 FI: Übergeordneter FI = Selektiv­FI (höherer Auslösestrom oder Verzögerung). Untergeordneter FI = Normal-FI (30 mA, keine Verzögerung). Nur bei Fehler im Unter­stromkreis soll der untergeordnete FI auslösen.",
  571: "LS-Auslösecharakteristik: B (3–5×In) für rein ohmsche Lasten (Leuchten, Steckdosen). C (5–10×In) für Motoren (Anlauf­strom). D (10–20×In) für sehr hohe Einschaltströme (Transformatoren, Schweißgeräte, große Motoren).",
  572: "Motor­schutzschalter: einstellbarer thermischer Auslöser (Bimetall) für Überlast + magnetischer Auslöser für Kurz­schluss. Einstell­wert = Motor-Nenn­strom. Ausschalten = Hand­betätigung. Öffner­kontakt (95/96) für Sicherheitskette.",
  573: "Motor­schutz­schalter-Auslösearten: Thermisch (Überlast): Bimetall­erwärmung über Nennstrom → Auslösung nach Zeit (inverse Kennlinie). Magnetisch (Kurzschluss): sofortige Auslösung bei Vielfachem des Nennstroms.",
  574: "Motor­schutz­relais hat keinen eigenen Kurzschluss­schutz → separat LS-Schalter oder NH-Sicherung erforderlich. Öffner­kontakt (95/96) unterbricht Steuer­stromkreis → Schütz fällt ab → Motor stoppt. Kein direktes Schalten des Haupt­stroms.",
  575: "Einphasiger Motor an 3-phasigem Motor­schutz: Alle 3 Bimetalle müssen gleichmäßig erwärmt werden. Der Einphasenstrom wird durch alle 3 Bimetalle geführt (Reihenschaltung) → gleich­mäßige Erwärmung → korrekte Auslösung.",
  576: "Thermistor­motorschutz (PTC): Widerstand des PTC-Fühlers steigt sprunghaft bei ca. 130–150 °C. Auslöse­gerät misst diesen Widerstand und schaltet bei Über­schreiten des Schwellwerts. Vorteil: Wicklungs­temperatur direkt gemessen (nicht Umgebung).",
  577: "Druckgas­überhitzungsschutz: Fühler (PTC oder NTC) im Druckgas­stutzen des Verdichters oder in der Druckleitung. Schützt vor zu hoher Verdichtungs­endtemperatur. Einstellwert typisch 100–120 °C. Handabrückung nach Fehler­behebung.",
  578: "Klixon (Über­temperatur­schalter): Öffnet beim Überschreiten einer Temperatur­schwelle → trennt Hilfs­wicklung oder Haupt­strom­kreis. Schließt nach Abkühlung selbst­tätig. Verwendung: kleine her­metische Verdichter als eingebauter Überlast­schutz.",
  579: "Selektivität sichert, dass bei einem Fehler nur der nächst­gelegene Schutz­schalter auslöst → keine unnötige Abschaltung weiterer Strom­kreise. Selektivitäts­nachweis: Kennlinien­überlappung vermeiden → kleinerer Schutz löst zuerst aus.",
  580: "Leitungs­schutz­organe: Schmelz­sicherungen (einmalig, günstig, wechseln nach Auslösung) und Leitungs­schutz­schalter (wieder­einschaltbar, zeigen Auslösung an). Schmelz­sicherungen in der Kälte­technik: NH-Sicherungen für Leistungs­kreise.",
  581: "D-System (Diazed): für < 63 A. DO-System (Neozed): für < 63 A, kompakter. NH-Sicherungen (Niederspannungs-Hochleistungs): für 63–1250 A, in Haupt­verteilungen. Stöpsel­sicherungen: Größen M00 bis DIII (Farbe codiert).",
  582: "D-System vs. DO-System: D (Diazed) = älteres System mit Schrauberring und Stöpsel­sicherung. DO (Neozed) = modernes, kompakteres System. Beide mit Farb­codierung nach Nennstrom: 2 A=rosa, 6 A=grün, 10 A=rot, 16 A=grau, 20 A=blau, 25 A=gelb, 35 A=schwarz.",
  583: "PT100: Platin-Widerstands­thermometer, Standard­typ. R(0 °C) = 100 Ω. Temperaturkoeffizient ≈ 0,385 Ω/K. Lineares Verhalten, sehr genau. Verwendung: präzise Temperaturmessungen in Klima- und Kälte­anlagen, Labor, Industrie.",
  584: "PT1000: ähnlich PT100, aber R(0 °C) = 1000 Ω. Vorteil: Zuleitungs­widerstände haben weniger Einfluss (Signal­rauschen geringer). Bevorzugt bei langen Zuleitungen. In der Kälte­technik häufig in Reglern.",
  585: "PTC (Positive Temperature Coefficient = Kalt­leiter): Widerstand steigt mit Temperatur. Zwei Typen: linear (zur Temperatur­messung) und Sprung-PTC (für Motor­schutz, springt bei bestimmter Temperatur). Wichtig: Typ nicht verwechseln!",
  586: "NTC (Negative Temperature Coefficient = Heißleiter): Widerstand SINKT mit steigender Temperatur. Nicht linear. Günstig und verbreitet in Thermo­staten und Reglern. Kalt = hoher Widerstand, warm = niedriger Widerstand.",
  587: "Druck­transmitter (4–20 mA): 4 mA = Minimal­druck. 20 mA = Maximal­druck. Lineares Ausgangssignal → einfache Verarbeitung im Regler. Vorteil gegenüber Ein/Aus-Pressostat: Druck­verlauf sichtbar, variable Einstellpunkte per Software.",
  588: "Sicherheitskette: Wenn auch nur ein Element öffnet (z.B. HD-Pressostat angesprochen), fällt die gesamte Kette ab → Verdichter­schütz öffnet → Motor stoppt sofort. Keine Verzögerung bei sicher­heitsrelevanten Schutz­auslösungen.",
  589: "Elemente der Sicherheitskette: Motor­schutz (Überlast), Thermistor (Wicklungs­temperatur), HD-Pressostat (zu hoher Druck), ND-Pressostat (zu niedriger Druck), Öldiff.­druck­schalter (Ölmangel), Druckgas­temperatur, Frostschutz­thermostat.",
  590: "EEV-Regelung: Drucktransmitter liefert Verdampfungs­druck (→ t₀). Temperaturfühler am Verdampfer­austritt liefert Sauggastemperatur. Über­hitzung = t_Gas – t₀. Regler sendet Impulse (Schrittmotor) → Ventilöffnung. Regelzyklus: 1–5 s.",
  591: "Kupfer: zäh (biegar, ohne Bruch), schweißbar und hart­lötbar. Sehr gute elektrische und thermische Leitfähigkeit. Widerstandsfähig gegen NH₃ (jedoch NICHT gegen NH₃-haltiges Kondenswasser!). Weich bei kalt → gut für Kältetechnik.",
  592: "Lötverbindungen sind dauerhaft (unlösbar ohne Hitze) und dichter als Schraub­verbindungen (Flansch, Verschraubung). Weniger Undichtheiten = weniger Kältemittel­verlust. Kälte­technik: möglichst viele Löt­verbindungen statt Schraub­verbindungen.",
  593: "Löten: Schmelztemperatur des Lots < Grundwerkstoff-Schmelz­punkt → kein Anschmelzen des Grundwerkstoffs. Schweißen: Grundwerkstoff und Zusatz schmelzen gemeinsam auf → innige Verbindung, aber höhere Verzugs­gefahr und Wärme­einbringung.",
  594: "Mechanische Reinigung: Schmirgelleinen (für grobe Oxidschichten), Kunststoff­vlies (für leichte Oxidation, keine Stahl­späne). Chemische Reinigung: Aceton (Fett und Öl). Wichtig: Aceton verdampft rückstandslos. Keine Lösemittel mit Chlor verwenden.",
  595: "Metallisch blank = sauber genug, wenn die Oberfläche gleichmäßig hell glänzt. Keine dunklen Flecken (Oxide), keine Fett­film (Reflexion), keine Kratzer durch Stahl­wolle. Erst dann Flussmittel und Lot aufbringen.",
  596: "Silber-Phosphor-Lot (L-CuP): Cu-Cu-Verbindungen, KEIN Flussmittel nötig, Phosphor reduziert Kupferoxide. Schmelzbereich ca. 645–825 °C. Nicht für Stahl oder Messing verwenden (Phosphor-Versprödung von Messing möglich).",
  597: "Cu-Messing: Messing (Legierung aus Kupfer + Zink) oxidiert stärker und bildet mit Phosphorlot spröde Phasen. Daher: Silber-Hart­lot (L-Ag nach EN 17672) + Flussmittel (FH 10 oder FH 12). Kein Silber-Phosphor-Lot für Cu-Messing!",
  598: "Flussmittel reinigen die Oberfläche von Oxiden beim Löten, verhindern Neubildung und verbessern die Benetzung des Lots. Achtung: Flussmittel entfernen KEIN Fett oder Öl → mechanische Vorbehandlung trotzdem nötig!",
  599: "Flussmittel-Dämpfe beim Löten: ätzend, reizend für Augen und Atemwege. Absaugung oder gute Lüftung obligatorisch. Schutzbrille und Handschuhe tragen. Nach dem Löten Flussmittelreste vollständig entfernen.",
  600: "Flussmittel wirkt nur gegen Oxide, NICHT gegen organische Verunreinigungen (Fett, Öl, Schmiermittel). Fett verhindert die Benetzung des Lots auch bei Anwendung von Flussmittel → Vorbehandlung ist immer nötig.",

  // ── Prüfungsvorbereitung & Meisterfragen (601–650) ────────────────────
  601: "Flussmittelreste sind immer korrosiv: Sie reagieren weiter mit Kupfer und verursachen Lochfraß. Entfernung: Mit heißem Wasser und Bürste sofort nach dem Abkühlen. Bei Rohren auch innen spülen. Keine Reste tolerieren!",
  602: "Schutzgas­spülen beim Löten: Trocken­stickstoff (oder 95/5 Formiergas) im geringen Überdruck durch das Rohr strömen lassen. Verhindert Zunder (Cu₂O) auf der Rohr­innen­fläche, der sich sonst in Expansions­ventilen festsetzt.",
  603: "Zunder (Kupferoxid, Cu₂O) im Rohrinneren: Harte, schwarze Ablagerung. Gelangt in den Kreislauf → verstopft Kapillar­rohre, TEV-Sitz, Trockner­sieb, EEV. Verursacht schwere Folgeschäden. Schutzgasspülen ist daher Pflicht.",
  605: "Harte Flamme = Sauerstoffüberschuss (kurzer blauer Flammkegel). Oxidiert die Lötstelle stark → Oxide verhindern gute Benetzung → poröse, schwache Verbindung. Immer reduzierende Flamme (leichter Gas­überschuss, ruhige gelb-orange Flamme).",
  606: "Überhitzung der Lötstelle: Flussmittel verbrennt → keine Schutzwirkung mehr. Grundwerkstoff oxidiert stark. Lot läuft weg (zu dünnflüssig). Gefüge­veränderung im Kupfer (Rekristallisation, Erweichung). Verbindung porös und undicht.",
  607: "HFKW-Zersetzung bei Hitze: R-134a, R-410A etc. zersetzen sich bei > 300–400 °C. Entstehende Stoffe: HF (Fluorwasserstoff = stark ätzend, giftig), HCl (bei chlorhaltigen KM). Extrem gefährlich → Sofortmaßnahme: Raum verlassen, frische Luft.",
  608: "Stechender Geruch + Löten an R-134a: Fluorwasserstoff (HF) entsteht durch KM-Zersetzung. HF ist extrem ätzend (Haut, Augen, Lungen). Sofortige Evakuierung, frische Luft, Arzt. Anlage vollständig entleeren vor Löt­arbeiten!",
  609: "Weichlöten < 450 °C: für Wasser, Sanitär (nicht für Kältetechnik). Hart­löten 450–900 °C: für Kälte­technik, Gas. Hoch­temperatur­löten > 900 °C: im Vakuumofen, Edelstahl­konstruktionen.",
  610: "Spaltlöten (Kapillar­löten): Lot zieht durch Kapillarkräfte in den engen Spalt. Voraussetzung: enger, gleich­mäßiger Spalt (0,05–0,3 mm), saubere Oberflächen, richtiger Temperatur­bereich des Flussmittels und Lots.",
  611: "Hart­löten (> 450 °C) in der Kältetechnik: Verbindung ist temperatur- und druckfest, dicht für KM-Drücke. Zugfestigkeit > 200 N/mm². Weichloten wären zu schwach für die Drücke und Temperaturen in Kälte­leitungen.",
  612: "Löt­verbindung entsteht durch: 1. Benetzung (Lot schmilzt auf der erw. Oberfläche). 2. Kapillarwirkung (Lot zieht in den Spalt). 3. Diffusion (Lot-Atome diffundieren in Grundwerkstoff = metallurgische Bindung). Alle 3 Schritte nötig für eine gute Verbindung.",
  613: "Optimaler Spalt 0,05–0,3 mm: Zu groß → Kapillar­wirkung reicht nicht → Hohlräume. Zu klein → kein Loteinzug möglich. Parallel = gleichmäßige Kapillar­wirkung. Konisch/ungleichmäßig → Segre­gation (Lot sammelt sich nur an einer Seite).",
  614: "Paralleler Spalt = konstante Kapillardruckkraft. Konischer Spalt = Lotein­zug ungleich → Segre­gation und Poren­bildung. Typisch: Muffe auf Rohr geschoben → Passform mit leichter Spielpassung.",
  615: "Oberflächen­vorbereitung: Kunststoff­vlies (Scotch-Brite) → kein Stahl­späne­risiko. Schmirgelleinen für stärkere Oxide. KEINE Stahl­wolle → Stahl­partikel im KM-Kreislauf → Korrosion, Kompressor­schäden.",
  616: "Stahl­wolle zur Kupfer­reinigung: Stahl­partikel drücken sich in die weiche Kupfer­oberfläche ein. Diese Partikel: (1) elektro­chemische Korrosion (Galvani-Element Stahl/Kupfer), (2) Lochfraß, (3) Fremd­körper im Kreislauf.",
  617: "Falsche Rohr­schneider­handhabung: Zu schnelles Eindrehen → Quetschung statt Schnitt → Grat am Schnitt­rand → Spalt wird an dieser Stelle zu groß. Rohr­innen­durchmesser wird verengt → erhöhter Druck­verlust.",
  618: "Silber im Lot: verbessert die Zähigkeit (Nicht­sprödigkeit), senkt den Schmelzpunkt, verbessert die Fließ­fähigkeit und Benetzung der Kupfer­oberfläche. Mehr Silber = besseres Lot, aber teurer. Typisch 2–30 % Silber­anteil.",
  619: "Phosphor im Lot: reduziert Kupferoxide auf der Oberfläche (Reduktionsmittel) → kein Flussmittel nötig bei Cu-Cu. ABER: Phosphor bildet mit Zink (in Messing) spröde Cu-Zn-Phosphid-Verbindungen → niemals Phosphorlot auf Messing!",
  620: "Phosphor­lot (L-CuP): kein Flussmittel nötig bei Cu-Cu (Phosphor wirkt als Selbst­flussmittel). Silber­hart­lot (L-Ag): Flussmittel erforderlich (Oberflächen­aktivierung). Phosphorlot = günstiger, einfacher bei reinen Cu-Cu-Verbindungen.",
  621: "Cu-Messing: Messing enthält Zink → Phosphorlot bildet spröde Phosphid-Verbindungen mit Zink. Daher: IMMER Silber­hart­lot (L-Ag) mit Flussmittel für Cu-Messing-Verbindungen.",
  622: "Wirktemperatur­bereich des Flussmittels: z.B. FH 10 wirkt bei 500–800 °C. Bei niedrigeren Temperaturen: inaktiv (kein Schutz). Bei höheren: Flussmittel verbrennt → keine Schutz­wirkung mehr. Lot­arbeitstemperatur muss in diesem Fenster liegen.",
  623: "Außerhalb des Wirktemperatur­bereichs: darunter = Oxidbildung nicht verhindert → Lot benetzt nicht. Darüber = Flussmittel verbrennt, entsteht schwarzer Rückstand → hartnäckige Korrosion. Temperatur­überwachung beim Löten ist entscheidend.",
  624: "Aktive Flussmittel­reste greifen Kupfer­oberflächen an (elektrochemisch, durch Säure­reste). Lochfraß beginnt unter der Flussmittelschicht. Bei Rohren, die KM führen: Partikel gelöster Korrosions­produkte gelangen in den Kreislauf.",
  625: "Arbeits­temperatur beim Löten: Man erhitzt das Rohr (Grundwerkstoff), nicht das Lot direkt. Das Werkstück muss heiß genug sein, damit das Lot am Werkstück schmilzt (nicht durch die Flamme). So zieht das Lot in den Spalt.",
  626: "Gleichmäßige Erwärmung beim Spaltlöten: Beide Fügepartner gleichzeitig erhitzen → kein Temperatur­gefälle → Lot zieht gleichmäßig ein. Bei ungleicher Erwärmung: Lot läuft zur heißen Seite → kalte Seite bleibt ungelötet (Bindungs­fehler).",
  627: "Temperatur­verlauf beim Hart­löten: 1. Aufwärmen (Grundwerkstoff erwärmen, nicht Lot). 2. Durchwärmen (beide Teile auf gleiche Temperatur bringen). 3. Lot einbringen (schmilzt am Werkstück). 4. Temperatur halten (Lot läuft ein). 5. Abkühlen (kein Bewegen!).",
  628: "Reduzierende Flamme: Leichter Gasüberschuss → Verbrennungsprodukte (CO, H₂) verbrauchen vorhandenen Sauerstoff → keine freie Oxidation an der Lötstelle. Erkennbar an leuchtend gelber, ruhiger Flamme (im Gegensatz zur scharfen, blauen oxydierenden Flamme).",
  629: "Folgen der Überhitzung: Flussmittel verbrennt (schwarzer Rückstand). Kupfer­oberfläche oxidiert stark. Lot wird zu dünnflüssig → läuft weg. Schlechtere Benetzung → porös, undichte Verbindung. Mechanische Schwächung durch Gefüge­veränderung.",
  630: "Überhitzte Lötstelle: Optisch erkennbar an: mattglänzender, rauher Naht­oberfläche. Anlauffarben auf dem Kupfer (blau, lila, schwarz). Schwarze Flussmittel­reste. Ungleichmäßige Naht­form. Mechansich: Naht bricht leicht.",
  632: "Kapillarwirkung (Kapillar­druck): Δp = 4 × σ / d (σ = Oberflächen­spannung des flüssigen Lots, d = Spalt­breite). Je schmaler der Spalt, desto höher der Kapillar­druck → Lot wird tiefer in den Spalt gesaugt. Optimaler Spalt 0,05–0,3 mm.",
  633: "Weichlöten (< 450 °C, z.B. Zinn-Löten) ist für KM-Leitungen in der Kälte­technik VERBOTEN (ÖVE, EN 378, Gasinstallations­normen). Gasleitungen: nur Hart­löten. Kälte­mittel­leitungen: nur Hart­löten. Wasser/Heizung: Weichlöten erlaubt.",
  634: "Rückschlags­sicherung: kombiniert 3 Sicherheitskomponenten: (1) Flammen­sperre (Sintermetall/Sieb stoppt Flammen­front), (2) Gasrücktritts­ventil (Rück­strömung verhindert), (3) Temperatur­auslöser (bei Flammenrückschlag → schließt Gasweg). An jeder Schlauchverbindung verpflichtend.",
  635: "Beim Umgang mit brennbaren Gasen: Feuerschutz­handschuhe schützen vor Verbrennungen beim Entzünden und bei Flammenkontakt. Warnweste für Straßen­verkehr. Schutzbrille gegen Splitter und Funkenwurf.",
  636: "Gasflaschen­lagerung: Aufrecht (Ventil oben), gesichert gegen Umfallen (Kette, Gestell). Gut belüftet (kein Keller, keine Gruben). Brenngase und Sauerstoff mindestens 2 m getrennt oder Trennwand (F90). Wärme fernhalten (max. 50 °C).",
  637: "Sauerstoff + Fett/Öl: Reaktion ist stark exotherm (explosionsartig). Schon minimale Mengen Öl oder Fett an einem Sauerstoff­ventil, Schlauch oder Druckminderer können explodieren. Strikt gefettete Hände, Handschuhe vermeiden!",
  638: "Schlecht gewarteter Brenner: Düsen verkrustet → instabile Flamme. Gasventile lassen undicht → ungeregelte Gas­menge. Mischventil falsch eingestellt → zu viel Sauerstoff (harte Flamme) oder zu wenig (Flamme erlischt). Regelmäßige Wartung Pflicht.",
  640: "F-Gase-VO (EU 517/2014): Phase-Down HFKW bis 2030 auf 21 % Ausgangswert. Dichtheitskontrollen, Rückgewinnungs­pflicht, Zertifizierungs­pflicht für Personen/Unternehmen. Verbote bestimmter KM in neuen Anlagen (GWP ≥ 2500).",
  641: "GWP ist eine relative Zahl: wie viel Treibhauseffekt ein Gas im Vergleich zu CO₂ über 100 Jahre hat. R-404A (GWP = 3922) erwärmt das Klima 3922× stärker als dieselbe Masse CO₂. Dieser Wert ist entscheidend für Phase-Down-Quoten.",
  642: "Kältemittel mit hohem GWP (z.B. R-404A: 3922) werden durch solche mit niedrigerem GWP ersetzt: R-448A (GWP = 1387) oder R-452A (GWP = 2140) für TK-Anwendungen, oder natürliche KM (CO₂/R-744: GWP = 1).",
  643: "CO₂-Äquivalent [t] = Masse [kg] × GWP / 1000. Beispiel: 100 kg R-404A → 100 × 3922 / 1000 = 392,2 t CO₂-Äq. Diese Zahl bestimmt, ob Dichtheits­kontroll­intervalle und Leckage­erkennungs­anforderungen gelten.",
  644: "Betreiber­pflichten nach F-Gase-VO: Dichtheit erhalten, Kontrollen durchführen (lassen), Leckagen sofort beheben, Prüfbuch führen, KM-Füllmengen dokumentieren, Rückgewinnung bei Außerbetriebnahme, zertifiziertes Personal beauftragen.",
  645: "Dichtheits­kontrolle: Prüfung ob KM entweicht. Methoden: Elektronischer Detektor (empfindlichste Methode, < 5 g/Jahr), UV-Kontrastmittel (sichtbar mit UV-Lampe), Lecksuch­spray (Blasen­test, für grobe Leckagen), Druckabfalltest.",

  // ── Kältekreislauf & Diagramme – Vertiefung (700–739) ─────────────────
  702: "1. Hauptsatz (Energie­erhaltung): In der Kälteanlage: Q₀ (Verdampfer) + P (Verdichter) = Q_C (Verflüssiger). Keine Energie geht verloren – sie wird nur umgewandelt.",
  703: "2. Hauptsatz legt die Richtung thermodynamischer Prozesse fest: Kälte­maschine arbeitet gegen die natürliche Richtung (von kalt nach warm) und benötigt deshalb Antriebsenergie.",
  704: "Enthalpie im log(p)-h-Diagramm: Auf der X-Achse abgelesen. Kälteleistung pro kg: q₀ = h₁ – h₄ (Abstand auf der Enthalpie-Achse). Verdichterarbeit: w = h₂ – h₁. Je breiter das Diagramm, desto effizienter der Kreislauf.",
  705: "Überhitzung ist eine wichtige Sicherheits­maßnahme: Nur überhitztes Gas sicher für den Verdichter. Die Überhitzungszone liegt am Ende des Verdampfers. TEV/EEV regeln die Überhitzung auf den Sollwert.",
  706: "Unterkühlung verschiebt den Punkt vor dem Expansions­organ im log(p)-h-Diagramm nach links (zu kleinerer Enthalpie). Damit steigt die Enthalpie­differenz im Verdampfer → mehr Kälteleistung pro kg KM.",
  707: "Flüssigkeitsschlag im Verdichter: Flüssigkeit ist nahezu inkompressibel. Der Druck steigt instantan auf sehr hohe Werte → mechanische Zerstörung. Schutz durch ausreichende Überhitzung (TEV-Einstellung) und Flüssigkeitsabscheider.",
  708: "Verflüssiger-Funktion: Im log(p)-h-Diagramm: horizontale Linie auf HD-Niveau. Wärme Q_C = m × (h₂ – h₃) wird abgegeben (Enthitzung + Kondensation + Unterkühlung).",
  709: "TEV arbeitet nach Druckbalance: Fühler­druck (Sättigungsdruck bei Fühlerttemperatur) minus Verdampfungs­druck minus Federvorspannung = Öffnungs­kraft. Bei steigender Überhitzung öffnet Ventil mehr → mehr KM → Überhitzung sinkt.",
  710: "GWP 100-Jahre-Wert: CO₂ = 1, R-32 = 675, R-134a = 1430, R-404A = 3922, R-410A = 2088. Neuzulassungs­verbote betreffen KM mit GWP ≥ 2500 in stationären Kälteanlagen ab 2022.",
  711: "ODP-Werte: R-11 = 1 (Referenz). R-12 = 1. R-22 = 0,055. R-134a = 0. CO₂ = 0. Propan = 0. HFKW haben ODP = 0 (kein Chlor), daher keine Ozon­schicht­belastung, aber trotzdem hoher GWP.",
  712: "F-Gase-VO regelt: (1) Wer handelt mit F-Gasen (Zertifizierung). (2) Wie werden Dichtheits­kontrollen durchgeführt. (3) Phase-Down (Quoten). (4) Verbote (GWP ≥ 2500). (5) Rückgewinnung. (6) Kennzeichnung. (7) Reporting.",
  713: "Saugleitungs­isolierung: Verhindert Wärme­eintrag von außen. Ungewollte Überhitzung erhöht Sauggas­temperatur → Verdichtungs­end­temperatur steigt → Verdichter mehr belastet. Isolierung auch gegen Kondensat­bildung (Feuchteschäden).",
  714: "Hunting (Jagen): TEV schwingt auf und zu → Saugdruck schwankt → Kälteleistung schwankt. Ursachen: Ventil überdimensioniert, Überhitzungseinstellung zu gering, externe Druckausgleichleitung fehlt, Verstopfung. Diagnose: schwankender ND-Druck.",
  715: "Wärmepumpe unterscheidet sich von Kältemaschine nur durch die Nutzungs­perspektive: Gleicher Kreislauf, aber die Nutzwärme (Q_H) wird am Verflüssiger entnommen (Heizung), statt die Kälteleistung (Q₀) am Verdampfer. Leistungszahl WP = Q_H/P.",
  716: "Ohmsches Gesetz: Grundlage aller Elektro­berechnungen. Merke: Die Dreiecks­formel: U oben, R und I unten. Abdecken was man sucht: U = R×I, R = U/I, I = U/R.",
  717: "Hart­löten: Schmelztemperatur des Lots > 450 °C. In der Kälte­technik typisch 650–800 °C (Silber-Phosphor-Lot). Verbindung widersteht Betriebsdrücken bis 80 bar und Temperaturen von –60 bis +150 °C.",
  718: "Im log(p)-h-Diagramm: X = spez. Enthalpie h [kJ/kg], Y = lg(Druck) [bar abs]. Der Kreisprozess ist ein Viereck: Verdampfen (waagerecht rechts), Verdichten (schräg rechts oben), Verflüssigen (waagerecht links), Drosseln (fast senkrecht links unten).",
  719: "Kältelast­berechnung: Summe aller Wärme­quellen im Kühlraum. Die drei größten Anteile sind meist: Transmission (Wärme durch Wände), Belüftung/Türen, Kühlgut. Ergebnis bestimmt die erforderliche Verdampfer­leistung.",
  720: "Entropie beschreibt, wie 'verstreut' Energie im System ist. Reale Prozesse erzeugen immer Entropie (Irreversibilität). Im Verdichter: Reibung → mehr Entropie → höhere Endtemperatur → mehr Verdichterarbeit als ideal.",
  721: "Reale Verdichtung: Linie im log(p)-h-Diagramm verläuft flacher als isentrope Linie → mehr Enthalpiezunahme → höherer h₂ → weniger Effizienz. Messgröße: isentroper Wirkungsgrad η_is = (h₂_is – h₁) / (h₂_real – h₁).",
  722: "Isenthalp: h = konstant. Beim Drosseln: Kein Wärme­übergang, keine Arbeit → Energie bleibt erhalten (1. Hauptsatz). Druck und Temperatur sinken, Dampfgehalt x steigt (es entsteht Flashgas).",
  723: "Isentrop: s = konstant (Entropie unverändert). Nur für ideale, reversible adiabatische Prozesse. Realer Verdichter: irreversibel → Entropie steigt → Endtemperatur und Verdichterarbeit größer als isentrop.",
  724: "Tiefere Verdampfungstemperatur: Saugdruck sinkt → Druckverhältnis steigt → Verdichter arbeitet stärker → Liefergrad sinkt → COP sinkt. Typisch: 3–4 % COP-Verlust pro 1 K Absenkung der Verdampfungstemperatur.",
  725: "Jedes Kelvin höhere Verdampfungstemperatur spart etwa 3–4 % Energie. Maßnahmen zur Erhöhung von t₀: bessere Wärme­übertragung im Verdampfer (mehr Fläche, besseres Reinigen, keine Vereisung), kleinerer Temperatur­abstand.",
  726: "Unterkühlung verschiebt h₃ im log(p)-h-Diagramm nach links (kältere Flüssigkeit vor der Drossel). Damit sinkt h₄ = h₃ (isenthalp). Die Differenz h₁ – h₄ (Kälteleistung pro kg) steigt. Unterkühlung verbessert immer den COP.",
  727: "Zu viel Überhitzung: Der Bereich im Verdampfer nach der Siedelinie (überhitzter Dampf) hat viel schlechtere Wärme­übertragung als der Phasenwechsel­bereich. Wärme­übergangs­koeffizient sinkt von ~2000 W/(m²K) auf ~150 W/(m²K) im Überhitzungsgebiet.",
  728: "Schädlicher Raum (Totvolumen): kleiner Spalt zwischen Kolbenkopf und Ventilplatte. Typisch: 2–5 % des Hub­volumens. Enthält nach der Verdichtung Hochdruck­gas. Dieses expandiert bei der nächsten Ansaugphase → verringert den ansaugbaren Gasvolumen­strom.",
  729: "Liefergrad η_v = f(π): Bei π = 3 (z.B. ND = 3 bar, HD = 9 bar): η_v ≈ 0,85. Bei π = 8: η_v ≈ 0,65. Bei sehr hohem π: η_v → 0 (Verdichter fördert praktisch kein Gas mehr). Daher Zweistufenverdichtung bei hohen Druckverhältnissen.",
  730: "Siedelinie (x = 0): links = untergekühlte Flüssigkeit (nur Flüssig­phase). Auf der Linie = gesättigte Flüssigkeit (gerade am Siedepunkt). Kritischer Punkt = Spitze der Nassdampf­kurve (oberhalb: kein Zweiphasenzustand mehr möglich).",
  731: "Taulinie (x = 1): rechts = überhitzter Dampf (nur Gasphase). Auf der Linie = gesättigter Dampf (gerade am Taupunkt). Zwischen Siedelinie und Taulinie: Nassdampfgebiet (Zweiphasen­gemisch). Verdampfer arbeitet im Nassdampfgebiet.",
  732: "Leckage-Folgen: (1) KM-Verlust → Umweltbelastung (GWP × Masse). (2) Kälteleistung sinkt (ND fällt). (3) Ölverdünnung (KM löst sich im Öl → Lagerschäden). (4) Rechtlich: Geldstrafen bei F-Gase-VO-Verstoß.",
  733: "Dokumentation: F-Gase-VO § 6–8 schreibt vor: Typ und Menge eingefülltes/entnommenes KM, Datum der Dichtheits­kontrolle, Leckagestelle und Behebung, Datum der Rückgewinnung. Aufbewahrung 5 Jahre.",
  734: "Hohe Verdichtungsend­temperatur (> 120 °C): Öl­abbrand in Zylinder, Ventil­beschädigung (Harzbildung), Kolbenring­verschleiß. Ursachen: hohes Druckverhältnis (Verflüssiger zu warm/zu kalt ND), zu hohe Sauggasüberhitzung.",
  735: "Öl­schäumen beim Start: Kältemittel löst sich bei Stillstand (niedrige Temp.) im Öl (Henry­gesetz). Beim Start fällt der Kurbel­wannendruck → KM entgast schlagartig → Öl schäumt → Schmierung nachlässt. Kurbelwannen­heizung verhindert dies.",
  736: "Drehstrom in der Kältetechnik: Drei­phasige Motoren sind einfacher, robuster und effizienter als Einphasenmotoren. Durch das automatisch erzeugte Drehfeld ist kein Hilfs­kondensator nötig. Leistungen bis mehrere MW möglich.",
  737: "FI-Schalter (RCD): Funktion: Summe aller Ströme in L und N muss 0 sein (Kirchhoffs Gesetz). Fließt Strom außerhalb des Kreislaufs (z.B. durch Erdschluss, Körperkontakt), entsteht Differenz → Auslösung. 30 mA in ≤ 40 ms.",
  738: "Luft-Wasser-WP bei Frost: Außentemperatur –15 °C → Verdampfungstemperatur muss noch tiefer (z.B. –20 °C) → Druckverhältnis steigt stark → COP fällt unter 2. Ab ca. –20 °C Außentemperatur: Heizstab sinnvoller (COP = 1).",
  739: "Abtauung bei Luft-WP: Eis­bildung auf Außen­verdampfer bei Luftfeuchte und Temperaturen nahe 0 °C. Heißgas-Abtauung: 4-Wege-Ventil kehrt Kreislauf um → Verdampfer wird Verflüssiger → Eis taut ab. Elektrisch: separate Heiz­stäbe.",

  // ── Fallenfragen & Fehleranalyse (740–756) ────────────────────────────
  740: "Überhitzung = nach dem Verdampfer (Gas), Unterkühlung = nach dem Verflüssiger (Flüssigkeit). Beide beschreiben einen Sicherheits­abstand vom Sättigungs­zustand. Prüfungs­tipp: Überhitzung = 'zu warm für Gas', Unterkühlung = 'zu kalt für Flüssigkeit'.",
  741: "Kältelast-Berechnung ist IMMER eine Summe mehrerer Anteile. Wer nur einen Anteil angibt, liegt falsch. Typische Prüfungs­frage: 'Welche Faktoren gehen NICHT in die Kältelast ein?' → alle gehen ein, wenn relevant.",
  742: "Jede Leckage ist problematisch: (1) Umwelt, (2) Leistungsverlust, (3) Öl­verdünnung, (4) gesetzliche Pflicht. Die F-Gase-VO verbietet explizit das Ignorieren oder Tolerieren von Leckagen. Sofortige Behebung und Dokumentation sind Pflicht.",
  743: "Flüssigkeit im Verdichter ist die GEFÄHRLICHSTE Betriebsstörung. Flüssigkeit kann nicht verdichtet werden → schlagartiger Druckanstieg → mechanische Zerstörung in Bruchteilen von Sekunden. Präventiv: ausreichende Überhitzung und Flüssigkeitsabscheider.",
  744: "Verflüssiger­verschmutzung steigert den HD-Druck (Wärme kann nicht mehr vollständig abgeführt werden → Kondensations­temperatur steigt → Druck steigt). Niemals: Druck sinkt! Hoher HD belastet Verdichter → höherer Strom­verbrauch, Lebensdauer sinkt.",
  745: "TEV regelt NUR die Kältemittel­einspritz­menge für den Verdampfer (Überhitzung). Drehzahl des Verdichters wird durch Thermostat oder Frequenz­umrichter geregelt. TEV und Drehzahl­regelung sind zwei völlig unabhängige Regelkreise.",
  746: "R-290 (Propan): GWP = 3 (extrem niedrig), ODP = 0. Aber: A3-Klasse (leicht entflammbar, Zünd­grenzen 1,7–10,9 Vol%). Daher: Füllmengen­beschränkungen (max. 150 g in Haushalts­geräten), keine Zündquellen, Kfz-Klimaanlagen ausgenommen.",
  747: "2. Hauptsatz gilt universal für ALLE thermodynamischen Systeme: Wärme­maschinen, Kälte­maschinen, Wärmepumpen, chemische Reaktionen, biologische Systeme. Er ist ein fundamentales Naturgesetz.",
  748: "Druckverluste in der Saugleitung: Saugdruck am Verdichter­eintritt < Saugdruck am Verdampfer­austritt. Effektive Verdampfungs­temperatur sinkt → Druckverhältnis steigt → COP sinkt. Maximaler Druckverlust in Saugleitung: ≤ 1 K Sättigungstemperatur.",
  749: "Wärmepumpe erzeugt keine Energie, sie VERSCHIEBT Energie (2. Hauptsatz). Die JAZ > 1 ist kein Wider­spruch: Die Mehrenergie kommt aus der Umgebungs­wärme (Luft, Erde, Wasser). COP > 1 ist thermodynamisch zulässig.",
  750: "FI-Schalter: primär Personen­schutz. Er reagiert auf Erd­schluss­strom (Strom fließt durch Körper zur Erde). Geräte­schutz ist Neben­effekt. LS-Schalter schützt die Leitung (Überlast/Kurz­schluss), nicht Personen.",
  751: "Schutz­gaslos Löten = Zunder­bildung innen. Dieser schwarze Kupferoxid-Zunder bricht in kleinen Partikeln ab und gelangt in den KM-Kreislauf. Verstopft: Schauglas, Kapillarrohr, TEV-Düse, Filtriertrockner, EEV-Nadel.",
  752: "Drosseln im log(p)-h-Diagramm: Fast senkrechte Linie (Enthalpie konstant = isenthalp). Druck sinkt, Temperatur sinkt, Dampfgehalt x steigt (Flashgas). h₄ = h₃ (keine Enthalpie­veränderung durch Drossel).",
  753: "Öl im Verdampfer bildet einen isolierenden Film auf der Rohr­innen­fläche. Wärme­leitfähigkeit Öl ≈ 0,15 W/(mK) vs. Kupfer ≈ 400 W/(mK). Bereits wenige Mikrometer Öl­film erhöhen den Wärme­übergangs­widerstand deutlich.",
  754: "Sicherheits­ventile sind nach KAV, EN 378 und DGÜW-V gesetzlich vorgeschrieben für jede Druckstufe. Ohne: illegaler Betrieb, Haftung bei Unfall. Ansprechdruck = PS (max. zulässiger Betriebsdruck), danach automatisches Öffnen und Schließen.",
  755: "GWP vs. ODP: Unterschied merken durch: O wie Ozon = ODP. G wie Global = Klima = GWP. CO₂ ist Referenz für GWP (= 1). R-11 ist Referenz für ODP (= 1). Beide sind dimensionslose Verhältniszahlen.",
  756: "Anhaltend niedriger Saugdruck beim Start deutet auf: KM-Mangel (Leckage), verstopfter Trockner oder Filter, zu kleine oder verstopfte Expansions­öffnung, schlechter Wärme­übergang im Verdampfer (Vereisung, Verschmutzung).",

  // ── Rechenaufgaben & Berechnungen (757–771) ───────────────────────────
  757: "Formel Transmissionslast: Q̇ = k × A × ΔT [W]. k in W/(m²K), A in m², ΔT in K. Hier: 0,35 × 120 × 18 = 756 W. Prüfungstipp: Einheiten einsetzen, Klammer­rechnung zuerst (keine Reihenfolge nötig, alles Multiplikation).",
  758: "COP-Formel: COP = Q̇₀ / P = Kälteleistung / elektrische Leistung. Hier: 8 / 2,5 = 3,2. Interpretation: 1 kW Strom erzeugt 3,2 kW Kälte. Hoher COP = effiziente Anlage. Typisch: Split-Klima COP 3–5.",
  759: "Temperatur­differenz in Kelvin: ΔT = T₁ – T₂ = 2 – (–10) = 12 K. Einheit ist Kelvin (K), nicht Grad Celsius (°C), weil es sich um eine Differenz handelt. 1 K = 1 °C Differenz, aber die Einheit der Differenz ist Kelvin.",
  760: "Formel sensible Kühlgut­wärme: Q = m × cp × ΔT [kJ]. m = 50 kg, cp = 3,8 kJ/(kg·K), ΔT = 12 K. Q = 50 × 3,8 × 12 = 2280 kJ. Für Leistung: Q̇ = Q / t [kW]. Zeitdauer (z.B. 1 h = 3600 s) nötig.",
  761: "Absolut­druck = Manometerdruck + Atmosph. Druck (1,013 ≈ 1,0 bar). 1,6 + 1,0 = 2,6 bar abs. Dann: Dampf­drucktabelle → bei 2,6 bar abs liegt die Siedetemperatur von R-134a ≈ 0,5 °C.",
  762: "Unter­kühlungs­formel: ΔT_UK = t_C – t_Flüssigkeit. Verflüssigungs­temperatur aus Druck­tabelle abgelesen (HD-Manometer → Absolutdruck → Tabelle). Kontakt­thermometer an Flüssigkeits­leitung. Ergebnis: 40 – 32 = 8 K.",
  763: "Überhitzungs­formel: ΔT_ÜH = t_Sauggas – t₀. Verdampfungs­temperatur aus ND-Manometer (Absolutdruck → Tabelle). Sauggas­temperatur mit Kontakt­thermometer an Saug­leitung beim Verdampfer­austritt. Ergebnis: 2 – (–10) = 12 K.",
  764: "Lüftungs-Wärmelast: Q̇ = ṁ × cp × ΔT [kW]. ṁ = 0,8 kg/s, cp = 1,0 kJ/(kg·K), ΔT = 9 K. Q̇ = 0,8 × 1,0 × 9 = 7,2 kW. Gibt die Kühlleistung an, die zum Abkühlen des eintretenden Außenluft­stroms nötig ist.",
  765: "Personen­wärme: Q̇ = Anzahl × Wärme­abgabe pro Person [W]. 6 × 120 = 720 W = 0,72 kW. Wärme­abgabe pro Person: leichte Arbeit ≈ 100–130 W. Zu addieren zur gesamt­en Kältelast.",
  766: "Beleuchtungs­wärme: Jedes Watt elektrischer Leistung wird vollständig in Wärme umgewandelt (im Kühlraum). 18 × 35 = 630 W = 0,63 kW. LED-Beleuchtung spart hier bis 60 %.",
  767: "Maschinenanlage: Elektrische Antriebsleistung × Nutzungsgrad (75 % als Wärme im Raum = 0,75). 2,4 × 0,75 = 1,8 kW. Die restlichen 25 % verlassen den Raum (z.B. durch Abluft des Lüfters).",
  768: "Absolutdruck: immer Überdruck + Atmosphären­druck. 1,2 + 1,0 = 2,2 bar abs. Dann Dampf­druck­tabelle: Bei 2,2 bar abs liegt R-134a-Siedetemperatur ≈ –10,6 °C (t₀).",
  769: "COP = 12 / 3 = 4,0. Bedeutet: 4 kW Kälteleistung für 1 kW Strom­verbrauch. Guter COP für gewerbliche Kälteanlage. Verflüssigungs­leistung: Q_C = Q₀ + P = 12 + 3 = 15 kW.",
  770: "Q̇ = 0,22 × 90 × 20 = 396 W. Niedrigerer k-Wert als Beispiel 757 (0,22 vs. 0,35) zeigt: Bessere Wärme­dämmung reduziert den Transmissions­wärme­eintrag deutlich (mehr als halbiert bei gleichem ΔT und Fläche).",
  771: "Q = 100 × 2,1 × 15 = 3150 kJ. Nur Energie­menge, keine Leistung. Für Leistung (kW): Q̇ = 3150 kJ / Abkühlzeit [s]. Beispiel: 1 h Abkühlzeit = 3600 s → Q̇ = 3150/3600 ≈ 0,875 kW Kälteleistung erforderlich.",
};

export const allQuestions: Question[] = [
  { id: 1, block: "Grundlagen der K\u00e4ltetechnik", question: "In welcher Einheit werden Druck und Temperatur in der K\u00e4ltetechnik angegeben?", answer: "Druck: bar (Praxis), Pascal (SI: 1 bar = 100.000 Pa). Temperatur: \u00b0C, SI-Einheit Kelvin (K). Temperaturdifferenzen immer in Kelvin." },
  { id: 2, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff Temperatur zu verstehen?", answer: "Die Temperatur gibt an, wie kalt oder warm ein Stoff ist. Sie wird mit einem Thermometer in \u00b0C oder K gemessen." },
  { id: 3, block: "Grundlagen der K\u00e4ltetechnik", question: "In welcher Einheit werden Temperaturdifferenzen angegeben?", answer: "Immer in Kelvin (K)." },
  { id: 4, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff Absolutdruck zu verstehen?", answer: "Druck gegen\u00fcber dem Vakuum (0 bar absolut). Auf Meeresh\u00f6he betr\u00e4gt der Umgebungsdruck ca. 1 bar." },
  { id: 5, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter den Begriffen Luftdruck und Unterdruck zu verstehen?", answer: "Luftdruck = Atmosph\u00e4rendruck (\u22481 bar auf Meeresh\u00f6he). Unterdruck = Druck unterhalb des Atmosph\u00e4rendrucks (Vakuum)." },
  { id: 6, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff \u00dcberdruck (Manometerdruck) zu verstehen?", answer: "Druck \u00fcber dem Atmosph\u00e4rendruck. Manometer zeigen 0 bar bei Atmosph\u00e4rendruck an." },
  { id: 7, block: "Grundlagen der K\u00e4ltetechnik", question: "Welchen Wert zeigt ein Manometer an, wenn in der Anlage der atmosph\u00e4rische Luftdruck herrscht?", answer: "0 bar (\u00dcberdruck)." },
  { id: 8, block: "Grundlagen der K\u00e4ltetechnik", question: "Wie erfolgt die Umrechnung vom Manometerdruck auf den Absolutdruck?", answer: "Absolutdruck = Manometerdruck + Umgebungsdruck (meist 1 bar)." },
  { id: 9, block: "Grundlagen der K\u00e4ltetechnik", question: "Welcher Druck ist in Dampfdrucktabellen und log(p),h-Diagrammen dargestellt?", answer: "Der Absolutdruck." },
  { id: 10, block: "Grundlagen der K\u00e4ltetechnik", question: "Beschreibe den Zusammenhang zwischen Druck und Temperatur. Nach Gay-Lussac: Druck und Temperatur sind direkt proportional (bei konstantem Volumen und konstanter Stoffmenge). Steigt die Temperatur, steigt der Druck \u2013 und umgekehrt.", answer: "\u25b8 K\u00e4ltetechnik: H\u00f6herer Verdampfungsdruck = h\u00f6here Verdampfungstemperatur." },
  { id: 11, block: "Grundlagen der K\u00e4ltetechnik", question: "Sie kommen zu einer R-513A-Anlage und messen einen \u00dcberdruck von 1,2 bar. Wie hoch ist der Absolutdruck und die Verdampfungstemperatur?", answer: "Absolutdruck = 2,2 bar. Aus Dampfdrucktabelle: t\u2080 \u2248 \u201310,6 \u00b0C." },
  { id: 12, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter den Begriffen Schmelzen, Erstarren, Verdampfen und Verfl\u00fcssigen zu verstehen? Wird dabei W\u00e4rme zu- oder abgef\u00fchrt?", answer: "Schmelzen: fest \u2192 fl\u00fcssig (W\u00e4rme zu). Erstarren: fl\u00fcssig \u2192 fest (W\u00e4rme ab). Verdampfen: fl\u00fcssig \u2192 gasf\u00f6rmig (W\u00e4rme zu). Verfl\u00fcssigen: gasf\u00f6rmig \u2192 fl\u00fcssig (W\u00e4rme ab)." },
  { id: 13, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff Wirkungsgrad zu verstehen?", answer: "Verh\u00e4ltnis von Nutzen zu Aufwand, immer < 1. Beschreibt die Effizienz einer Energieumwandlung." },
  { id: 14, block: "Grundlagen der K\u00e4ltetechnik", question: "Was besagt der 1. Hauptsatz der Thermodynamik und was hei\u00dft das in Bezug auf die K\u00e4ltetechnik?", answer: "Energieerhaltung: Energie wird weder erzeugt noch vernichtet. In der K\u00e4lteanlage: Q\u2080 + P = Qc." },
  { id: 15, block: "Grundlagen der K\u00e4ltetechnik", question: "Was besagt der 2. Hauptsatz der Thermodynamik und was hei\u00dft das in Bezug auf die K\u00e4ltetechnik?", answer: "W\u00e4rme flie\u00dft von selbst nur von warm nach kalt. t\u2080 < K\u00fchlmedium, tC > Umgebung." },
  { id: 16, block: "Grundlagen der K\u00e4ltetechnik", question: "Bei welcher Temperatur liegt der absolute Nullpunkt?", answer: "\u2013273,15 \u00b0C = 0 K." },
  { id: 17, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff W\u00e4rmeinhalt zu verstehen?", answer: "Enthalpie \u2013 die thermische Energie eines Stoffes. Einheit: kJ/kg. In der K\u00e4ltetechnik rechnet man mit Enthalpiedifferenzen." },
  { id: 18, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff k-Wert oder u-Wert zu verstehen? Bei welchen Anwendungen gro\u00df, wo klein?", answer: "W\u00e4rmedurchgangskoeffizient (W/(m\u00b2\u00b7K)). Klein bei K\u00fchlraumbegrenzungen (wenig W\u00e4rmeeintrag), gro\u00df bei W\u00e4rme\u00fcbertragern (viel \u00dcbertragung)." },
  { id: 19, block: "Grundlagen der K\u00e4ltetechnik", question: "Wie ver\u00e4ndert sich der W\u00e4rme\u00fcbergang eines Verdampfers, wenn ein Ventilator ausf\u00e4llt?", answer: "Der W\u00e4rme\u00fcbergang wird kleiner (\u03b1-Wert sinkt)." },
  { id: 20, block: "Grundlagen der K\u00e4ltetechnik", question: "Was bedeutet sensible und latente W\u00e4rme? Nenne Beispiele in K\u00e4lteanlagen. Sensibel: messbare Temperatur\u00e4nderung (\u00dcberhitzungszone). Latent:", answer: "Phasenwechsel ohne Temperatur\u00e4nderung (Verdampfungszone)." },
  { id: 21, block: "Grundlagen der K\u00e4ltetechnik", question: "Wie verh\u00e4lt sich der Siedepunkt eines K\u00e4ltemittels in Abh\u00e4ngigkeit vom Druck und was ist eine Dampfdruckkurve?", answer: "Siedepunkt steigt mit Druck. Dampfdruckkurve = grafische Darstellung dieses Zusammenhangs." },
  { id: 22, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum ist es notwendig, dass das K\u00e4ltemittel vor dem Verfl\u00fcssigen auf h\u00f6heren Druck verdichtet wird?", answer: "Nur so steigt die Temperatur \u00fcber die Umgebungstemperatur. Erst dann kann W\u00e4rme abgegeben werden (2. Hauptsatz)." },
  { id: 23, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum ist es notwendig, dass das K\u00e4ltemittel vor dem Verdampfen auf niedrigen Druck gedrosselt wird?", answer: "Nur so sinkt die Temperatur unter die K\u00fchlraumtemperatur. Erst dann kann W\u00e4rme aufgenommen werden." },
  { id: 24, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum muss die Verfl\u00fcssigungstemperatur bei luftgek\u00fchlten Verfl\u00fcssigern \u00fcber der Au\u00dfentemperatur liegen?", answer: "Damit ein W\u00e4rmestrom vom K\u00e4ltemittel an die Umgebung flie\u00dfen kann." },
  { id: 25, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum muss die Verdampfungstemperatur unter der K\u00fchlraumtemperatur liegen?", answer: "Damit ein W\u00e4rmestrom vom K\u00fchlraum ins K\u00e4ltemittel flie\u00dfen kann." },
  { id: 26, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Verdampfungstemperatur wird erwartet, wenn die K\u00fchlraumtemperatur 0\u00b0C betr\u00e4gt?", answer: "Ca. \u201310 \u00b0C (\u0394T \u2248 10 K)." },
  { id: 27, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Verfl\u00fcssigungstemperatur wird erwartet, wenn die Umgebungstemperatur 33\u00b0C betr\u00e4gt?", answer: "Ca. 43 \u00b0C (\u0394T \u2248 10 K)." },
  { id: 28, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter der Taupunktemperatur und der Feuchtkugeltemperatur zu verstehen?", answer: "Taupunkt: Temperatur, bei der die Luft mit Wasserdampf ges\u00e4ttigt ist (Kondensation). Feuchtkugeltemperatur: niedrigste Temperatur durch Verdunstungsk\u00fchlung (K\u00fchlgrenztemperatur)." },
  { id: 29, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist in Bezug auf K\u00e4lteanlagen unter dem Begriff \u00dcberhitzung zu verstehen?", answer: "Erw\u00e4rmung des K\u00e4ltemitteldampfes \u00fcber die Verdampfungstemperatur. Nur Gase k\u00f6nnen \u00fcberhitzt werden." },
  { id: 30, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum ist es notwendig, dass das K\u00e4ltemittel vor dem Verdichten \u00fcberhitzt wird?", answer: "Damit der Verdichter nur gasf\u00f6rmiges K\u00e4ltemittel ansaugt \u2013 Fl\u00fcssigkeit w\u00fcrde ihn zerst\u00f6ren." },
  { id: 31, block: "Grundlagen der K\u00e4ltetechnik", question: "In welchem Bauteil findet die \u00dcberhitzung statt?", answer: "Im Verdampfer (am Ende, in der \u00dcberhitzungszone)." },
  { id: 32, block: "Grundlagen der K\u00e4ltetechnik", question: "Welches Bauteil sorgt f\u00fcr eine ausreichend gro\u00dfe \u00dcberhitzung am Verdampferaustritt (regelt die \u00dcberhitzung)?", answer: "Das Expansionsorgan (TEV oder EEV). Kapillarrohr hat keine Regelfunktion." },
  { id: 33, block: "Grundlagen der K\u00e4ltetechnik", question: "Wie gro\u00df sind \u00fcbliche \u00dcberhitzungswerte bei thermostatischen Expansionsorganen?", answer: "7\u20138 K (TEV), 4\u20136 K (EEV)." },
  { id: 34, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Bauteile trennen die Verfl\u00fcssigungsdruckseite von der Verdampfungsdruckseite?", answer: "Verdichter und Expansionsorgan." },
  { id: 35, block: "Grundlagen der K\u00e4ltetechnik", question: "Wie wird die Verdampfer\u00fcberhitzung in der Praxis gemessen?", answer: "Verdampfungsdruck p\u2080 am Austritt messen \u2192 t\u2080 aus Tabelle \u2192 Rohrtemperatur t\u2082\u2095 messen \u2192 \u0394t = t\u2082\u2095 \u2013 t\u2080." },
  { id: 36, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Folgen hat eine zu geringe \u00dcberhitzung im Verdampfer?", answer: "Fl\u00fcssigkeit kann in den Verdichter gelangen \u2192 Fl\u00fcssigkeitsschl\u00e4ge, Zerst\u00f6rung." },
  { id: 37, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Folgen hat eine zu gro\u00dfe \u00dcberhitzung im Verdampfer?", answer: "Verdampferfl\u00e4che wird schlechter genutzt \u2192 K\u00e4lteleistung und Effizienz sinken." },
  { id: 38, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist in Bezug auf K\u00e4lteanlagen unter dem Begriff Unterk\u00fchlung zu verstehen?", answer: "Abk\u00fchlung der Fl\u00fcssigkeit unter die Verfl\u00fcssigungstemperatur. Nur 100 % Fl\u00fcssigkeit kann unterk\u00fchlt werden." },
  { id: 39, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum ist es notwendig, dass das K\u00e4ltemittel vor dem Expansionsorgan unterk\u00fchlt ist?", answer: "Damit dem Ventil blasenfreie Fl\u00fcssigkeit zugef\u00fchrt wird \u2013 Dampfblasen st\u00f6ren die Regelung und verursachen Sch\u00e4den." },
  { id: 40, block: "Grundlagen der K\u00e4ltetechnik", question: "Wie wird die Unterk\u00fchlung in der Praxis gemessen?", answer: "Verfl\u00fcssigungsdruck pC am Eintritt Expansionsorgan \u2192 tC aus Tabelle \u2192 Rohrtemperatur t\u2081\u1d64 messen \u2192 \u0394t = tC \u2013 t\u2081\u1d64." },
  { id: 41, block: "Grundlagen der K\u00e4ltetechnik", question: "Was sind die Folgen von zu geringer Unterk\u00fchlung in der Fl\u00fcssigkeitsleitung?", answer: "Druckabf\u00e4lle f\u00fchren zu Vorverdampfung \u2192 Dampfblasen \u2192 Fehlregelung, Dampfschl\u00e4ge, Rohrbr\u00fcche." },
  { id: 42, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche M\u00f6glichkeiten gibt es, um nutzbare Unterk\u00fchlung zu gewinnen?", answer: "Nach dem Sammler (externe Unterk\u00fchler, innerer W\u00e4rme\u00fcbertrager) \u2013 nur dort ist 100 % Fl\u00fcssigkeit." },
  { id: 43, block: "Grundlagen der K\u00e4ltetechnik", question: "Kann im Verfl\u00fcssiger nutzbare Unterk\u00fchlung gewonnen werden, wenn ein Sammler eingebaut ist?", answer: "Nein, nutzbare Unterk\u00fchlung nur nach dem Sammler \u2013 im Verfl\u00fcssiger ist ein Zweiphasengemisch." },
  { id: 44, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Unterk\u00fchlungswerte k\u00f6nnen ohne externen Unterk\u00fchler gewonnen werden?", answer: "Ca. 1\u20133 K durch W\u00e4rmeabgabe der Fl\u00fcssigkeitsleitung an die Umgebung. Bei hohen Temperaturen oder Sonneneinstrahlung auch 0 K." },
  { id: 45, block: "Grundlagen der K\u00e4ltetechnik", question: "An welcher Stelle im K\u00e4ltekreislauf ist die h\u00f6chste und niedrigste Temperatur?", answer: "H\u00f6chste: Verdichteraustritt (Verdichtungsendtemperatur). Niedrigste: Verdampfereintritt nach der Drosselung." },
  { id: 46, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist unter dem Begriff Enthitzung zu verstehen und wo findet diese statt?", answer: "Abk\u00fchlung des \u00fcberhitzten Dampfes auf Verfl\u00fcssigungstemperatur. Findet in Druckleitung und erstem Teil des Verfl\u00fcssigers statt." },
  { id: 47, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche gemeinsame Eigenschaft haben Verdampfer und Verfl\u00fcssiger?", answer: "Beide sind W\u00e4rme\u00fcbertrager mit Phasenwechsel \u2013 K\u00e4ltemittel ist darin sowohl fl\u00fcssig als auch gasf\u00f6rmig." },
  { id: 48, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche gemeinsame Eigenschaft haben Verdichter und Drosselorgan?", answer: "Beide trennen Hoch- und Niederdruckseite und f\u00fchren eine Druck\u00e4nderung herbei." },
  { id: 49, block: "Grundlagen der K\u00e4ltetechnik", question: "Welche Aufgabe hat der Verdampfer in einer K\u00e4lteanlage?", answer: "W\u00e4rme aus dem K\u00fchlraum aufnehmen und ans K\u00e4ltemittel \u00fcbertragen, das dabei verdampft." },
  { id: 50, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist der Unterschied zwischen trockener und \u00fcberfluteter Verdampfung?", answer: "Trocken: K\u00e4ltemittel verl\u00e4sst den Verdampfer \u00fcberhitzt. \u00dcberflutet: Verdampfer mit Fl\u00fcssigkeit gef\u00fcllt, Austritt als Dampf-Fl\u00fcssigkeits-Gemisch (oft NH\u2083)." },
  { id: 51, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche zwei Zonen gibt es in einem Verdampfer (trockene Verdampfung)?", answer: "Verdampfungszone (latent, T konstant) und \u00dcberhitzungszone (sensibel, T steigt)." },
  { id: 52, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "In welcher Zone des Verdampfers erfolgt sensible, in welcher latente W\u00e4rmeaufnahme?", answer: "Latent: Verdampfungszone. Sensibel: \u00dcberhitzungszone." },
  { id: 53, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist unter direkter und indirekter K\u00fchlung zu verstehen?", answer: "Direkt: Verdampfer im K\u00fchlraum, K\u00e4ltemittel direkt. Indirekt: K\u00e4ltetr\u00e4ger zwischen Verdampfer und K\u00fchlstelle (Sole, Glykol)." },
  { id: 54, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Nenne 3 Verdampferbauformen und Einsatzbereiche.", answer: "Bauform Einsatz Lamellenw\u00e4rme\u00fcbertrager K\u00fchlr\u00e4ume, Vitrinen, W\u00e4rmepumpen Plattenw\u00e4rme\u00fcbertrager Kaltwassers\u00e4tze, W\u00e4rmepumpen Rohrb\u00fcndelw\u00e4rme\u00fcbertrager Kaltwassers\u00e4tze, Industrie" },
  { id: 55, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Auswirkung hat ein stark verschmutzter Lamellenverdampfer?", answer: "W\u00e4rme\u00fcbertragungsfl\u00e4che sinkt \u2192 Verdampferleistung sinkt." },
  { id: 56, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Auswirkung hat ein defekter L\u00fcfter eines Lamellenverdampfers?", answer: "Weniger Luft \u2192 Leistung sinkt, Vereisung m\u00f6glich, Hunting-Gefahr." },
  { id: 57, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Auswirkung hat ein vereister Lamellenverdampfer?", answer: "Eis wirkt als Isolator \u2192 W\u00e4rme\u00fcbertragungsfl\u00e4che sinkt \u2192 Verdampferleistung sinkt, ND-St\u00f6rungen m\u00f6glich." },
  { id: 58, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche M\u00f6glichkeiten der Abtauung gibt es?", answer: "Elektrisch, Hei\u00dfgas, Kaltgas, Umluft (ab 4 \u00b0C), Warmsole." },
  { id: 59, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was passiert auf der Verdampferoberfl\u00e4che bei sehr tiefen Temperaturen?", answer: "Reifbildung \u2192 W\u00e4rme\u00fcbertragung wird schlechter \u2192 K\u00e4lteleistung und Effizienz sinken \u2192 regelm\u00e4\u00dfige Abtauung n\u00f6tig." },
  { id: 60, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Auswirkung hat eine starke Bereifung auf die K\u00e4lteleistung?", answer: "K\u00e4lteleistung sinkt, da die W\u00e4rme\u00fcbertragungsfl\u00e4che reduziert ist." },
  { id: 61, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Wodurch kann die Abtauung bei einem Verdampfer eingeleitet werden?", answer: "Zeitschaltuhr oder Bedarfsabtauung (Temperatur-/Drucksensorik)." },
  { id: 62, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist stille/statische K\u00fchlung?", answer: "Luftzirkulation nur durch nat\u00fcrliche Konvektion (kein Ventilator). Einsatz: empfindliche K\u00fchlg\u00fcter (Blumen, Gem\u00fcse)." },
  { id: 63, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Verdampfer total vereist, Heizstab defekt \u2013 welche Abtaumethoden?", answer: "Hei\u00dfluft (externer Heizl\u00fcfter, vorsichtig), Warmwasser, aber nie Gasbrenner! (Besch\u00e4digung, Sicherheit)." },
  { id: 64, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Warum sollte die Temperaturdifferenz Raum/Verdampfung so klein wie m\u00f6glich sein?", answer: "Je kleiner \u0394T, desto h\u00f6her die Verdampfungstemperatur \u2192 besserer COP (ca. 3\u2013 4 % pro Kelvin)." },
  { id: 65, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Nach welchen Faktoren wird der Lamellenabstand bei Verdampfern festgelegt?", answer: "Nach Anwendung: NK (\u22650 \u00b0C) 4\u20135 mm, TK 7\u20139 mm, hohe Feuchtelast (\u2264 \u20133 \u00b0C) 10\u201312 mm." },
  { id: 66, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was sind die Aufgaben eines Verdichters?", answer: "Ansaugen bei Niederdruck, verdichten auf Hochdruck, Druckdifferenz aufrechterhalten und Massenstrom sichern." },
  { id: 67, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Verdichterbauformen gibt es?", answer: "Hubkolben, Scroll, Rollkolben, Schrauben, Turbo." },
  { id: 68, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist unter einem hermetischen Verdichter zu verstehen?", answer: "Motor und Verdichter verschwei\u00dft \u2013 keine Reparatur. Einsatz: kleine bis mittlere Leistungen." },
  { id: 69, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist ein halbhermetischer Verdichter?", answer: "Motor und Verdichter in verschraubtem Geh\u00e4use \u2013 bedingt reparierbar. Mit/ohne Sauggask\u00fchlung." },
  { id: 70, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist ein offener Verdichter und wo wird er eingesetzt?", answer: "Motor und Verdichter getrennt, Welle nach au\u00dfen gef\u00fchrt. Antrieb frei w\u00e4hlbar. Einsatz: Ammoniakanlagen, Kfz." },
  { id: 71, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist zweistufige Verdichtung und wann ist sie notwendig?", answer: "Wenn die Temperaturdifferenz Verdampfung/Verfl\u00fcssigung > 70 K (HFKW). Verhindert zu hohe Verdichtungsendtemperatur." },
  { id: 72, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Verdichterbauform wird \u00fcberwiegend in Split-Klimager\u00e4ten verbaut?", answer: "Rollkolbenverdichter (Swingverdichter)." },
  { id: 73, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Bauform hat einen externen Fl\u00fcssigkeitsabscheider und warum?", answer: "Rollkolbenverdichter \u2013 anf\u00e4llig gegen Nassfahren, daher Abscheider am Sauggaseintritt." },
  { id: 74, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Worauf muss bei Schrauben-/Scrollverdichtern mit 400 V bei Inbetriebnahme geachtet werden?", answer: "Rechtsdrehfeld \u2013 falsche Drehrichtung f\u00fchrt zu schweren Sch\u00e4den." },
  { id: 75, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Warum hat ein Schraubenverdichter einen besseren Liefergrad als ein Hubkolbenverdichter?", answer: "Hubkolben: R\u00fcckexpansion im Totraum. Schrauben: vollst\u00e4ndiges Ausschieben, keine R\u00fcckexpansion." },
  { id: 76, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Warum wird Ammoniak (R-717) nicht bei hermetischen Verdichtern eingesetzt?", answer: "Ammoniak greift Kupfer an \u2013 zerst\u00f6rt die Kupferwicklungen. Offene Verdichter mit Aluminiumwicklungen oder Stahl." },
  { id: 77, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Verdichterbauform wird bei Ammoniakanlagen verwendet?", answer: "\u00dcberwiegend offene Verdichter." },
  { id: 78, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Wie verh\u00e4lt sich die K\u00e4lteleistung eines Verdichters bei sinkender Verdampfungstemperatur?", answer: "Die K\u00e4lteleistung sinkt." },
  { id: 79, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist ein Verdichtereinsatzgrenzendiagramm?", answer: "Diagramm mit Verdampfungs- und Verfl\u00fcssigungstemperatur auf den Achsen \u2013 zeigt die zul\u00e4ssigen Betriebsbereiche." },
  { id: 80, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Nenne M\u00f6glichkeiten der Verdichterleistungsregelung.", answer: "\u00b7 Drehzahlregelung mit Frequenzumformer (effizient) \u00b7 Zylinderabschaltung \u00b7 Polumschaltung \u00b7 Mehrere Verdichter im Verbund \u00b7 Hei\u00dfgas-Bypass (unwirtschaftlich)" },
  { id: 81, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist R\u00fcckexpansion bei einem Kolbenverdichter?", answer: "Gasentspannung im Totraum beim Abw\u00e4rtshub \u2013 Saugventil \u00f6ffnet erst, wenn Druck unter Saugdruck f\u00e4llt \u2192 Liefergradverlust." },
  { id: 82, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist die Leistungszahl eines Verdichters und woraus wird sie ermittelt?", answer: "COP = K\u00e4lteleistung / elektrische Leistungsaufnahme." },
  { id: 83, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist ein sauggasgek\u00fchlter Verdichter?", answer: "Sauggas wird \u00fcber die Motorwicklung gef\u00fchrt \u2192 k\u00fchlt den Motor, aber erh\u00f6ht die \u00dcberhitzung (bis zu 40 K Gesamt\u00fcberhitzung)." },
  { id: 84, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Positiver Effekt, wenn im Tiefk\u00fchlbereich keine sauggasgek\u00fchlten Verdichter verwendet werden?", answer: "Keine zus\u00e4tzliche \u00dcberhitzung \u2192 geringere Verdichtungsendtemperatur. K\u00fchlung durch L\u00fcfter/Zylinderkopfk\u00fchlung." },
  { id: 85, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche weiteren M\u00f6glichkeiten f\u00fcr Verdichter-Zusatzk\u00fchlungen gibt es?", answer: "Kopfl\u00fcfter, K\u00fchlschlangen ums Geh\u00e4use, wassergek\u00fchlte Zylinderk\u00f6pfe, K\u00e4ltemitteleinspritzung, \u00d6lk\u00fchler." },
  { id: 86, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Methoden der Verdichterschmierung gibt es?", answer: "\u00b7 Druckumlaufschmierung (\u00d6lpumpe) \u00b7 Schleuderschmierung (\u00d6lschleuderbleche) \u00b7 Zentrifugalschmierung (Axialbohrung in der Welle) 87\u201389. Erkl\u00e4re die drei Schmierprinzipien. \u00b7 Schleuderschmierung: Rotierende Teile tauchen in den \u00d6lsumpf und schleudern \u00d6l zu den Schmierstellen. \u00b7 Druckumlaufschmierung: \u00d6lpumpe saugt \u00d6l an und pumpt es \u00fcber \u00d6lkan\u00e4le zu den Schmierstellen. \u00b7 Zentrifugalschmierung: Schr\u00e4ge Bohrung in der stehenden Welle \u2013 \u00d6l wird durch Zentrifugalkraft nach oben bef\u00f6rdert." },
  { id: 89, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Erkl\u00e4re das Prinzip der Zentrifugalschmierung.", answer: "Schr\u00e4ge Bohrung in der stehenden Welle \u2013 Zentrifugalkraft bef\u00f6rdert \u00d6l nach oben zu den Schmierstellen." },
  { id: 90, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Wozu werden \u00d6lheizungen im Kurbelgeh\u00e4use verwendet und wann sind sie eingeschaltet?", answer: "Verhindern Eindiffundieren von K\u00e4ltemittel ins \u00d6l im Stillstand. Eingeschaltet, wenn der Verdichter steht." },
  { id: 91, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Warum darf die Verdichtungsendtemperatur nicht zu hoch sein?", answer: "F\u00f6rdert \u00d6lzersetzung und Korrosion an den Druckventilen (Reaktionsgeschwindigkeit steigt mit Temperatur)." },
  { id: 92, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Wodurch machen sich M\u00e4ngel an Saug-/Druckventilen bemerkbar?", answer: "Schneller Druckausgleich nach Abschaltung, K\u00e4ltemittel l\u00e4sst sich nicht auf 0 bar absaugen, hohe Verdichtungsendtemperatur, Temperaturunterschiede zwischen Zylindern, K\u00e4lteleistung sinkt." },
  { id: 93, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist \u00d6lwurf und wie gro\u00df ist er?", answer: "Vom Verdichter ausgesto\u00dfenes \u00d6l, das mit dem K\u00e4ltemittel in die Anlage transportiert wird. 1\u20133 % des Massenstroms." },
  { id: 94, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Wie ist ein Trennhaubenverdichter aufgebaut? Vor- und Nachteile?", answer: "Hubkolben mit senkrechter Welle, Motor durch d\u00fcnne Trennhaube vom K\u00e4ltemittel getrennt. Vorteil: K\u00e4ltekreislauf bleibt bei Motorschaden sauber." },
  { id: 95, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Welche Aufgabe hat das \u00d6l bei Schraubenverdichtern im Rotorgeh\u00e4use?", answer: "Schmieren, Abdichten, W\u00e4rme abf\u00fchren (\u00fcber \u00d6lk\u00fchler)." },
  { id: 96, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Warum ist es nicht zul\u00e4ssig, die Drehzahl bei drehzahlgeregelten Verdichtern beliebig tief zu senken?", answer: "Bei zu geringer Drehzahl: Schmierung nicht mehr sichergestellt \u2192 Mangelschmierung, Sch\u00e4den; auch Schwingungsgefahr." },
  { id: 97, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist die Aufgabe des Verfl\u00fcssigers?", answer: "W\u00e4rme vom K\u00e4ltemittel an die Umgebung abgeben, sodass es verfl\u00fcssigt." },
  { id: 98, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Nenne 3 Verfl\u00fcssigerbauformen.", answer: "\u00b7 Luftgek\u00fchlte Verfl\u00fcssiger (Lamellenw\u00e4rme\u00fcbertrager) \u00b7 Wassergek\u00fchlte Verfl\u00fcssiger (Platten-, Rohrb\u00fcndelw\u00e4rme\u00fcbertrager) \u00b7 Verdunstungsverfl\u00fcssiger (adiabate K\u00fchlung)" },
  { id: 99, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist ein statischer Verfl\u00fcssiger und wo wird er eingesetzt?", answer: "Kein Ventilator, W\u00e4rmeabgabe nur durch nat\u00fcrliche Konvektion. Einsatz: sehr kleine Leistungen (K\u00fchlschr\u00e4nke)." },
  { id: 100, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was versteht man unter einem Verfl\u00fcssigungssatz?", answer: "Kombination aus Verdichter + Verfl\u00fcssiger, oft mit Sammler und Anschlusskasten auf einem Gestell." },
  { id: 101, block: "Verdichter", question: "Worauf ist bei der Aufstellung luftgek\u00fchlter Verfl\u00fcssiger zu achten?", answer: "Ausreichend Luftzirkulation (Zu-/Abluft), keine direkte Sonne, geringe Verschmutzungsgefahr." },
  { id: 102, block: "Verdichter", question: "Welche Auswirkung hat eine steigende Lufteintrittstemperatur auf den Verfl\u00fcssigungsdruck?", answer: "Der Verfl\u00fcssigungsdruck steigt, weil die Temperaturdifferenz zum Medium gr\u00f6\u00dfer werden muss." },
  { id: 103, block: "Verdichter", question: "Wodurch ergibt sich die H\u00f6he der Verfl\u00fcssigungstemperatur?", answer: "Durch die Auslegung des Verfl\u00fcssigers (Leistung, max. Au\u00dfentemperatur, gew\u00e4hlte Temperaturdifferenz)." },
  { id: 104, block: "Verdichter", question: "Welche M\u00f6glichkeiten der Verfl\u00fcssigungsdruckregelung gibt es?", answer: "Drehzahlregelung des L\u00fcfters (FU, Phasenanschnitt), Verfl\u00fcssigungsdruckregler (KVR), Wassermengenregler." },
  { id: 105, block: "Verdichter", question: "Welche Auswirkung hat eine verschmutzte Verfl\u00fcssigeroberfl\u00e4che?", answer: "Verfl\u00fcssigungsdruck steigt, Verdichtungsendtemperatur steigt, COP und K\u00e4lteleistung sinken, Betriebskosten steigen." },
  { id: 106, block: "Verdichter", question: "Was passiert, wenn bei einem wassergek\u00fchlten Verfl\u00fcssiger die K\u00fchlwassermenge reduziert wird?", answer: "Verfl\u00fcssigungstemperatur steigt \u2192 bei \u00dcberschreitung des max. Betriebsdrucks Abschaltung durch Sicherheitseinrichtung." },
  { id: 107, block: "Verdichter", question: "Worauf ist zu achten, wenn Verfl\u00fcssigungss\u00e4tze in geschlossenen R\u00e4umen aufgestellt werden?", answer: "Ausreichende Frischluftzufuhr, ggf. Frischluftkanal \u2013 sonst steigt die Raumtemperatur und damit der Verfl\u00fcssigungsdruck." },
  { id: 108, block: "Verdichter", question: "G\u00e4ngige Temperaturdifferenzen zwischen Verfl\u00fcssigungstemperatur und K\u00fchlmedium bei Luftk\u00fchlung?", answer: "10\u201312 K." },
  { id: 109, block: "Verdichter", question: "Was passiert, wenn der Verfl\u00fcssiger stark verschmutzt ist?", answer: "Verfl\u00fcssigungsdruck \u2191, Verdichtungsendtemperatur \u2191, Leistungsaufnahme \u2191, COP \u2193, K\u00e4lteleistung \u2193 (gr\u00f6\u00dferer Drosseldampfanteil)." },
  { id: 110, block: "Verdichter", question: "Wie funktioniert ein Verdunstungsverfl\u00fcssiger (adiabate K\u00fchlung)?", answer: "K\u00e4ltemittelrohre werden mit Wasser bespr\u00fcht \u2192 Verdunstung k\u00fchlt \u2192 effektive Temperatur sinkt Richtung Feuchtkugeltemperatur." },
  { id: 111, block: "Verdichter", question: "Warum darf der Verfl\u00fcssigungsdruck im Winter nicht zu tief absinken?", answer: "TEV ben\u00f6tigt Mindestdruckdifferenz \u2013 sonst Verdampfer unterversorgt \u2192 Leistungsabfall, ND-Abschaltung." },
  { id: 112, block: "Verdichter", question: "Welche Aufgabe haben Drosselorgane?", answer: "K\u00e4ltemittel vom Verfl\u00fcssigungsdruck auf Verdampfungsdruck drosseln und in den Verdampfer einspritzen. Trennung Hoch-/Niederdruck." },
  { id: 113, block: "Verdichter", question: "Welche Bauformen von Drosselorganen gibt es?", answer: "Kapillarrohr, Drosselblende, TEV (intern/extern), MOP-Ventil, EEV (pulsweitenmodulierend/Schrittmotor), Schwimmerventile." },
  { id: 115, block: "Verdichter", question: "Bei welchen K\u00e4lteanlagen werden Kapillarrohre verwendet?", answer: "Kleine Anlagen mit konstanter K\u00e4ltelast (K\u00fchlschrank, Gefriertruhe) \u2013 ohne Sammler." },
  { id: 116, block: "Verdichter", question: "Aufgabe und Funktionsweise TEV \u2013 Kr\u00e4ftegleichgewicht?", answer: "Regelt Einspritzmenge f\u00fcr vollst\u00e4ndige Verdampfung mit leichter \u00dcberhitzung. \u00d6ffnungskraft: F\u00fchlerdruck. Schlie\u00dfkr\u00e4fte: Verdampfungsdruck + Federkraft. \u00d6ffnung, wenn p_F > p\u2080 + p_S." },
  { id: 117, block: "Verdichter", question: "Wie ist der F\u00fchler eines TEV am Rohr zu positionieren und warum?", answer: "Am waagerechten Rohr, 1\u20133 Uhr (je nach Durchmesser), nie unten (\u00d6l verf\u00e4lscht), nicht nach \u00d6lhebebogen, vor Fremdw\u00e4rme und Kaltluft sch\u00fctzen, gut befestigen." },
  { id: 118, block: "Verdichter", question: "Was kann an der Einstellschraube am TEV eingestellt werden?", answer: "Die statische \u00dcberhitzung (Anteil der Gesamt\u00fcberhitzung)." },
  { id: 119, block: "Verdichter", question: "Worauf ist beim Einstellen der TEV-\u00dcberhitzung zu achten?", answer: "Messger\u00e4te bereit, ausreichende F\u00fcllmenge, blasenfreie unterk\u00fchlte Fl\u00fcssigkeit vor TEV, Verfl\u00fcssigungsdruck im Auslegungszustand, keine starke Vereisung, Spindel in kleinen Schritten verstellen, Geduld (TEV reagiert tr\u00e4ge)." },
  { id: 120, block: "Verdichter", question: "Was ist unter dem Begriff \u201eHunting\u201c zu verstehen?", answer: "Periodisches Auf- und Zuschwingen des TEV \u2192 Saugdruck schwankt \u2192 Fl\u00fcssigkeit in Saugleitung m\u00f6glich." },
  { id: 121, block: "Verdichter", question: "Woran soll erkennbar sein, welche D\u00fcse sich im TEV befindet?", answer: "Deckel der D\u00fcsenverpackung mit Gr\u00f6\u00dfenangabe sollte auf dem F\u00fchlerkapillarrohr befestigt sein." },
  { id: 122, block: "Verdichter", question: "Unterschied TEV mit internem vs. externem Druckausgleich?", answer: "Intern: p\u2080 am Eintritt wirkt als Schlie\u00dfkraft. Extern: Druck vom Austritt \u00fcber separate Leitung \u2192 kompensiert Verdampfer-Druckabfall." },
  { id: 123, block: "Verdichter", question: "Wann TEV mit \u00e4u\u00dferem Druckausgleich einsetzen?", answer: "\u0394p Verdampfer > 0,2 bar (NK) / > 0,1 bar (TK), Rohrl\u00e4nge > 30 m, Mehrfacheinspritzung mit Verteiler." },
  { id: 124, block: "Verdichter", question: "Was passiert, wenn ein TEV mit innerem Druckausgleich an einem Verdampfer mit gro\u00dfem Druckabfall angeschlossen ist?", answer: "Verdampfer wird unterversorgt \u2192 \u00dcberhitzung zu hoch \u2192 Leistung und Effizienz sinken." },
  { id: 125, block: "Verdichter", question: "Warum m\u00fcssen Druckausgleichsleitungen immer oben am Rohr angeschlossen werden?", answer: "Damit kein \u00d6l in die Leitung flie\u00dft und die Messung verf\u00e4lscht." },
  { id: 126, block: "Verdichter", question: "Warum haben Kapillarrohranlagen keinen Sammler?", answer: "Druckausgleich nach Abschaltung, die F\u00fcllmenge muss sehr exakt abgestimmt sein \u2013 Bef\u00fcllung nur mit F\u00fcllzylinder oder elektronischer Waage." },
  { id: 127, block: "Verdichter", question: "Welche zwei Bauformen elektronischer Expansionsventile gibt es?", answer: "Pulsweitenmodulierend (PWM) und Schrittmotor-Expansionsventil." },
  { id: 128, block: "Verdichter", question: "Welche Vorteile bieten EEV und wo werden sie eingesetzt?", answer: "H\u00f6here Regelgenauigkeit (\u00b10,5 K), kleinere \u00dcberhitzung (4\u20136 K), stabiles Regelverhalten, schnellere Reaktion, Energieeffizienzsteigerung 10\u201320 %, integrierte MOP-Funktion. Einsatz: anspruchsvolle Regelung, hohe Effizienzanforderungen." },
  { id: 129, block: "Verdichter", question: "Erkl\u00e4ren Sie die Funktion eines MOP-Ventils. MOP = Maximum Operating Pressure. Ein TEV, das den Verdampfungsdruck auf einen Maximalwert begrenzt. Der F\u00fchler enth\u00e4lt eine definierte Nassdampfmenge, die bei einer festgelegten Temperatur vollst\u00e4ndig", answer: "verdampft. Bei \u00dcberschreitung steigt der F\u00fchlerdruck nicht weiter \u2192 Ventil \u00f6ffnet nicht weiter." },
  { id: 130, block: "Verdichter", question: "In welchen F\u00e4llen werden MOP-Ventile eingesetzt?", answer: "Tiefk\u00fchlanlagen nach Abtauung, Anlaufschutz f\u00fcr Verdichter und Verfl\u00fcssiger." },
  { id: 132, block: "Verdichter", question: "F\u00fcr welche K\u00fchlaufgabe sind MOP-Ventile ungeeignet?", answer: "Schnellk\u00fchlung (Schockfroster) \u2013 Anlaufphase w\u00e4re zu lang. Hier andere Ma\u00dfnahmen (Fl\u00fcssigkeitsabscheider, Teillastregelung)." },
  { id: 133, block: "Verdichter", question: "Wie wird der maximale \u00d6ffnungsdruck eines MOP-Ventils festgelegt?", answer: "MOP-Punkt = projektierten Verdampfungsdruck + 0,5 bis 1 bar Reserve." },
  { id: 134, block: "Verdichter", question: "Was passiert, wenn der MOP-Punkt zu tief gew\u00e4hlt wird?", answer: "Verdampfer wird auf zu tiefen Wert abgesaugt \u2192 es dauert sehr lange, bis ein normaler Betriebspunkt erreicht wird." },
  { id: 135, block: "Verdichter", question: "Was bedeutet Mehrfacheinspritzung und wann ist sie notwendig?", answer: "Aufteilung des Verdampfers in mehrere parallele, gleich lange Str\u00e4nge, um den Druckabfall zu reduzieren. Jeder Strang erh\u00e4lt gleich viel K\u00e4ltemittel." },
  { id: 136, block: "Verdichter", question: "Welche TEV-Type ist bei Mehrfacheinspritzung zu verwenden und warum?", answer: "TEV mit \u00e4u\u00dferem Druckausgleich \u2013 der Druckabfall \u00fcber den Verteiler muss kompensiert werden." },
  { id: 137, block: "Verdichter", question: "Auswirkung, wenn eine Verteilerleitung einen geringeren Druckabfall hat als die anderen?", answer: "Durch diesen Strang str\u00f6mt mehr K\u00e4ltemittel \u2192 er ist nicht vollst\u00e4ndig verdampft \u2192 \u00dcberhitzung steigt \u2192 TEV drosselt \u2192 alle anderen Str\u00e4nge bekommen weniger K\u00e4ltemittel \u2192 Verdampfer unterversorgt." },
  { id: 138, block: "Verdichter", question: "Was ist unter Drosseldampf zu verstehen?", answer: "Bei der Expansion verdampft ein Teil des K\u00e4ltemittels sofort (ca. 30 %), um den Rest abzuk\u00fchlen \u2013 dieser Dampf tr\u00e4gt nicht zur K\u00e4lteleistung bei." },
  { id: 139, block: "Verdichter", question: "Welche Leitung verbindet Verdichter mit Verfl\u00fcssiger? Druck, Zustand?", answer: "Druckleitung \u2013 Verfl\u00fcssigungsdruck, gasf\u00f6rmig \u00fcberhitzt." },
  { id: 140, block: "Verdichter", question: "Welche Leitung verbindet Verfl\u00fcssiger mit Sammler? Druck, Zustand?", answer: "Kondensatleitung \u2013 Verfl\u00fcssigungsdruck, vorwiegend fl\u00fcssig (Gasr\u00fcckstr\u00f6mung m\u00f6glich)." },
  { id: 141, block: "Verdichter", question: "Welche Leitung verbindet Sammler mit Expansionsorgan? Druck, Zustand?", answer: "Fl\u00fcssigkeitsleitung \u2013 Verfl\u00fcssigungsdruck, fl\u00fcssig, unterk\u00fchlt." },
  { id: 142, block: "Verdichter", question: "Welche Leitung verbindet Expansionsorgan mit Verdampfer? Druck, Zustand?", answer: "Einspritzleitung \u2013 Verdampfungsdruck, ca. 70 % fl\u00fcssig, 30 % gasf\u00f6rmig (Nassdampf)." },
  { id: 143, block: "Verdichter", question: "Welche Leitung verbindet Verdampfer mit Verdichter? Druck, Zustand?", answer: "Saugleitung \u2013 Verdampfungsdruck, gasf\u00f6rmig, \u00fcberhitzt." },
  { id: 144, block: "Verdichter", question: "Nenne wesentliche Grunds\u00e4tze der Rohrleitungsf\u00fchrung.", answer: "\u00b7 Druckverluste minimieren \u00b7 \u00d6ltransport und \u00d6lr\u00fcckf\u00fchrung sicherstellen \u00b7 Gef\u00e4lle in Str\u00f6mungsrichtung: 2 % bei Mehrphasigkeit \u00b7 Hebeleitungen senkrecht: max. 5 m bei glattem Kupferrohr \u00b7 Keine schr\u00e4g steigenden Installationen \u00b7 \u00d6ls\u00e4cke und \u00d6lfallen vermeiden \u00b7 In Fl\u00fcssigkeitsleitungen: Gass\u00e4cke vermeiden \u00b7 Fl\u00fcssige Abg\u00e4nge von unten im Sammelrohr \u00b7 Rohrleitungswerkstoffe m\u00fcssen f\u00fcr das K\u00e4ltemittel geeignet sein \u00b7 Oberfl\u00e4chentemperatur < Umgebungstemperatur \u2192 d\u00e4mmen" },
  { id: 145, block: "Verdichter", question: "Worauf ist bei l\u00e4ngeren Druckleitungen bzgl. L\u00e4ngen\u00e4nderung zu achten?", answer: "Thermische L\u00e4ngen\u00e4nderung \u2192 nicht beidseitig fix montieren \u2192 Loslager/Gleitlager vorsehen \u2013 sonst Spannungen, Rohrbr\u00fcche." },
  { id: 146, block: "Verdichter", question: "Was ist Vorverdampfung? Auswirkungen? Wie verhindern?", answer: "Dampfblasen in der Fl\u00fcssigkeitsleitung durch Druckabfall. Folgen: Leistungsverlust, Fehlregelung, Sch\u00e4den (Kavitation). Verhindern: ausreichende Unterk\u00fchlung, Druckabf\u00e4lle minimieren." },
  { id: 147, block: "Verdichter", question: "Warum sollen Druckabf\u00e4lle in Rohrleitungen vermieden werden?", answer: "Druckleitung/Saugleitung: Verdichter muss h\u00f6here Druckdifferenz \u00fcberwinden \u2192 COP sinkt. Fl\u00fcssigkeitsleitung: Gefahr der Vorverdampfung." },
  { id: 148, block: "Verdichter", question: "In welcher Rohrleitung und an welcher Stelle soll ein Schauglas eingebaut werden?", answer: "In der Fl\u00fcssigkeitsleitung vor dem Expansionsventil (nach eventuellem Magnetventil), um blasenfreie Fl\u00fcssigkeit zu pr\u00fcfen." },
  { id: 149, block: "Verdichter", question: "Warum sind Rohrleitungsverbindungen spannungsfrei auszuf\u00fchren?", answer: "Verbindungen unter Zug/Druck werden undicht oder brechen. Rohr vor dem Verbinden ohne Kraft in Position halten." },
  { id: 150, block: "Verdichter", question: "Welche Auswirkungen hat ein zu kleiner Durchmesser in der Saugleitung?", answer: "Hoher Druckabfall \u2192 Verdichter muss h\u00f6here Druckdifferenz \u00fcberwinden \u2192 COP sinkt." },
  { id: 151, block: "Verfl\u00fcssiger & Verdampfer", question: "Welche Auswirkung hat ein zu kleiner Durchmesser in der Fl\u00fcssigkeitsleitung?", answer: "Hoher Druckabfall \u2192 Vorverdampfungsgefahr bei nicht ausreichender Unterk\u00fchlung." },
  { id: 152, block: "Verfl\u00fcssiger & Verdampfer", question: "Warum m\u00fcssen Saugleitungen isoliert werden?", answer: "Kondensatbildung verhindern, W\u00e4rmeeintrag vermeiden (sonst zu hohe Ansaug\u00fcberhitzung)." },
  { id: 153, block: "Verfl\u00fcssiger & Verdampfer", question: "Wann m\u00fcssen Fl\u00fcssigkeitsleitungen isoliert werden?", answer: "Bei W\u00e4rmeeintrag (Sonne, warme Bereiche) \u2013 sonst wird Unterk\u00fchlung abgebaut." },
  { id: 154, block: "Verfl\u00fcssiger & Verdampfer", question: "Wann m\u00fcssen Druckleitungen isoliert werden?", answer: "Bei W\u00e4rmer\u00fcckgewinnung/W\u00e4rmepumpen, damit die Enthitzungsw\u00e4rme nicht verloren geht." },
  { id: 155, block: "Verfl\u00fcssiger & Verdampfer", question: "Wie sind Flanschverbindungen richtig anzuziehen?", answer: "Erst Hand, dann \u00fcber Kreuz mit Drehmomentschl\u00fcssel \u2013 richtiges Drehmoment beachten." },
  { id: 156, block: "Verfl\u00fcssiger & Verdampfer", question: "Was sagt die \u00d6NORM EN 378-2 \u00fcber B\u00f6rdelverbindungen?", answer: "Max. Rohr-\u00d8 20 mm, spannungsfrei montieren, vor Einfrieren und Schwingungen sch\u00fctzen, mit Drehmomentschl\u00fcssel anziehen." },
  { id: 157, block: "Verfl\u00fcssiger & Verdampfer", question: "Warum sind Rohrleitungen bei Transport und Lagerung immer verschlossen zu halten?", answer: "Schutz vor Schmutz und Feuchtigkeit \u2013 sonst St\u00f6rungen und Verunreinigung der gesamten Anlage." },
  { id: 158, block: "Verfl\u00fcssiger & Verdampfer", question: "Wie ist die Kondensatleitung zwischen Verfl\u00fcssiger und Sammler auszuf\u00fchren?", answer: "So kurz wie m\u00f6glich, mit Gef\u00e4lle zum Sammler (min. 2 %), ausreichender Durchmesser f\u00fcr Druckausgleich, Sammlereintritt unter Verfl\u00fcssigeraustritt." },
  { id: 159, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist eine Impulsleitung?", answer: "K\u00e4ltemittelf\u00fchrende Leitung zu Steuer-/Regeleinrichtungen (Drucktransmitter). Kein Durchfluss, nur statische Druck\u00fcbertragung." },
  { id: 160, block: "Verfl\u00fcssiger & Verdampfer", question: "Welches Kupferrohr wird in der K\u00e4ltetechnik verwendet? Worauf achten?", answer: "Kupferrohr nach DIN EN 12735-1, innen gereinigt und entfettet, verschiedene H\u00e4rtegrade (R 220 = gegl\u00fcht). Handhabung: nicht verschmutzen, verschlossen lagern." },
  { id: 161, block: "Verfl\u00fcssiger & Verdampfer", question: "Welche Aufgabe hat das K\u00e4ltemittel in einer K\u00e4lteanlage?", answer: "Bei tiefer Temperatur verdampfen und W\u00e4rme aufnehmen, bei hoher Temperatur verfl\u00fcssigen und W\u00e4rme abgeben. Es ist der W\u00e4rmetr\u00e4ger." },
  { id: 162, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist ein Reinstoffk\u00e4ltemittel?", answer: "Verdampft/verfl\u00fcssigt bei konstantem Druck auch bei konstanter Temperatur. Verh\u00e4lt sich wie ein einheitlicher Stoff (z. B. R-134a)." },
  { id: 163, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist ein K\u00e4ltemittelgemisch?", answer: "Mischung aus mehreren Reinstoffen. Zeotrop (400er, Temperaturgleit) oder azeotrop (500er, konstante Siedetemperatur)." },
  { id: 164, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist unter Temperaturgleit zu verstehen?", answer: "Temperatur\u00e4nderung w\u00e4hrend des Phasenwechsels bei konstantem Druck (Differenz zwischen Anfangs- und Endtemperatur)." },
  { id: 165, block: "Verfl\u00fcssiger & Verdampfer", question: "Nenne 2 K\u00e4ltemittel mit Temperaturgleit.", answer: "R-407C, R-407F, R-449A, R-448A" },
  { id: 166, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist ein \u201eBlend\u201c?", answer: "Ein K\u00e4ltemittelgemisch (Mischung mehrerer Reinstoffe). Unterscheidung in zeotrope und azeotrope Blends." },
  { id: 167, block: "Verfl\u00fcssiger & Verdampfer", question: "Unterschied zeotropes und azeotropes K\u00e4ltemittelgemisch?", answer: "Azeotrop: konstante Siedetemperatur, verh\u00e4lt sich wie Reinstoff. Zeotrop: gleitende Temperatur, Entmischungsgefahr." },
  { id: 168, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist beim Bef\u00fcllen mit zeotropen K\u00e4ltemitteln zu beachten?", answer: "Immer fl\u00fcssig f\u00fcllen! Sonst Entmischung \u2013 die leichter siedende Komponente verdampft zuerst aus der Flasche. Nachf\u00fcllen problematisch." },
  { id: 169, block: "Verfl\u00fcssiger & Verdampfer", question: "Darf bei einer Leckage zeotropes K\u00e4ltemittel nachgef\u00fcllt werden?", answer: "Nein! Erst Leck beheben, dann Anlage evakuieren und komplett neu bef\u00fcllen \u2013 das verbleibende K\u00e4ltemittel hat eine andere Zusammensetzung." },
  { id: 170, block: "Verfl\u00fcssiger & Verdampfer", question: "Warum R-32 statt R-410A in Klimaanlagen? Eigenschaften?", answer: "R-32 hat GWP 675 (< 750 Grenzwert ab 2025), R-410A hat 2088. \u00c4hnliche Thermodynamik, geringere F\u00fcllmenge." },
  { id: 173, block: "Verfl\u00fcssiger & Verdampfer", question: "Welches K\u00e4ltemittel wird in Split- und Multi-Split-Klimaanlagen eingesetzt?", answer: "R-32 (\u00e4ltere Anlagen: R-410A)." },
  { id: 174, block: "Verfl\u00fcssiger & Verdampfer", question: "Nenne 3 nat\u00fcrliche K\u00e4ltemittel und Besonderheiten.", answer: "K\u00e4ltemittel Nummer Besonderheit Propan R-290 Brennbar (A3) Isobutan R-600a Brennbar (A3) Ammoniak R-717 Giftig (B2L), greift Kupfer an CO\u2082 R-744 Hohe Drucklage, transkritisch" },
  { id: 175, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist unter KW, FCKW, H-FCKW, H-FKW und HFO zu verstehen?", answer: "KW: Kohlenwasserstoff (Propan). FCKW: vollhalogeniert, ODP (R-12). H-FCKW: teilhalogeniert, geringes ODP (R-22). H-FKW: teilfluoriert, kein ODP, GWP (R-449A). HFO: Hydrofluorolefine, niedriges GWP (R-1234yf)." },
  { id: 176, block: "Verfl\u00fcssiger & Verdampfer", question: "Normsiedetemperatur?", answer: "Verdampfungstemperatur bei 1 bar Absolutdruck." },
  { id: 177, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist der Treibhauseffekt?", answer: "Erw\u00e4rmung der Erdatmosph\u00e4re durch Treibhausgase (CO\u2082, HFKW) \u2013 Ursache der globalen Erw\u00e4rmung." },
  { id: 178, block: "Verfl\u00fcssiger & Verdampfer", question: "ODP-Wert? Referenz? Beispiele?", answer: "Ozone Depletion Potential \u2013 Ozonabbaupotential. Referenz: R-11 = 1. Stoffe mit ODP: R-12, R-22." },
  { id: 179, block: "Verfl\u00fcssiger & Verdampfer", question: "GWP-Wert? Referenz? Beispiele?", answer: "Global Warming Potential \u2013 Treibhauspotenzial. Referenz: CO\u2082 = 1 (\u00fcber 100 Jahre). Alle HFKW haben ein GWP." },
  { id: 180, block: "Verfl\u00fcssiger & Verdampfer", question: "Verordnungen zu K\u00e4ltemitteln?", answer: "F-Gase-Verordnung (Verbote, Phase-down, Dichtheitskontrollen) und Ozonschichtverordnung (ODP-Stoffe, Dichtheitskontrollen)." },
  { id: 181, block: "Verfl\u00fcssiger & Verdampfer", question: "Beispiele f\u00fcr brennbare K\u00e4ltemittel und Einsatz?", answer: "R-290 (Propan): W\u00e4rmepumpen, K\u00fchlm\u00f6bel. R-600a (Isobutan): Haushaltsk\u00fchlschr\u00e4nke." },
  { id: 182, block: "Verfl\u00fcssiger & Verdampfer", question: "CO\u2082 (R-744) \u2013 welche Gefahren trotz Ungiftigkeit?", answer: "Hohe Drucklage (>100 bar), Erstickungsgefahr bei hohen Konzentrationen (verdr\u00e4ngt Sauerstoff, ab 100.000 ppm Bewusstlosigkeit)." },
  { id: 183, block: "Verfl\u00fcssiger & Verdampfer", question: "Sicherheitsk\u00e4ltemittel \u2013 Gefahren bei gro\u00dfen Mengen?", answer: "Schwerer als Luft \u2192 luftverdr\u00e4ngend, erstickend; auch narkotische Wirkung." },
  { id: 184, block: "Verfl\u00fcssiger & Verdampfer", question: "Alternativen mit niedrigerem GWP f\u00fcr R-134a, R-404A, R-410A?", answer: "R-134a \u2192 R-513A, R-1234yf. R-404A \u2192 R-449A, R-448A. R-410A \u2192 R-32." },
  { id: 185, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist ein Drop-in-K\u00e4ltemittel? Beispiele?", answer: "Ersatzk\u00e4ltemittel ohne \u00d6l-/Komponentenwechsel (altes KM absaugen, neues einf\u00fcllen). F\u00fcr R-22: R-417A, R-422D. F\u00fcr R-12: R-437A." },
  { id: 186, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist \u201eRetrofit\u201c?", answer: "Umstellung einer bestehenden Anlage auf alternatives K\u00e4ltemittel, meist mit Komponententausch (Dichtungen, Filtertrockner, \u00d6l, Expansionsventil)." },
  { id: 187, block: "Verfl\u00fcssiger & Verdampfer", question: "Worauf ist bei einer K\u00e4ltemittelumstellung zu achten?", answer: "Komponentenfreigabe, K\u00e4lteleistung, Druckgastemperatur, \u00d6lwechsel n\u00f6tig? Verfl\u00fcssiger ausreichend? \u00dcberhitzung neu einstellen, Gasgeschwindigkeiten pr\u00fcfen, Regelger\u00e4te pr\u00fcfen." },
  { id: 188, block: "Verfl\u00fcssiger & Verdampfer", question: "\u00dcberdruck bei 59 \u00b0C f\u00fcr R-513A, R-134a, R-449A, R-404A, R-410A, R-32, R-744?", answer: "R-513A: 16 bar, R-134a: 15,3 bar, R-449A: 27,5 bar, R-404A: 27 bar, R-410A: 36,6 bar, R-32: 37,4 bar, R-744: 145,6 bar." },
  { id: 189, block: "Verfl\u00fcssiger & Verdampfer", question: "Was ist eine Mischungsl\u00fccke? Folgen?", answer: "Bereich, in dem \u00d6l und K\u00e4ltemittel nicht mischbar sind \u2192 \u00d6lr\u00fcckf\u00fchrung gest\u00f6rt." },
  { id: 190, block: "Verfl\u00fcssiger & Verdampfer", question: "Warum m\u00fcssen K\u00e4ltemaschinen\u00f6le gut mit dem K\u00e4ltemittel mischbar sein?", answer: "Damit das \u00d6l aus dem kalten Teil (Verdampfer) zur\u00fcck zum Verdichter transportiert wird." },
  { id: 191, block: "Verfl\u00fcssiger & Verdampfer", question: "Was bedeutet hygroskopisch? Praktische Auswirkung?", answer: "Wasseraufnahmef\u00e4higkeit \u2013 POE-\u00d6le stark hygroskopisch. Gebinde sofort verschlie\u00dfen, sonst Feuchtigkeit \u2192 S\u00e4ure, \u00d6lschlamm." },
  { id: 192, block: "Verfl\u00fcssiger & Verdampfer", question: "Wie ver\u00e4ndert sich die Viskosit\u00e4t mit steigender \u00d6ltemperatur?", answer: "Die Viskosit\u00e4t sinkt." },
  { id: 193, block: "Verfl\u00fcssiger & Verdampfer", question: "Woran ist \u00d6l zu erkennen, das ausgetauscht werden muss?", answer: "Dunkle Verf\u00e4rbung (Zersetzung), Kupferplattierung, nach Wicklungsbrand." },
  { id: 194, block: "Verfl\u00fcssiger & Verdampfer", question: "Welche Gr\u00fcnde gibt es f\u00fcr einen \u00d6lwechsel?", answer: "Alterung, S\u00e4ure im \u00d6l (S\u00e4uretester), nach Wicklungsbrand." },
  { id: 195, block: "Verfl\u00fcssiger & Verdampfer", question: "Welche Gr\u00fcnde f\u00fcr \u00d6lwechsel gibt es?", answer: "\u00b7 Alterung \u00b7 S\u00e4ure im \u00d6l (S\u00e4uretester) \u00b7 Verunreinigung durch Wicklungsbrand" },
  { id: 196, block: "Verfl\u00fcssiger & Verdampfer", question: "Wozu dient das log(p),h-Diagramm?", answer: "Grafische Darstellung des Kreisprozesses, Ermittlung von Enthalpiedifferenzen, Leistungen, Zustandsgr\u00f6\u00dfen." },
  { id: 197, block: "Verfl\u00fcssiger & Verdampfer", question: "Auf welcher Linie ist das KM fl\u00fcssig, wo gasf\u00f6rmig?", answer: "Siedelinie (links): ges\u00e4ttigte Fl\u00fcssigkeit (x=0). Taulinie (rechts): ges\u00e4ttigter Dampf (x=1)." },
  { id: 198, block: "Verfl\u00fcssiger & Verdampfer", question: "Bereich innerhalb der Glockenkurve?", answer: "Nassdampfbereich / Zweiphasengebiet." },
  { id: 199, block: "Verfl\u00fcssiger & Verdampfer", question: "Aggregatzustand im Nassdampfbereich?", answer: "Sowohl fl\u00fcssig als auch gasf\u00f6rmig \u2013 je n\u00e4her an der Siedelinie, desto mehr Fl\u00fcssigkeit." },
  { id: 200, block: "Verfl\u00fcssiger & Verdampfer", question: "Wie ver\u00e4ndert sich die Enthalpie bei Verdichten, Verfl\u00fcssigen, Drosseln, Verdampfen?", answer: "Verdichten: steigt. Verfl\u00fcssigen: sinkt. Drosseln: konstant. Verdampfen: steigt." },
  { id: 201, block: "Expansionsorgane & Regelung", question: "Wie ver\u00e4ndert sich der Druck bei Verdichten, Verfl\u00fcssigen, Drosseln, Verdampfen?", answer: "Verdichten: steigt. Verfl\u00fcssigen: konstant. Drosseln: sinkt. Verdampfen: konstant." },
  { id: 202, block: "Expansionsorgane & Regelung", question: "Was ist der kritische Punkt? Was passiert dar\u00fcber?", answer: "Zustand, bei dem Dampf und Fl\u00fcssigkeit nicht mehr unterscheidbar sind. Oberhalb der kritischen Temperatur ist keine Verfl\u00fcssigung durch W\u00e4rmeabgabe m\u00f6glich \u2192 Gask\u00fchler (transkritischer Betrieb, z. B. R-744)." },
  { id: 203, block: "Expansionsorgane & Regelung", question: "Wie zeichnet man ein log(p),h-Diagramm eines einstufigen Prozesses?", answer: "1. pC- und p\u2080-Linie zeichnen. 2. Punkt 1: p\u2080, \u00dcberhitzungstemperatur. 3. Punkt 2: pC, Isentrope durch Punkt 1. 4. Punkt 3: pC, Unterk\u00fchlungstemperatur. 5. Punkt 4: h\u2083 senkrecht auf p\u2080." },
  { id: 204, block: "Expansionsorgane & Regelung", question: "Wozu werden Filtertrockner verwendet?", answer: "Schmutz filtern, Feuchtigkeit absorbieren, S\u00e4uren binden." },
  { id: 205, block: "Expansionsorgane & Regelung", question: "Warum werden Filtertrockner in die Fl\u00fcssigkeitsleitung eingebaut?", answer: "Geringe Str\u00f6mungsgeschwindigkeit (0,5\u20130,7 m/s) \u2192 l\u00e4ngere Verweildauer, bessere Trocknung." },
  { id: 206, block: "Expansionsorgane & Regelung", question: "Wann muss ein Filtertrockner ausgewechselt werden?", answer: "Bei jedem Eingriff in den Kreislauf, bei S\u00e4ttigung (Feuchtigkeit/S\u00e4ure), bei \u0394T > 2 K \u00fcber den Trockner (verstopft), Dampfblasen im Schauglas." },
  { id: 207, block: "Expansionsorgane & Regelung", question: "Worauf ist beim Einbau und der Handhabung eines Filtertrockners zu achten?", answer: "Durchflussrichtung beachten (Pfeil), nicht lange der Luft aussetzen (Feuchtigkeitsaufnahme). L\u00f6ttrockner: ausschneiden, nicht ausl\u00f6ten!" },
  { id: 208, block: "Expansionsorgane & Regelung", question: "Was ist ein Burn-out-Filtertrockner?", answer: "Spezieller Reinigungstrockner nach Wicklungsbrand mit hohem S\u00e4urebindungsverm\u00f6gen. Einbau in die Saugleitung." },
  { id: 209, block: "Expansionsorgane & Regelung", question: "Warum muss der Wassergehalt in einer K\u00e4lteanlage m\u00f6glichst gering sein?", answer: "Sonst chemische Reaktionen mit \u00d6l \u2192 S\u00e4urebildung, \u00d6lschlamm, Korrosion, Eisblockade am Expansionsorgan." },
  { id: 210, block: "Expansionsorgane & Regelung", question: "Was sind Saugleitungsfilter? Wann kommen sie zum Einsatz?", answer: "Filtereins\u00e4tze vor dem Verdichter bei verzweigten Netzen, die Schmutz/Lotreste/Zunder filtern. Nach Einlaufphase werden sie entfernt, das Geh\u00e4use bleibt." },
  { id: 211, block: "Expansionsorgane & Regelung", question: "Wozu werden Schaugl\u00e4ser verwendet?", answer: "Kontrolle des Aggregatzustands in der Fl\u00fcssigkeitsleitung vor dem Expansionsventil \u2013 muss fl\u00fcssig und blasenfrei sein." },
  { id: 212, block: "Expansionsorgane & Regelung", question: "Wozu dient der Indikator im Schauglas?", answer: "Feuchtigkeitsindikator: Gr\u00fcn = trocken, Gelb = Feuchtigkeit." },
  { id: 213, block: "Expansionsorgane & Regelung", question: "Worauf ist beim L\u00f6ten von Schaugl\u00e4sern zu achten?", answer: "K\u00fchlen, sonst wird der Indikator zerst\u00f6rt." },
  { id: 214, block: "Expansionsorgane & Regelung", question: "Ursachen f\u00fcr Dampfblasen im Schauglas?", answer: "K\u00e4ltemittelmangel, Druckabfall in der Fl\u00fcssigkeitsleitung (verstopfter Filtertrockner, H\u00f6henunterschied, zu lange Leitung), W\u00e4rmeeintrag." },
  { id: 215, block: "Expansionsorgane & Regelung", question: "Feuchtigkeitsindikator verf\u00e4rbt \u2013 Ma\u00dfnahme?", answer: "Filtertrockner wechseln, Ursache f\u00fcr Feuchtigkeitseintrag suchen." },
  { id: 216, block: "Expansionsorgane & Regelung", question: "Wozu werden Absperrventile verwendet?", answer: "Anlagenteile f\u00fcr Reparaturen absperren (in Fl\u00fcssigkeits-, Saug-, Hei\u00dfgasleitung)." },
  { id: 217, block: "Expansionsorgane & Regelung", question: "Bei welchen Anlagen Absperrventile empfehlenswert?", answer: "Verzweigte Netze, Verbundk\u00e4lteanlagen \u2013 Reparatur ohne vollst\u00e4ndiges Absaugen." },
  { id: 218, block: "Expansionsorgane & Regelung", question: "Welche Aufgaben haben Magnetventile? Praxisbeispiele?", answer: "Automatisiertes Absperren von Rohrleitungen. Beispiele: K\u00fchlstellenregelung, Pump-Down, Abtaueinleitung." },
  { id: 219, block: "Expansionsorgane & Regelung", question: "Unterschied direktgesteuerte vs. servogesteuerte Magnetventile?", answer: "Direkt: Spule zieht Anker direkt, keine Druckdifferenz n\u00f6tig, nur kleine Leistungen. Servo: Pilotventil \u00f6ffnet, Hauptventil braucht Druckdifferenz." },
  { id: 220, block: "Expansionsorgane & Regelung", question: "Warum direkt gesteuerte Magnetventile nur bei kleinen K\u00e4lteleistungen?", answer: "Sonst m\u00fcsste die Magnetspule sehr gro\u00df und stark sein \u2192 starke Erw\u00e4rmung, unwirtschaftlich." },
  { id: 221, block: "Expansionsorgane & Regelung", question: "Servogesteuertes Magnetventil schaltet nicht \u2013 Ursachen?", answer: "Druckdifferenz zu gering, Verschmutzung (Ausgleichsbohrung verstopft), Druck nach Ventil h\u00f6her als Eintritt, Flattern durch Pulsation." },
  { id: 222, block: "Expansionsorgane & Regelung", question: "Was ist NO bzw. NC bei Magnetventilen? Anwendung?", answer: "NC (normally closed): spannungslos geschlossen \u2192 Pump-Down, Verbund. NO (normally open): spannungslos offen \u2192 Druckabbau bei Abschaltung." },
  { id: 223, block: "Expansionsorgane & Regelung", question: "Worauf ist beim Einbau von Magnetventilen zu achten?", answer: "Str\u00f6mungsrichtung (Pfeil), unmittelbar vor dem TEV, beim L\u00f6ten k\u00fchlen." },
  { id: 224, block: "Expansionsorgane & Regelung", question: "Was ist eine Pump-Down-Schaltung? Ablauf?", answer: "MV schlie\u00dft bei erreichter Temperatur \u2192 Verdichter saugt Verdampfer leer \u2192 ND-Pressostat schaltet ab \u2192 bei K\u00fchlbedarf \u00f6ffnet MV \u2192 Saugdruck steigt \u2192 Verdichter startet bei CUT IN." },
  { id: 225, block: "Expansionsorgane & Regelung", question: "Was ist eine Pump-Out-Schaltung? Unterschied?", answer: "Wie Pump-Down, aber Verdichter gegen Wiederanlauf gesperrt \u2013 startet erst wieder bei aktiver K\u00fchlanforderung. Verhindert Pendeln." },
  { id: 226, block: "Expansionsorgane & Regelung", question: "Warum werden Pump-Down und Pump-Out eingesetzt?", answer: "Schutz vor Fl\u00fcssigkeitsschl\u00e4gen beim Start, Vermeidung unzul\u00e4ssigen Druckanstiegs bei Abtauung." },
  { id: 227, block: "Expansionsorgane & Regelung", question: "Negative Auswirkung Pump-Down vs. Pump-Out?", answer: "Bei Pump-Down kann Druckanstieg im Verdampfer (Abtauung) zu kurzem Wiederanlauf f\u00fchren (Takten)." },
  { id: 228, block: "Expansionsorgane & Regelung", question: "Magnetventile in Verbundk\u00e4lteanlagen?", answer: "In der Fl\u00fcssigkeitsleitung vor jedem Verdampfer, gesteuert vom K\u00fchlstellenregler. Leitung MV\u2013Expansionsorgan m\u00f6glichst kurz." },
  { id: 229, block: "Expansionsorgane & Regelung", question: "Wann werden Service-Magnet-Spulen eingesetzt?", answer: "Zum manuellen \u00d6ffnen des Ventils ohne Bestromung (Inbetriebnahme, Evakuieren, Service)." },
  { id: 230, block: "Expansionsorgane & Regelung", question: "Gefahr beim Abziehen einer bestromten Magnetspule vom Anker?", answer: "Spule wird sehr hei\u00df, Kunststoff schmilzt, Spule wird zerst\u00f6rt." },
  { id: 231, block: "Expansionsorgane & Regelung", question: "Durch welche Komponente kann ein Magnetventil in Verbundanlagen entfallen?", answer: "EEV, die 100 % schlie\u00dfen k\u00f6nnen (Herstellerangaben beachten)." },
  { id: 232, block: "Expansionsorgane & Regelung", question: "Welche Aufgabe haben R\u00fcckschlagventile? Anwendungsbeispiele?", answer: "R\u00fcckkondensation in den Verdichter verhindern (Druckleitung), R\u00fcckstr\u00f6mung in den Verfl\u00fcssiger verhindern (Kondensatleitung), K\u00e4ltemittelstrom lenken (Hei\u00dfgasabtauung)." },
  { id: 233, block: "Expansionsorgane & Regelung", question: "Evakuieren von Anlagen mit R\u00fcckschlagventilen?", answer: "Immer beidseitig evakuieren! Sonst werden Teile der Anlage nicht evakuiert." },
  { id: 234, block: "Expansionsorgane & Regelung", question: "Zweck von R\u00fcckschlagventilen in der Druckleitung nach dem Verdichter?", answer: "Verhindern, dass bei kaltem Verdichter K\u00e4ltemittel aus dem Verfl\u00fcssiger zur\u00fcckkondensiert." },
  { id: 235, block: "Expansionsorgane & Regelung", question: "Alternative Ma\u00dfnahme zum R\u00fcckschlagventil?", answer: "Leistungsf\u00e4hige Kurbelwannenheizung, ordnungsgem\u00e4\u00dfe Druckleitungsverlegung." },
  { id: 236, block: "Expansionsorgane & Regelung", question: "R\u00fcckschlagventil macht schlagende Ger\u00e4usche \u2013 Ursache?", answer: "Ventil zu gro\u00df dimensioniert \u2192 Pulsationen \u2192 Sch\u00e4den, R\u00fcckkondensation, L\u00e4rm." },
  { id: 237, block: "Expansionsorgane & Regelung", question: "Aufgaben von K\u00e4ltemittelsammlern?", answer: "Vorratsbeh\u00e4lter f\u00fcr fl\u00fcssiges KM, Ausgleich bei variabler Verdampferleistung (mehrere K\u00fchlstellen)." },
  { id: 238, block: "Expansionsorgane & Regelung", question: "Messvorrichtung im Sammler als Leckageerkennung?", answer: "F\u00fcllstands\u00fcberwachung \u2013 warnt bei unzul\u00e4ssigem Abfall." },
  { id: 239, block: "Expansionsorgane & Regelung", question: "Warum Sammler nicht \u00fcber oder weit weg vom Verfl\u00fcssiger aufstellen?", answer: "Keine kontinuierliche Str\u00f6mung \u2192 periodische K\u00e4ltemittelstr\u00f6mung \u2192 Verfl\u00fcssigungsdruck steigt, Sch\u00e4den an der Kondensatleitung m\u00f6glich." },
  { id: 240, block: "Expansionsorgane & Regelung", question: "Kondensatleitung zwischen Verfl\u00fcssiger und Sammler ausf\u00fchren?", answer: "Kurz, Gef\u00e4lle zum Sammler, ausreichender Durchmesser f\u00fcr Druckausgleich, Sammlereintritt unter Verfl\u00fcssigeraustritt." },
  { id: 241, block: "Expansionsorgane & Regelung", question: "Was ist bei allseitig absperrbaren Sammlern aus Sicherheitsgr\u00fcnden einzubauen?", answer: "Eine Sicherheitseinrichtung (Sicherheitsventil) gegen unzul\u00e4ssige Drucksteigerung." },
  { id: 242, block: "Expansionsorgane & Regelung", question: "Aufgabe von Fl\u00fcssigkeitsabscheidern? Funktionsweise? Einbauort?", answer: "Schutz vor fl\u00fcssigem KM aus der Saugleitung. Einbau in Saugleitung vor Verdichter. Geschwindigkeitsreduzierung \u2192 Fl\u00fcssigkeit setzt sich ab, wird \u00fcber Schn\u00fcffelbohrung dosiert zur\u00fcckgef\u00fchrt." },
  { id: 243, block: "Expansionsorgane & Regelung", question: "Wann Fl\u00fcssigkeitsabscheider einbauen?", answer: "Wenn Gefahr von Fl\u00fcssigkeit in der Saugleitung besteht (Kreislaufumkehr, Hei\u00dfgasabtauung)." },
  { id: 244, block: "Expansionsorgane & Regelung", question: "Fl\u00fcssigkeitsabscheider mit internem W\u00e4rme\u00fcbertrager \u2013 Funktion?", answer: "Fl\u00fcssigkeitsleitung wird durch den Abscheider gef\u00fchrt \u2192 Unterk\u00fchlung der Fl\u00fcssigkeit, Erw\u00e4rmung und Verdampfung im Abscheider. Einsatz bei sehr tiefen t\u2080." },
  { id: 245, block: "Expansionsorgane & Regelung", question: "Kann der Fl\u00fcssigkeitsabscheider dauerhaft fl\u00fcssiges KM aufnehmen?", answer: "Nein, nur periodische Sch\u00fcbe." },
  { id: 246, block: "Expansionsorgane & Regelung", question: "\u00d6lr\u00fcckf\u00fchrung aus dem Fl\u00fcssigkeitsabscheider?", answer: "\u00dcber eine Schn\u00fcffelbohrung feindosiert in die Saugleitung." },
  { id: 247, block: "Expansionsorgane & Regelung", question: "Aufgabe von \u00d6labscheidern?", answer: "Ausgetragenes \u00d6l aus dem Druckgasstrom abscheiden und zum Verdichter zur\u00fcckf\u00fchren." },
  { id: 248, block: "Expansionsorgane & Regelung", question: "Wann Einbau eines \u00d6labscheiders empfehlenswert?", answer: "Verbundanlagen, niedrige t\u2080 mit Mischungsl\u00fccken, Teillastbetrieb." },
  { id: 249, block: "Expansionsorgane & Regelung", question: "Bei welcher Verdichterbauform ist ein \u00d6labscheider zwingend?", answer: "Schraubenverdichter (hohe \u00d6lwurfrate durch \u00d6leinspritzung)." },
  { id: 250, block: "Expansionsorgane & Regelung", question: "Warum \u00d6labscheider vor Inbetriebnahme vorf\u00fcllen?", answer: "Damit Schwimmer rechtzeitig \u00f6ffnet und \u00d6l zur\u00fcckflie\u00dft \u2013 sonst \u00d6lstandabfall im Verdichter, Hei\u00dfgas in Saugleitung m\u00f6glich." },
  { id: 251, block: "K\u00e4ltekreislauf & Diagramme", question: "Abscheidegrade von \u00d6labscheidern?", answer: "97\u201399 %." },
  { id: 252, block: "K\u00e4ltekreislauf & Diagramme", question: "Kann man mit \u00d6labscheider auf saubere Rohrleitungsf\u00fchrung verzichten?", answer: "Nein, da nicht 100 % Abscheidung \u2013 \u00d6lr\u00fcckf\u00fchrung aus dem Netz muss weiterhin gew\u00e4hrleistet sein." },
  { id: 253, block: "K\u00e4ltekreislauf & Diagramme", question: "Wann \u00d6labscheider isolieren/beheizen?", answer: "Bei niedrigen Umgebungstemperaturen \u2013 sonst Kondensation von KM im Stillstand." },
  { id: 254, block: "K\u00e4ltekreislauf & Diagramme", question: "\u00d6lr\u00fcckf\u00fchrung st\u00e4ndig hei\u00df \u2013 Ursache?", answer: "Hei\u00dfgas str\u00f6mt aus dem \u00d6labscheider in die R\u00fcckf\u00fchrleitung (h\u00e4ngender Schwimmer, Fremdk\u00f6rper)." },
  { id: 255, block: "K\u00e4ltekreislauf & Diagramme", question: "\u00d6l-/Fl\u00fcssigkeitsabscheider in kalter Umgebung \u2013 was beachten?", answer: "Heizung vorsehen, damit \u00d6l nicht zu dickfl\u00fcssig wird und KM nicht eindiffundiert." },
  { id: 256, block: "K\u00e4ltekreislauf & Diagramme", question: "Wozu dienen Schalld\u00e4mpfer (Muffler)? Wo eingebaut?", answer: "D\u00e4mpfung von Druckpulsationen (kein K\u00f6rperschall). Einbau in Druckleitung." },
  { id: 257, block: "K\u00e4ltekreislauf & Diagramme", question: "Worauf beim Einbau eines Mufflers achten?", answer: "Waagrecht oder senkrecht nach unten in Flussrichtung \u2013 sonst sammelt sich \u00d6l. Montagemarkierungen beachten." },
  { id: 258, block: "K\u00e4ltekreislauf & Diagramme", question: "Wozu dienen Schwingungsd\u00e4mpfer? Einbauort?", answer: "Reduzierung von Verdichtervibrationen. In Druckleitung zwischen Verdichter und Verfl\u00fcssiger." },
  { id: 259, block: "K\u00e4ltekreislauf & Diagramme", question: "Worauf beim Einbau eines Schwingungsd\u00e4mpfers achten?", answer: "Quer zur Schwingungsrichtung einbauen, nahe am Flansch f\u00fcr optimale D\u00e4mpfung." },
  { id: 260, block: "K\u00e4ltekreislauf & Diagramme", question: "Wozu dienen Thermostate?", answer: "Temperatur messen und elektrische Komponenten schalten (z. B. K\u00fchlstellenregelung)." },
  { id: 261, block: "K\u00e4ltekreislauf & Diagramme", question: "Welche \u201eThermostate\u201c werden heute haupts\u00e4chlich eingesetzt?", answer: "Elektronische K\u00fchlstellenregler." },
  { id: 262, block: "K\u00e4ltekreislauf & Diagramme", question: "Funktionen eines elektronischen K\u00fchlstellenreglers?", answer: "Verdichtersteuerung, L\u00fcfternachlauf, Abtaueinleitung/-ende, Alarmausg\u00e4nge, T\u00fcrkontakt, Temperaturanzeige, MSR-Einbindung." },
  { id: 263, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe von Verdampfungsdruckreglern? Einbauort?", answer: "Verhindern Unterschreiten des Verdampfungsdrucks (Schutz vor Bereifung, Einfrieren). Einbau: Saugleitung nach Verdampfer vor Verdichter." },
  { id: 264, block: "K\u00e4ltekreislauf & Diagramme", question: "Funktionsweise und Einstellung Verdampfungsdruckregler?", answer: "\u00d6ffnet bei steigendem Eingangsdruck. Einstellung: rechts = h\u00f6herer \u00d6ffnungsdruck (gesteigerte t\u2080)." },
  { id: 265, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe von Verfl\u00fcssigungsdruckreglern? Einbauort?", answer: "Verhindern zu tiefes Absinken des Verfl\u00fcssigungsdrucks (Winter). Einbau: Kondensatleitung. Alternative: L\u00fcfter-Drehzahlregelung." },
  { id: 266, block: "K\u00e4ltekreislauf & Diagramme", question: "Funktionsweise und Einstellung Verfl\u00fcssigungsdruckregler?", answer: "Bei sinkendem Druck schlie\u00dft das Ventil, staut KM an \u2192 wirksame Verfl\u00fcssigerfl\u00e4che sinkt \u2192 Druck steigt. Nur vom Eintrittsdruck abh\u00e4ngig." },
  { id: 267, block: "K\u00e4ltekreislauf & Diagramme", question: "Welches weitere Bauteil mit Verfl\u00fcssigungsdruckregler kombiniert?", answer: "Sammlerdruckregler oder Differenzdruckventil (NRD), um den Sammlerdruck aufrechtzuerhalten." },
  { id: 268, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe des Differenzdruckventils? Funktionsweise?", answer: "H\u00e4lt konstanten, ausreichenden Sammlerdruck in Anlagen mit luftgek\u00fchltem Verfl\u00fcssiger. Teil des Regelsystems KVR + NRD." },
  { id: 269, block: "K\u00e4ltekreislauf & Diagramme", question: "Wo wird das Differenzdruckventil NRD eingebaut? Einstellbar?", answer: "Zwischen Druckleitung und Sammlereintritt. Fixer Wert: 1,4 bar, nicht einstellbar." },
  { id: 270, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe von Startreglern?", answer: "Begrenzung des max. Saugdrucks bei Tiefk\u00fchlung nach Abtauung/Stillstand \u2013 entlastet den Verdichter, Motor kann kleiner ausfallen." },
  { id: 271, block: "K\u00e4ltekreislauf & Diagramme", question: "Wie werden Startregler eingestellt?", answer: "Werkseinstellung 2 bar. Rechts = h\u00f6herer \u00d6ffnungsdruck, links = niedriger. Einstellung auf max. zul\u00e4ssigen Saugdruck des Verdichters." },
  { id: 272, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe von Sammlerdruckreglern?", answer: "Verhindern Abfallen des Sammlerdrucks bei niedrigen Au\u00dfentemperaturen. Einbau: Druckleitung zwischen Verdichter und Sammler." },
  { id: 273, block: "K\u00e4ltekreislauf & Diagramme", question: "Einstellung Sammlerdruckregler?", answer: "Zuerst Verfl\u00fcssigungsdruckregler einstellen, w\u00e4hrend Sammlerdruckregler geschlossen ist. Dann \u00d6ffnungsdruck am Sammlerdruckregler ca. 1 bar niedriger als Verfl\u00fcssigungsdruck einstellen." },
  { id: 274, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe mechanischer Leistungsregler?", answer: "Saugdruck nach unten begrenzen, unzul\u00e4ssiges Druckverh\u00e4ltnis verhindern. K\u00e4ltemitteldampf wird vom Verdichteraustritt in die Saugleitung geleitet." },
  { id: 275, block: "K\u00e4ltekreislauf & Diagramme", question: "Funktionsweise mechanischer Leistungsregler?", answer: "\u00d6ffnet bei sinkendem Austrittsdruck (Verdampferdruck unterschreitet Einstellwert)." },
  { id: 276, block: "K\u00e4ltekreislauf & Diagramme", question: "Energieeffizienz mechanischer Leistungsregler?", answer: "Ung\u00fcnstig \u2013 ein Teil der Verdichterleistung geht als Hei\u00dfgas-Bypass verloren. In Neuanlagen kaum noch verwendet." },
  { id: 277, block: "K\u00e4ltekreislauf & Diagramme", question: "Was sind thermostatische Leistungsregler?", answer: "Hei\u00dfgas-Bypass-Regler wie Expansionsorgane aufgebaut, mit Anlegef\u00fchler an der Einspritzleitung (misst t\u2080)." },
  { id: 278, block: "K\u00e4ltekreislauf & Diagramme", question: "Worauf bei Montage/Einbau von Druckreglern achten?", answer: "Durchfluss in Pfeilrichtung, ordnungsgem\u00e4\u00df befestigen gegen Vibrationen, beliebige Einbaulage m\u00f6glich." },
  { id: 279, block: "K\u00e4ltekreislauf & Diagramme", question: "Worauf bei L\u00f6tarbeiten an Druckreglern achten?", answer: "Eins\u00e4tze in Manometeranschl\u00fcssen entfernen, Ventil mit feuchtem Tuch k\u00fchlen, Flamme vom Ventil weghalten, kein Lot ins Ventil gelangen lassen." },
  { id: 280, block: "K\u00e4ltekreislauf & Diagramme", question: "Druckprobe bei Anlagen mit Druckreglern?", answer: "Pr\u00fcfdruck darf den max. zul\u00e4ssigen Pr\u00fcf\u00fcberdruck der Ventile nicht \u00fcberschreiten." },
  { id: 281, block: "K\u00e4ltekreislauf & Diagramme", question: "Evakuieren bei Anlagen mit Druckreglern?", answer: "Alle Ventile \u00f6ffnen, beidseitig (Hoch-/Niederdruck) evakuieren \u2013 nicht \u00fcber die kleinen Manometerstutzen." },
  { id: 282, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe druckgesteuerter Luftmengenregler?", answer: "Verhindern Abfall des Verfl\u00fcssigungsdrucks durch Anpassung der Ventilatordrehzahl bei niedrigen Umgebungstemperaturen." },
  { id: 283, block: "K\u00e4ltekreislauf & Diagramme", question: "Vorteile einer stetigen Drehzahlregelung des Verfl\u00fcssigerl\u00fcfters?", answer: "Konstanter Verfl\u00fcssigungsdruck, weniger Takten, bessere TEV-Funktion, kein unn\u00f6tig hoher Druck = Energieeinsparung." },
  { id: 284, block: "K\u00e4ltekreislauf & Diagramme", question: "Auswirkung der Druckregelung durch Ein-/Ausschalten des L\u00fcfters (Pressostat)?", answer: "Druckschwankungen (Takten) \u2192 TEV arbeitet nicht ordnungsgem\u00e4\u00df." },
  { id: 285, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe druckgesteuerter Wassermengenregler?", answer: "Konstanthalten des Verfl\u00fcssigungsdrucks bei wassergek\u00fchlten Verfl\u00fcssigern \u2013 regeln Wassermenge druckabh\u00e4ngig." },
  { id: 286, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufbau und Funktion des Wassermengenreglers?", answer: "Federkraft \u00f6ffnet Ventil bei steigendem Druck. Linksdrehen der Spindel = h\u00f6here Vorspannung = \u00f6ffnet erst bei h\u00f6herem Druck." },
  { id: 287, block: "K\u00e4ltekreislauf & Diagramme", question: "Was ist ein Pressostat? Duo-Pressostat?", answer: "Druckschalter als Sicherheitseinrichtung (Hoch-/Niederdruck). Duo-Pressostat: Kombi aus HD und ND." },
  { id: 288, block: "K\u00e4ltekreislauf & Diagramme", question: "Auf welchen Wert ND-Pressostat einstellen?", answer: "\u00dcber 0 bar (Praxis: 0,2 bar), damit bei Leckage keine Luft gesaugt wird." },
  { id: 289, block: "K\u00e4ltekreislauf & Diagramme", question: "ND-Schalter einstellen \u2013 was ist CUT IN und DIFF?", answer: "CUT IN = Wiedereinschaltdruck, DIFF = Differenz. Ausschaltdruck = CUT IN \u2013 DIFF. Einstellreihenfolge: erst CUT IN, dann DIFF." },
  { id: 290, block: "K\u00e4ltekreislauf & Diagramme", question: "HD-Schalter einstellen \u2013 was ist DIFF?", answer: "CUT OUT = Abschaltdruck, DIFF = Differenz. Einschaltdruck = CUT OUT \u2013 DIFF. Einstellreihenfolge: erst CUT OUT, dann DIFF." },
  { id: 291, block: "K\u00e4ltekreislauf & Diagramme", question: "ND: CUT IN 2 bar, Ausschaltdruck 0,5 bar \u2192 DIFF?", answer: "1,5 bar." },
  { id: 292, block: "K\u00e4ltekreislauf & Diagramme", question: "HD: CUT OUT 16 bar, DIFF 2 bar \u2192 Wiedereinschaltdruck? 14 bar.", answer: "293. 3 Gruppen von Druckschaltern? Druckw\u00e4chter (selbstr\u00fcckstellend, PSH/PSL), baumustergepr\u00fcfte Druckbegrenzer (Handr\u00fcckstellung ohne Werkzeug), Sicherheitsdruckbegrenzer (Werkzeug n\u00f6tig)." },
  { id: 293, block: "K\u00e4ltekreislauf & Diagramme", question: "Beschreibe die Funktion des \u00d6ldifferenzdruckschalters.", answer: "\u00b7 Zwei getrennte Kreise: Sicherheitskreis und Differenzkreis \u00b7 Bei zu niedrigem Differenzdruck wird das Zeitrelais aktiviert \u00b7 Nach Ablauf der Ausl\u00f6sezeit schaltet der Sicherheitskreis den Verdichter ab \u00b7 Handr\u00fcckstellung erforderlich (Ursachenforschung!)" },
  { id: 294, block: "K\u00e4ltekreislauf & Diagramme", question: "Einstellung ND bei Freiluftplatzierung im Winter?", answer: "CUT IN niedriger als der niedrigste Druck im Winter (Sammlerdruck nach Stillstand), sonst startet Verdichter nicht." },
  { id: 295, block: "K\u00e4ltekreislauf & Diagramme", question: "Bestimmung des maximal zul\u00e4ssigen Drucks (PS)? HD-SchalterEinstellung?", answer: "PS = Mindestwert nach EN 378-2, basierend auf Sattdampfdruck-Tabelle. HDSchalter: CUT OUT \u2264 0,9 \u00d7 PS." },
  { id: 296, block: "K\u00e4ltekreislauf & Diagramme", question: "Wie Hochdruckschalter auf Funktion pr\u00fcfen?", answer: "Verfl\u00fcssigerl\u00fcfter abschalten/Oberfl\u00e4che bedecken \u2192 Druck steigt \u2192 Abschaltdruck pr\u00fcfen. NOT-AUS bereithalten!" },
  { id: 297, block: "K\u00e4ltekreislauf & Diagramme", question: "Aufgabe \u00d6ldifferenzdruckschalter?", answer: "Schutz vor zu niedrigem Schmier\u00f6ldruck (Differenz Pumpendruck \u2013 Kurbelgeh\u00e4usedruck). Zeitverz\u00f6gert, Handr\u00fcckstellung." },
  { id: 298, block: "K\u00e4ltekreislauf & Diagramme", question: "K\u00e4ltetechnischer Anschluss \u00d6ldifferenzdruckschalter?", answer: "Anschluss an Kurbelgeh\u00e4use (Saugdruck) und an \u00d6lpumpe (\u00d6ldruck)." },
  { id: 299, block: "K\u00e4ltekreislauf & Diagramme", question: "Funktion \u00d6ldifferenzdruckschalter?", answer: "Zwei Kreise: Differenzkreis und Sicherheitskreis. Zeitrelais startet, wenn Differenzdruck < Sollwert. Nach Ablauf der Zeit schaltet Sicherheitskreis ab." },
  { id: 300, block: "K\u00e4ltekreislauf & Diagramme", question: "Zeitverz\u00f6gerung beim \u00d6ldifferenzdruckschalter \u2013 wozu?", answer: "Verhindert Abschaltung bei kurzen Druckschwankungen und w\u00e4hrend der Anlaufphase (Druckaufbau dauert)." },
  { id: 301, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum nur Handr\u00fcckstellung?", answer: "Abschaltung weist auf ernstes Schmierproblem hin \u2013 Ursache muss fachkundig ermittelt werden vor Wiederanlauf." },
  { id: 302, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Ansprechen des \u00d6ldifferenzdruckschalters bei defekter \u00d6lheizung?", answer: "KM im \u00d6l \u2192 beim Start sch\u00e4umt \u00d6l \u2192 keine \u00d6ldruck \u2192 Abschaltung." },
  { id: 303, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Worauf ist bei der Inbetriebnahme von \u00d6lsammlern zu achten?", answer: "Bis zum oberen/mittleren Schauglas bef\u00fcllen. \u00d6l nur nachf\u00fcllen, wenn Stand unter das untere Schauglas sinkt." },
  { id: 304, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was sind \u00d6lspiegelregulatoren? Wann verbaut?", answer: "Regeln \u00d6lniveau am Verdichter im Verbundbetrieb. \u00d6lzufuhr aus \u00d6lsammler. Mechanisch oder elektronisch." },
  { id: 305, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was sind \u00d6lfilter? Wann verbaut?", answer: "Filtern Schmutz aus dem \u00d6l, in \u00d6lleitungen vor den \u00d6lspiegelregulatoren." },
  { id: 306, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Differenzdruckventile im \u00d6lreguliersystem?", answer: "Bauen Druck aus dem \u00d6labscheider in die Saugleitung ab, halten aber eine bestimmte Druckdifferenz aufrecht (0,1\u20132,5 bar)." },
  { id: 307, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was sind \u00d6lsammler?", answer: "Entgasen, k\u00fchlen, bevorraten das \u00d6l vom Abscheider. Mit Schauglas, Heizelement." },
  { id: 308, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Montage von \u00d6lsammlern \u2013 worauf achten?", answer: "Gleiche H\u00f6he oder h\u00f6her als \u00d6lspiegelregulatoren, Heizelement einbauen (gegen KM-Verlagerung)." },
  { id: 309, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Inbetriebnahme \u00d6lsammler?", answer: "Bis oberes/mittleres Schauglas f\u00fcllen, nur nachf\u00fcllen bei Unterschreiten des unteren Schauglases." },
  { id: 310, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was sind \u00d6labscheider-Sammler?", answer: "Kombination aus \u00d6labscheider und Sammler, ohne Schwimmerventil. F\u00fcr Hochdruck-\u00d6lreguliersysteme." },
  { id: 311, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was ist ein innerer W\u00e4rme\u00fcbertrager? Wo eingebaut?", answer: "R\u00f6hrenw\u00e4rme\u00fcbertrager zwischen Fl\u00fcssigkeitsleitung und Saugleitung zur Vergr\u00f6\u00dferung der Unterk\u00fchlung und Erh\u00f6hung der Sauggas\u00fcberhitzung." },
  { id: 312, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was sind 4-Wege-Ventile? Wo eingesetzt?", answer: "Kreislaufumkehrventil \u2013 Verdampfer wird Verfl\u00fcssiger und umgekehrt. Einsatz: Abtauung, Klimager\u00e4te mit Heizen/K\u00fchlen." },
  { id: 313, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wie wird Wasser beim Evakuieren entfernt?", answer: "Der Druck wird unter den Verdampfungsdruck von Wasser bei Umgebungstemperatur abgesenkt (ca. 23 mbar bei 20 \u00b0C). Wasser beginnt zu verdampfen und wird abgesaugt." },
  { id: 314, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Welche Pr\u00fcfungen sind vor Inbetriebnahme erforderlich?", answer: "Unterlagen der Druckger\u00e4te, Sicherheitseinrichtungen, Schwei\u00dfn\u00e4hte (ausgew\u00e4hlt), Sichtpr\u00fcfung, Kennzeichnung, Dichtheitspr\u00fcfbericht, Anpassung Antriebe/Verdichter." },
  { id: 315, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Vor Inbetriebnahme einzustellende Komponenten?", answer: "Pressostate (HD/ND), \u00d6ldifferenzdruckschalter, Thermostate, Motorschutz, Drehrichtungspr\u00fcfung, \u00d6l-/Abtauheizungen." },
  { id: 316, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum Druckprobe zuerst mit 3 bar, dann mit vollem Druck?", answer: "Grobe Lecks (offene Verbindungen) fr\u00fch erkennen, N\u2082 sparen." },
  { id: 317, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was ist Evakuieren?", answer: "Entfernen von Fremdgasen und Feuchtigkeit aus dem K\u00e4ltekreislauf mittels Vakuumpumpe." },
  { id: 318, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum muss vor dem Bef\u00fcllen evakuiert werden?", answer: "Fremdgase und Feuchtigkeit entfernen \u2013 sonst erh\u00f6hter Betriebsdruck, Effizienzverlust, S\u00e4urebildung, Eisblockade." },
  { id: 319, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Folgen nicht ordnungsgem\u00e4\u00dfer Evakuierung?", answer: "Betriebsdruck steigt (Partialdruck Fremdgas), Leistungsaufnahme steigt, COP sinkt, \u00dcberdruckst\u00f6rungen, Feuchtigkeit \u2192 S\u00e4ure, \u00d6lschlamm." },
  { id: 320, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wie wird Wasser beim Evakuieren entfernt?", answer: "Druck unter Verdampfungsdruck des Wassers bei Umgebungstemperatur absenken (ca. 23 mbar bei 20 \u00b0C) \u2192 Wasser verdampft und wird abgesaugt." },
  { id: 321, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was ist \u201eVakuum brechen\u201c? Mit welchem Stoff?", answer: "Bef\u00fcllen der evakuierten Anlage mit Stickstoff, um Restfeuchtigkeit zu binden und auszutragen." },
  { id: 322, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum kein Relativdruckmanometer beim Evakuieren?", answer: "Kann Vakuumwerte nicht anzeigen \u2013 Feinvakuum (1\u20133 mbar) nur mit Vakuummeter/Torrmeter messbar." },
  { id: 323, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Grundregeln beim Evakuieren?", answer: "Beidseitig evakuieren, kurze dicke Schl\u00e4uche, nicht \u00fcber Schraderventile, Vakuummeter fern der Pumpe platzieren, Vakuummeter verwenden." },
  { id: 324, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wozu Gasballastventil bei Vakuumpumpen?", answer: "Verhindert Kondensation von Wasserdampf im Pumpengeh\u00e4use \u2192 sch\u00fctzt vor \u00d6lverschlechterung und Korrosion." },
  { id: 325, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Schutzgasf\u00fcllung im Verdichter \u2013 wann ablassen?", answer: "Erst kurz vor dem Evakuieren \u2013 sonst zieht der Verdichter Luft und Feuchtigkeit." },
  { id: 326, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Evakuierung dauert sehr lange \u2013 Ursachen?", answer: "Anlage undicht, zu viel Feuchtigkeit, KM im \u00d6l gebunden, Vakuumpumpe defekt oder zu klein." },
  { id: 327, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Anlage wurde nicht ausreichend evakuiert \u2013 Auswirkungen?", answer: "Verfl\u00fcssigungsdruck steigt (Partialdruck Fremdgas), Leistungsaufnahme \u2191, COP \u2193, Verdichtungsendtemperatur steigt." },
  { id: 328, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wie pr\u00fcft man \u00fcberschl\u00e4gig auf Fremdgase?", answer: "Verfl\u00fcssigungsdruck und Lufteintrittstemperatur (luftgek\u00fchlt) bzw. Wasseraustrittstemperatur messen und mit Auslegungs-\u0394T vergleichen (10\u201315 K)." },
  { id: 329, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wo sammeln sich Fremdgase in der Anlage?", answer: "Im Sammler und Verfl\u00fcssiger \u2013 weil nur Fl\u00fcssigkeit weitergeleitet wird." },
  { id: 330, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was kann passieren, wenn Vakuum mit fl\u00fcssigem KM gebrochen wird?", answer: "Extrem tiefe Temperaturen durch Entspannung (1 mbar \u2192 Siedetemperatur) \u2192 Materialrisse m\u00f6glich." },
  { id: 331, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Bef\u00fcllen mit zeotropem KM \u2013 was beachten?", answer: "Immer fl\u00fcssig f\u00fcllen! Sonst Entmischung. Bei Saugseiten-F\u00fcllung extreme Vorsicht, kein Fl\u00fcssigkeitsschlag im Verdichter." },
  { id: 332, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wie werden Kapillarrohranlagen gef\u00fcllt?", answer: "F\u00fcllkriterium: \u00dcberhitzung bei Teillast. Am Verdampferaustritt muss angemessene \u00dcberhitzung vorhanden sein; sonst F\u00fcllmenge erh\u00f6hen." },
  { id: 333, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Auswirkung einer \u00dcberf\u00fcllung?", answer: "Fl\u00fcssiges KM staut sich im Verfl\u00fcssiger \u2192 wirksame Fl\u00e4che sinkt \u2192 Verfl\u00fcssigungsdruck steigt \u2192 Effizienz \u2193, HD-Abschaltung m\u00f6glich." },
  { id: 334, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wo ist die Inbetriebnahme, Druckprobe etc. zu dokumentieren?", answer: "Im Pr\u00fcf- und Anlagenbuch." },
  { id: 335, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Kennzeichnung nach F-Gase-Verordnung?", answer: "\u201eEnth\u00e4lt fluorierte Treibhausgase\u201c, Industrie-/chemische Bezeichnung, F\u00fcllmenge (kg), CO\u2082-\u00c4quivalent, GWP. Hermetisch geschlossene Systeme extra kennzeichnen." },
  { id: 336, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Welche Angaben muss ein Typenschild nach KAV enthalten?", answer: "Errichter (Name/Anschrift), Baujahr, Art des KM, F\u00fcllgewicht (kg), K\u00e4lteleistung (kW), festgelegter h\u00f6chster Betriebsdruck jeder Druckstufe (bar)." },
  { id: 337, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Inhalte des Pr\u00fcfbuchs nach KAV?", answer: "Typenschild-Angaben, Bescheinigungen \u00fcber Druckproben, Probe vor Inbetriebnahme, Vermerke \u00fcber gr\u00f6\u00dfere Instandsetzungen/\u00c4nderungen." },
  { id: 338, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum m\u00fcssen Dichtheitspr\u00fcfungen durchgef\u00fchrt werden?", answer: "\u00d6kologisch (Treibhauseffekt, Ozonschicht), rechtlich (F-Gase-VO, KAV, Ozonschicht-VO), wirtschaftlich (Warensch\u00e4den bei Ausfall)." },
  { id: 339, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Rechtliche Grundlagen f\u00fcr Dichtheitspr\u00fcfung?", answer: "F-Gase-Verordnung, Ozonschichtverordnung, K\u00e4lteanlagenverordnung." },
  { id: 340, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wie oft sind Dichtheitspr\u00fcfungen durchzuf\u00fchren? Wovon abh\u00e4ngig?", answer: "Intervall abh\u00e4ngig vom verwendeten KM und der anwendbaren Verordnung. Grunds\u00e4tzlich vor Inbetriebnahme immer. Wiederkehrend: siehe F-Gase-/Ozonschichtverordnung." },
  { id: 341, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Welche Verfahren der Dichtheitspr\u00fcfung gibt es?", answer: "Druckabfallpr\u00fcfung (Druckstandsprobe) mit Stickstoff, Lecksuche mit elektronischen Lecksuchger\u00e4ten, schaumbildenden Mitteln. Druckabfallpr\u00fcfung: Temperaturstabilisierung abwarten!" },
  { id: 342, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Anzeichen f\u00fcr eine Leckage?", answer: "Leckageerkennungssystem schl\u00e4gt an, ungew\u00f6hnliche Ger\u00e4usche/Schwingungen, Eisbildung, unzureichende Leistung, \u00d6laustritt, Korrosion, F\u00fcllstandsabfall, Abweichungen der Betriebsparameter." },
  { id: 343, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Wo treten die meisten Undichtheiten auf?", answer: "Laut \u00d6GKT-Umfrage: 1. B\u00f6rdelverbindungen, 2. Verdampfer, 3. Stopfbuchsen, 4. Schraderventile, 5. Verfl\u00fcssiger." },
  { id: 344, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Unterschied direkter und indirekter K\u00e4ltemittelmangel?", answer: "Direkt: zu wenig KM-Masse in der Anlage. Indirekt: genug KM vorhanden, aber durch Expansionsorgane nicht ausreichend dem Verdampfer zugef\u00fchrt." },
  { id: 345, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Direkte vs. indirekte Messmethode bei Lecksuche?", answer: "Direkt: KM-Austritt direkt messbar (Schaumbildner, elektronisches Lecksuchger\u00e4t). Indirekt: Analyse der Anlagenparameter (Druck/Temperatur). Direkte Methode ist zu bevorzugen." },
  { id: 346, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Welche Methode bei vermutetem Leck anwenden?", answer: "Wenn indirekt ein Leck vermutet wird, muss eine direkte Methode zur genauen Ortung folgen." },
  { id: 347, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Bei einer Dichtheitspr\u00fcfung wird eine Leckage festgestellt \u2013 was tun?", answer: "So schnell wie m\u00f6glich beheben." },
  { id: 348, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was muss nach der Behebung einer Leckage erfolgen?", answer: "Innerhalb eines Monats Nachpr\u00fcfung auf Dichtheit, Eintrag ins Pr\u00fcfbuch." },
  { id: 349, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Welche Messger\u00e4te sollten bei jeder Fehlersuche vorhanden sein?", answer: "Manometer, Thermometer, Hygrometer, Lecksuchger\u00e4t, Multimeter." },
  { id: 350, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum m\u00fcssen Filter von Klima-/L\u00fcftungsanlagen regelm\u00e4\u00dfig gewechselt werden?", answer: "Hygiene (Verkeimung), energetisch (Druckverlust \u2191 \u2192 mehr Ventilatorleistung), k\u00e4ltetechnisch (Vereisung bei zu wenig Luft)." },
  { id: 351, block: "Elektrotechnik & Steuerung", question: "Was passiert bei Betrieb einer undichten Anlage im Vakuum auf der Saugseite?", answer: "Luft und Feuchtigkeit werden ins System gesaugt \u2192 Betriebsdruck \u2191, Effizienz \u2193, S\u00e4urebildung, Eisblockade." },
  { id: 352, block: "Elektrotechnik & Steuerung", question: "Druckrohrtemperatur zu hoch \u2013 Ursachen?", answer: "Verdampfungsdruck zu niedrig, Verfl\u00fcssigungsdruck zu hoch, \u00dcberhitzung am Verdichtereintritt zu hoch." },
  { id: 353, block: "Elektrotechnik & Steuerung", question: "Druckrohrtemperatur zu niedrig \u2013 Ursachen?", answer: "Verdichter bekommt Fl\u00fcssigkeitsanteile (Nassfahren), Verfl\u00fcssigungsdruck zu gering." },
  { id: 354, block: "Elektrotechnik & Steuerung", question: "Verfl\u00fcssigungsdruck bei Inbetriebnahme zu hoch \u2013 Ursachen?", answer: "Drehzahlregler falsch, KVR falsch eingestellt, Umgebung sehr hei\u00df, Luftzirkulation eingeschr\u00e4nkt, \u00fcberf\u00fcllt, Fremdgase, Verfl\u00fcssiger unterdimensioniert." },
  { id: 355, block: "Elektrotechnik & Steuerung", question: "Bestandsanlage schaltet \u00fcber HD ab \u2013 Ursachen?", answer: "Verfl\u00fcssiger verschmutzt, Lamellen verbogen, L\u00fcftermotor defekt, Umgebung sehr hei\u00df, Luftzirkulation eingeschr\u00e4nkt." },
  { id: 356, block: "Elektrotechnik & Steuerung", question: "Filtertrockner f\u00fchlbar k\u00e4lter als Fl\u00fcssigkeitsleitung \u2013 Ma\u00dfnahme?", answer: "Vorverdampfung durch Druckabfall \u2192 verstopft \u2192 Filtertrockner wechseln (\u0394T > 2 K)." },
  { id: 357, block: "Elektrotechnik & Steuerung", question: "Verdampfer nur im ersten Viertel stark bereift \u2013 Bedeutung?", answer: "Mangelhafte Einspritzung (KM-Mangel, TEV unterdimensioniert, D\u00fcse zu klein/verstopft, \u00dcberhitzung zu hoch). Erst F\u00fcllmenge pr\u00fcfen!" },
  { id: 358, block: "Elektrotechnik & Steuerung", question: "Ma\u00dfnahmen nach Wicklungsbrand bei sauggasgek\u00fchlten Verdichtern?", answer: "\u00d6l wechseln, Burnout-Filtertrockner einbauen, S\u00e4uretest, ggf. erneuter \u00d6lwechsel." },
  { id: 359, block: "Elektrotechnik & Steuerung", question: "Kurzbezeichnungen: t0, tC, p0, pC, t2n, tDn, tE1U, \u0394t2n, \u0394tE1U?", answer: "t\u2080 = Verdampfungstemperatur, tC = Verfl\u00fcssigungstemperatur, p\u2080 = Verdampfungsdruck, pC = Verfl\u00fcssigungsdruck, t\u2082\u2095 = Temperatur Verdampferaustritt, tDn = Temperatur Verdichteraustritt, tE1U = Temperatur Expansionsorgan-Eintritt (unterk\u00fchlt), \u0394t\u2082\u2095 = \u00dcberhitzung Verdampferaustritt, \u0394tE1U = Unterk\u00fchlung Expansionsorgan-Eintritt." },
  { id: 360, block: "Elektrotechnik & Steuerung", question: "Verdichter kann durch ND-Schalter nicht stoppen \u2013 Ursache?", answer: "DIFF zu gro\u00df eingestellt \u2192 Ausschaltdruck liegt unter 0 bar oder Saugdruck erreicht den Ausschaltdruck nicht." },
  { id: 361, block: "Elektrotechnik & Steuerung", question: "Verdichter l\u00e4uft im Winter kurz an und geht auf ND-St\u00f6rung \u2013 Ursache und Abhilfe?", answer: "Au\u00dfentemperatur tief \u2192 KM verlagert sich in Verfl\u00fcssiger \u2192 Verfl\u00fcssigungsdruck sinkt \u2192 Druckdifferenz am TEV zu gering \u2192 Verdampfer unterversorgt \u2192 Saugdruck sinkt unter Abschaltpunkt. Abhilfe: Winterdruckregelung (Drehzahlregler, KVR) einbauen." },
  { id: 362, block: "Elektrotechnik & Steuerung", question: "Verfl\u00fcssigungsdruck zu niedrig \u2013 Ursachen und Abhilfe?", answer: "Verfl\u00fcssigeroberfl\u00e4che zu gro\u00df \u2192 KVR einbauen / Verfl\u00fcssiger tauschen; KVR falsch eingestellt \u2192 richtig einstellen; K\u00fchlluft zu kalt \u2192 Drehzahlregelung; Luftmenge zu gro\u00df \u2192 kleineren Ventilator / Drehzahlregelung." },
  { id: 363, block: "Elektrotechnik & Steuerung", question: "HD-Schalter schaltet Verdichter ab \u2013 Gr\u00fcnde und was bei Fehlerbehebung beachten?", answer: "Ursachen: Verfl\u00fcssiger verschmutzt/verstopft, L\u00fcfter aus, K\u00fchlwasser fehlt, Sicherung L\u00fcftermotor ausgel\u00f6st, \u00fcberf\u00fcllt, Fremdgase. Vor dem Wiedereinschalten Fehler unbedingt finden und beheben!" },
  { id: 364, block: "Elektrotechnik & Steuerung", question: "Verfl\u00fcssigungsdruck zu hoch (luftgek\u00fchlt) \u2013 Ursachen und Abhilfe?", answer: "Verfl\u00fcssiger reinigen, Motor/Ventilatorfl\u00fcgel tauschen, Bel\u00fcftung verbessern, falsche Drehrichtung korrigieren, Kan\u00e4le montieren, Fremdgase entfernen und neu bef\u00fcllen, Verfl\u00fcssiger ggf. gr\u00f6\u00dfer w\u00e4hlen, F\u00fcllmenge reduzieren." },
  { id: 365, block: "Elektrotechnik & Steuerung", question: "Verfl\u00fcssigungsdruck zu hoch (wassergek\u00fchlt) \u2013 Ursachen und Abhilfe?", answer: "Wassertemperatur senken, Wassermenge erh\u00f6hen (automatisches Wasserventil), Wasserr\u00f6hre reinigen, Pumpe reparieren/tauschen, Fremdgase entfernen, Verfl\u00fcssiger ggf. gr\u00f6\u00dfer w\u00e4hlen." },
  { id: 366, block: "Elektrotechnik & Steuerung", question: "Verfl\u00fcssigungsdruck zu niedrig (wassergek\u00fchlt) \u2013 Ursachen und Abhilfe?", answer: "Verfl\u00fcssiger zu gro\u00df \u2192 KVR einbauen / tauschen; KVR falsch eingestellt \u2192 richtig einstellen; Wassermenge zu gro\u00df \u2192 Wasserventil montieren/einstellen; Wassertemperatur zu niedrig \u2192 Wassermenge reduzieren (Wasserventil)." },
  { id: 367, block: "Elektrotechnik & Steuerung", question: "Verfl\u00fcssigungsdruck pendelt \u2013 Ursachen und Abhilfe?", answer: "Druckschaltungs-Differenz zu gro\u00df \u2192 Drehzahlregler verwenden; TEV pendelt \u2192 \u00dcberhitzung h\u00f6her / kleinere D\u00fcse; R\u00fcckschlagventil falsch dimensioniert/platziert." },
  { id: 368, block: "Elektrotechnik & Steuerung", question: "Filtertrockner kalt, betaut, bereift \u2013 Ursachen und Abhilfe?", answer: "Teilverstopfung \u2192 Trockner erneuern, System auf Feuchtigkeit/S\u00e4ure pr\u00fcfen (ggf. KM und \u00d6l komplett erneuern). \u0394T > 2 K \u2192 tauschen!" },
  { id: 369, block: "Elektrotechnik & Steuerung", question: "Feuchtigkeitsindikator gelb \u2013 Ursachen und Abhilfe?", answer: "Feuchtigkeit \u2192 Kreislauf auf Feuchtigkeit/S\u00e4ure pr\u00fcfen, Herkunft der Feuchtigkeit ermitteln, Trockner erneuern, ggf. KM und \u00d6l komplett erneuern." },
  { id: 370, block: "Elektrotechnik & Steuerung", question: "Feuchtigkeitsindikator braun/schwarz \u2013 Ursachen und Abhilfe?", answer: "Verschmutzung/Partikel \u2192 Kreislauf reinigen, Trockner, Schauglas, \u00d6l wechseln." },
  { id: 371, block: "Elektrotechnik & Steuerung", question: "\u00d6l sch\u00e4umt beim Anlauf \u2013 Ursachen und Abhilfe?", answer: "KM im \u00d6l durch niedrige Temperatur \u2192 Kurbelgeh\u00e4useheizung anbringen. Bei Anlagen mit \u00d6labscheider: \u00d6labscheider w\u00e4hrend Stillstand zu kalt \u2192 Heizelement montieren oder MV mit Zeitverz\u00f6gerung in \u00d6lr\u00fcckf\u00fchrrohr." },
  { id: 372, block: "Elektrotechnik & Steuerung", question: "Dampfblasen im Schauglas vor TEV \u2013 Ursachen?", answer: "Unterk\u00fchlung zu gering (Druckabfall, W\u00e4rmeeintrag), falsche K\u00fchlwasserf\u00fchrung, H\u00f6henunterschied TEV\u2013Sammler, defekte Verfl\u00fcssigungsdruckregelung, KM-Mangel." },
  { id: 373, block: "Elektrotechnik & Steuerung", question: "Anlage taktet \u00fcber ND-Schalter \u2013 Ursachen?", answer: "Verdichter zu gro\u00df f\u00fcr aktuelle Last, KM-Mangel, Verdampfungsdruckregler zu hoher \u00d6ffnungsdruck, Druckdifferenz am Schalter falsch eingestellt." },
  { id: 374, block: "Elektrotechnik & Steuerung", question: "Wie kann der S\u00e4uregehalt in einer K\u00e4lteanlage \u00fcberpr\u00fcft werden?", answer: "S\u00e4uretester \u2013 \u00d6l wird mit Testfl\u00fcssigkeit verbunden, Verf\u00e4rbung zeigt S\u00e4ure an." },
  { id: 375, block: "Elektrotechnik & Steuerung", question: "Anlage taktet \u00fcber HD-Schalter \u2013 Ursachen?", answer: "Verfl\u00fcssigungsdruck zu hoch (W\u00e4rmeabfuhr gest\u00f6rt \u2013 L\u00fcfter aus, Pumpe aus), oder Fehler am HD-Schalter. Reset-Schalter kann Takten verhindern." },
  { id: 376, block: "Elektrotechnik & Steuerung", question: "Verdichter hat sehr hohe Oberfl\u00e4chentemperatur \u2013 Ursachen?", answer: "HD zu hoch, zu hohe Verdampferbelastung \u2192 Motor\u00fcberlastung, Motork\u00fchlung ausgefallen, zu hohe Sauggas\u00fcberhitzung, KM-Mangel und lange Laufzeit." },
  { id: 377, block: "Elektrotechnik & Steuerung", question: "\u00d6lstand im Kurbelgeh\u00e4use zu niedrig \u2013 Ursachen?", answer: "Zu geringe F\u00fcllmenge, mangelhafte \u00d6lr\u00fcckf\u00fchrung (falsche Rohrdimension, fehlender Abscheider, fehlendes Gef\u00e4lle), parallele Verdichter nicht auf gleicher Ebene, Schwimmerventil verstopft/h\u00e4ngt, \u00d6lr\u00fcckf\u00fchrleitung verstopft." },
  { id: 378, block: "Elektrotechnik & Steuerung", question: "\u00d6l verf\u00e4rbt \u2013 Ursachen und Abhilfe?", answer: "Ungen\u00fcgende Reinhaltung bei Montage, Feuchtigkeit, zu hohe Druckrohrtemperatur, Verschlei\u00dfpartikel. In allen F\u00e4llen: \u00d6l und Filtertrockner wechseln, ggf. System reinigen." },
  { id: 379, block: "Elektrotechnik & Steuerung", question: "K\u00e4lteleistung zu gering, t\u2080 in Ordnung \u2013 Ursachen und Abhilfe?", answer: "Druckabfall \u00fcber TEV kleiner als ausgelegt \u2192 gr\u00f6\u00dfere D\u00fcse/Ventil; TEV zu klein \u2192 gr\u00f6\u00dferes Ventil/D\u00fcse." },
  { id: 380, block: "Elektrotechnik & Steuerung", question: "Verdichter nassfahren \u2013 Ursachen und Abhilfe?", answer: "TEV zu gro\u00df \u2192 kleineres Ventil/D\u00fcse; \u00dcberhitzung zu niedrig eingestellt \u2192 erh\u00f6hen; F\u00fchlerkontakt schlecht / zu warm angebracht \u2192 F\u00fchler pr\u00fcfen, isolieren, besser platzieren." },
  { id: 381, block: "Elektrotechnik & Steuerung", question: "Was ist ein \u00d6lreguliersystem?", answer: "Mehrere \u00d6labscheider \u2192 \u00d6lsammler \u2192 Differenzdruckventil \u2192 \u00d6lspiegelregulator + Filter \u2192 Verdichter. Bei parallelgeschalteten Abscheidern R\u00fcckschlagventile in \u00d6lr\u00fcckf\u00fchrleitungen." },
  { id: 382, block: "Elektrotechnik & Steuerung", question: "Wie werden Verdichter in Verbundk\u00e4lteanlagen geregelt?", answer: "Abh\u00e4ngig vom Saugdruck in der Saugleitung (elektronische Verbundregler). Bei steigendem Druck \u2192 Verdichter/Leistungsstufe zu, bei sinkendem \u2192 ab." },
  { id: 383, block: "Elektrotechnik & Steuerung", question: "K\u00fchlstellenregelung in Verbundanlagen?", answer: "Jede K\u00fchlstelle hat einen K\u00fchlstellenregler, der ein MV in der Fl\u00fcssigkeitsleitung ansteuert. Bei K\u00fchlbedarf MV + L\u00fcfter ein, bei erreichter Temperatur MV zu." },
  { id: 384, block: "Elektrotechnik & Steuerung", question: "Was ist eine Verbundk\u00e4lteanlage?", answer: "Mehrere Verdichter in einem Kreislauf, versorgen mehrere K\u00fchlstellen, die nicht immer gleichzeitig in Betrieb sind (z. B. Superm\u00e4rkte)." },
  { id: 385, block: "Elektrotechnik & Steuerung", question: "Vorteile Verbundk\u00e4lteanlagen?", answer: "Stufenlose Leistungsanpassung (FU), geringere Gesamtleistung (Gleichzeitigkeitsfaktor 0,6\u20130,8), hohe Ausfallsicherheit, kleineres Rohrnetz, effiziente W\u00e4rmer\u00fcckgewinnung." },
  { id: 386, block: "Elektrotechnik & Steuerung", question: "Nachteile Verbundk\u00e4lteanlagen?", answer: "Komplexere Regelung, bei Gesamtausfall alle K\u00fchlstellen tot, bei Wicklungsbrand gesamter Kreislauf verschmutzt, bei Leckage entweicht gesamte F\u00fcllmenge." },
  { id: 387, block: "Elektrotechnik & Steuerung", question: "Warum Leckageerkennung bei Verbundanlagen sinnvoll?", answer: "Damit bei einer Leckage an einer K\u00fchlstelle nicht die gesamte F\u00fcllmenge entweicht. Fr\u00fchwarnung durch Sammler-F\u00fcllstands\u00fcberwachung oder Gaswarnanlage." },
  { id: 388, block: "Elektrotechnik & Steuerung", question: "Was ist beim Bau von Tiefk\u00fchlanlagen besonders zu beachten?", answer: "Augenmerk auf Abtauung, Kondensatablauf mit Heizb\u00e4ndern beheizen, Druckausgleichsklappe im K\u00fchlraum vorsehen." },
  { id: 389, block: "Elektrotechnik & Steuerung", question: "Warum Gewichtsverlust bei unverpacktem Fleisch?", answer: "Zu geringe relative Feuchte \u2192 Fleisch trocknet aus \u2192 Gewichtsverlust = Warenwert- und Qualit\u00e4tsverlust." },
  { id: 390, block: "Elektrotechnik & Steuerung", question: "Warum darf die relative Feuchte bei Fleisch nicht zu gro\u00df sein?", answer: "Sonst Bakterienbildung, Fleisch wird schmieriger." },
  { id: 391, block: "Elektrotechnik & Steuerung", question: "Was bedeutet Schutzklasse I, II, III?", answer: "Klasse Prinzip Schutzleiter I Schutzleiter + Basisisolierung Ja (PE) II Schutzisolierung Nein III Schutzkleinspannung Nein (< 50 V)" },
  { id: 392, block: "Elektrotechnik & Steuerung", question: "Was ist CA-Lagerung und ULO-Lagerung?", answer: "CA = Controlled Atmosphere (kontrollierte Atmosph\u00e4re: O\u2082, N\u2082, CO\u2082 einstellbar). ULO = Ultra Low Oxygen (extrem sauerstoffreduziert, minimale Reifeaktivit\u00e4t)." },
  { id: 393, block: "Elektrotechnik & Steuerung", question: "Was versteht man unter K\u00e4ltebedarf?", answer: "Summe aller W\u00e4rmestr\u00f6me, die in einen K\u00fchlraum eindringen (Transmission, Luftwechsel, K\u00fchlgut, Beleuchtung, Personen, Maschinen). Dient zur Bestimmung der erforderlichen K\u00e4lteleistung." },
  { id: 394, block: "Elektrotechnik & Steuerung", question: "Welche Informationen f\u00fcr eine K\u00e4ltebedarfsberechnung?", answer: "K\u00fchlg\u00fcter (Art, Masse, Einbringtemperatur, Beschickungszyklus), Raumtemperatur (Plus/TK), Lager- oder Abk\u00fchlraum, Personen und Aufenthaltsdauer, Raumma\u00dfe/Volumen, Umgebungstemperatur, D\u00e4mmung, Beleuchtung (Art/Dauer), elektr. Verbraucher und Betriebsdauer." },
  { id: 395, block: "Elektrotechnik & Steuerung", question: "Aus welchen Anteilen setzt sich der K\u00e4ltebedarf zusammen?", answer: "Transmission, Luftwechsel, K\u00fchlgut, Atmungsw\u00e4rme (Obst/Gem\u00fcse), Verdampfer-Ventilatormotor, Abtauheizung, Beleuchtung, Personen, Arbeitsmaschinen/Ger\u00e4te, Strahlungsw\u00e4rme (au\u00dfenliegende W\u00e4nde)." },
  { id: 396, block: "Elektrotechnik & Steuerung", question: "Innerer und \u00e4u\u00dferer Lastanteil?", answer: "\u00c4u\u00dferer: Transmission, Luftwechsel (von Umgebung in den Raum). Innerer: K\u00fchlgut, Beleuchtung, Personen, Atmungsw\u00e4rme (Quelle innerhalb des Raumes)." },
  { id: 397, block: "Elektrotechnik & Steuerung", question: "Lagertemperatur und Feuchte f\u00fcr \u00c4pfel, Fleisch, Bananen, Fisch, Blattgem\u00fcse?", answer: "\u00c4pfel: \u20131 bis 4 \u00b0C, 85\u201395 % r.F. Frisches Fleisch: 0,5\u20131,5 \u00b0C, 85\u201390 % r.F. Bananen: 12\u201314 \u00b0C, 85\u201395 % r.F. Fisch frisch in Eis: 0\u20132 \u00b0C, 90\u201395 % r.F. Blattgem\u00fcse: 0 \u00b0C, 90\u201395 % r.F." },
  { id: 398, block: "Elektrotechnik & Steuerung", question: "Wie wird der Energieverbrauch einer K\u00e4lteanlage berechnet?", answer: "Leistungsaufnahme messen, Betriebsstunden pro Tag ermitteln, multiplizieren \u2192 Energieverbrauch pro Tag. F\u00fcr Kosten mit Strompreis multiplizieren." },
  { id: 399, block: "Elektrotechnik & Steuerung", question: "Was ist der Kv-Wert eines Ventils?", answer: "Wasserdurchfluss in m\u00b3/h durch das Ventil bei einem Druckabfall von 1 bar (Durchflusskoeffizient). Dient zur Ventilauslegung." },
  { id: 400, block: "Elektrotechnik & Steuerung", question: "Unter welchen Bedingungen muss in einem K\u00fchlraum geheizt werden?", answer: "TK-R\u00e4ume unter 0 \u00b0C: Abtauheizung, T\u00fcrrahmenheizung (gegen Reif), Ablaufheizung (gegen Einfrieren)." },
  { id: 401, block: "F-Gase & Umweltrecht", question: "Was ist Energieeffizienz in der K\u00e4ltetechnik? Ma\u00dfnahmen?", answer: "Verh\u00e4ltnis Nutzen (K\u00e4lte) zu Aufwand (Strom). Ma\u00dfnahmen: Drehzahlregelung Verdichter/L\u00fcfter, EEV einsetzen, Verfl\u00fcssigungstemperatur absenken, t\u2080 anheben, W\u00e4rmer\u00fcckgewinnung, Abw\u00e4rmenutzung." },
  { id: 402, block: "F-Gase & Umweltrecht", question: "Welche nationalen Gesetze und Verordnungen gibt es?", answer: "K\u00e4lteanlagenverordnung (KAV), Duale-Druckger\u00e4teverordnung, Druckger\u00e4te\u00fcberwachungsverordnung (DG\u00dcW-V), Arbeitsst\u00e4ttenverordnung (ASV)." },
  { id: 403, block: "F-Gase & Umweltrecht", question: "Welche EU-Verordnungen gibt es?", answer: "F-Gase-Verordnung, Zertifizierungsverordnung, Dichtheitskontrollverordnung, Kennzeichnungsverordnung, Ozonschichtverordnung." },
  { id: 404, block: "F-Gase & Umweltrecht", question: "Wo werden nationale Rechtsvorschriften kundgemacht?", answer: "Bundesgesetzblatt (BGB), rechtlich verbindlich \u00fcber das Rechtsinformationssystem des Bundes (RIS)." },
  { id: 405, block: "F-Gase & Umweltrecht", question: "Unterschied \u00d6NORM und Gesetz/Verordnung?", answer: "Rechtsnorm = verpflichtend. Norm = Empfehlung, wird erst durch vertragliche Vereinbarung oder gesetzliche Erkl\u00e4rung verbindlich." },
  { id: 406, block: "F-Gase & Umweltrecht", question: "Unter welchen Umst\u00e4nden kann eine \u00d6NORM verbindlich werden?", answer: "Wenn der Gesetzgeber sie f\u00fcr verbindlich erkl\u00e4rt (Gesetzescharakter) oder wenn sie vertraglich vereinbart wird (Privatrecht)." },
  { id: 407, block: "F-Gase & Umweltrecht", question: "Welche \u00d6NORMen gibt es in der K\u00e4ltetechnik?", answer: "EN 378 Teile 1\u20134 (Sicherheit/Umweltschutz), EN ISO 22712 (Sachkunde), EN 14276 Teile 1+2 (Druckger\u00e4te)." },
  { id: 409, block: "F-Gase & Umweltrecht", question: "Welches Schutzziel hat die KAV?", answer: "Schutz der Arbeitnehmer:innen und der Nachbarschaft." },
  { id: 410, block: "F-Gase & Umweltrecht", question: "Ab welchem F\u00fcllgewicht gilt die KAV?", answer: "1,5 kg K\u00e4ltemittel (au\u00dfer Luft oder Wasser)." },
  { id: 411, block: "F-Gase & Umweltrecht", question: "Welche K\u00e4ltemittel sind vom Geltungsbereich der KAV ausgenommen?", answer: "Ausschlie\u00dflich Luft und Wasser." },
  { id: 412, block: "F-Gase & Umweltrecht", question: "Was sagt die KAV \u00fcber das F\u00fchren eines Pr\u00fcfbuches?", answer: "F\u00fcr jede Anlage muss ein Pr\u00fcfbuch gef\u00fchrt werden mit Zeitpunkt und festgestellten M\u00e4ngeln jeder Pr\u00fcfung nach \u00a722. Aufbewahrung solange die Anlage in Betrieb ist; muss Beh\u00f6rden jederzeit vorgewiesen werden k\u00f6nnen." },
  { id: 413, block: "F-Gase & Umweltrecht", question: "Welche Inhalte muss das Pr\u00fcfbuch nach KAV umfassen?", answer: "Typenschild-Angaben (\u00a710), Bescheinigungen \u00fcber Druckproben (\u00a79, \u00a722 Abs.2), Probe vor Inbetriebnahme (\u00a716), Best\u00e4tigung der Errichtung nach KAV. Gr\u00f6\u00dfere Instandsetzungen/\u00c4nderungen sind zu vermerken." },
  { id: 414, block: "F-Gase & Umweltrecht", question: "Was ist j\u00e4hrlich im Pr\u00fcf- und Anlagenbuch zu dokumentieren?", answer: "Bei jeder \u00dcberpr\u00fcfung: Angabe, ob die Anlage aus sicherheitstechnischer Sicht weiter betrieben werden kann." },
  { id: 415, block: "F-Gase & Umweltrecht", question: "Welche Sicherheitseinrichtung muss jede Druckstufe haben?", answer: "Eine Einrichtung gegen \u00dcberschreitung des h\u00f6chstzul\u00e4ssigen Betriebsdrucks: Sicherheitsventile, Bruchplatten oder \u00dcberdruckschalter. Schmelzpfropfen allein gen\u00fcgen nicht." },
  { id: 416, block: "F-Gase & Umweltrecht", question: "Ausf\u00fchrung allseitig absperrbarer Sammler und Verdampfer?", answer: "Wenn die M\u00f6glichkeit einer unzul\u00e4ssigen Drucksteigerung besteht, m\u00fcssen sie mit einer geeigneten Sicherheitseinrichtung ausger\u00fcstet sein." },
  { id: 417, block: "F-Gase & Umweltrecht", question: "Wie ist eine Druckprobe nach KAV durchzuf\u00fchren?", answer: "Mit dem 1,5-fachen des festgelegten h\u00f6chsten Betriebsdrucks, mindestens aber mit dem 1,5-fachen des Sattdampfdrucks bei 40 \u00b0C (bei h\u00f6heren Temperaturen entsprechend h\u00f6her)." },
  { id: 418, block: "F-Gase & Umweltrecht", question: "Angaben auf dem Typenschild nach KAV?", answer: "Errichter (Name/Anschrift), Baujahr, Art des K\u00e4ltemittels, KM-F\u00fcllgewicht (kg), K\u00e4lteleistung (kW), festgelegter h\u00f6chster Betriebsdruck jeder Druckstufe (bar)." },
  { id: 419, block: "F-Gase & Umweltrecht", question: "L\u00fcftungsvorschriften f\u00fcr R\u00e4ume mit K\u00e4ltemaschinen?", answer: "Ausreichend be- und entl\u00fcftbar. Schwere D\u00e4mpfe \u2192 bodennah entl\u00fcften; leichte D\u00e4mpfe (Ammoniak) \u2192 deckennah. Keller: k\u00fcnstliche L\u00fcftung (au\u00dfer <10 kg Gruppe 1). L\u00fcftung von au\u00dferhalb schaltbar." },
  { id: 420, block: "F-Gase & Umweltrecht", question: "Ausf\u00fchrung der elektrischen Anlage (Beleuchtung/L\u00fcftung)?", answer: "Nach Vorschriften f\u00fcr Elektrotechnik. Beleuchtung und L\u00fcftung m\u00fcssen unabh\u00e4ngig voneinander und auch bei abgeschalteter K\u00e4ltemaschine von au\u00dferhalb in Betrieb gesetzt werden k\u00f6nnen." },
  { id: 421, block: "F-Gase & Umweltrecht", question: "Was ist bei der Probe vor Inbetriebnahme durchzuf\u00fchren?", answer: "Probe auf Dichtheit und auf Ansprechen der Sicherheitseinrichtungen beim \u00dcberschreiten des festgelegten h\u00f6chsten Betriebsdrucks. Durch befugte, fachkundige Person." },
  { id: 422, block: "F-Gase & Umweltrecht", question: "Was ist bei der wiederkehrenden \u00dcberpr\u00fcfung nach \u00a722 KAV durchzuf\u00fchren?", answer: "Pr\u00fcfung der Sicherheitseinrichtungen, Abdeckungen, Ber\u00fchrungsschutz, Verletzungsgefahr, Spannungsfreiheit, Hitzeschutz, Korrosion, Befestigung von Rohren/Bauteilen, \u00dcbereinstimmung mit KAV. Durch befugte, fachkundige Person." },
  { id: 423, block: "F-Gase & Umweltrecht", question: "Welche Gef\u00e4hrdungen k\u00f6nnen von K\u00e4lteanlagen ausgehen?", answer: "Verbrennungen, Verletzungen durch bewegliche Teile, Geh\u00f6rsch\u00e4den (L\u00e4rm), Ersticken/Panik durch KM-Austritt, Umweltsch\u00e4den, Explosion/Feuer, Hauterfrierungen, Bersten von Beh\u00e4ltern, Schnittgefahr, elektrische Gef\u00e4hrdung." },
  { id: 424, block: "F-Gase & Umweltrecht", question: "Schutzziel der Arbeitsst\u00e4ttenverordnung? Wie ist die K\u00e4lte-/Klimatechnik betroffen?", answer: "Konkretisierung des Arbeitnehmer:innenschutzes. K\u00e4lte-/Klimatechnik: Klima-/L\u00fcftungsanlagen m\u00fcssen regelm\u00e4\u00dfig gepr\u00fcft und dokumentiert werden." },
  { id: 425, block: "F-Gase & Umweltrecht", question: "Bundes-Arbeitsst\u00e4ttenverordnung vs. ASTV? Unterschiede f\u00fcr die Klima-/L\u00fcftungstechnik?", answer: "ASTV 2014 gilt f\u00fcr Arbeitsst\u00e4tten nach \u00a719 AShG. B-ASTV 2013 gilt f\u00fcr Bundesdienststellen. F\u00fcr unsere Technik keine wesentlichen Unterschiede." },
  { id: 426, block: "F-Gase & Umweltrecht", question: "Wie oft sind Klima-/L\u00fcftungsanlagen zu pr\u00fcfen?", answer: "Mindestens einmal j\u00e4hrlich (l\u00e4ngstens 15 Monate), sowie nach gr\u00f6\u00dferen Instandsetzungen/\u00c4nderungen oder bei begr\u00fcndeten Zweifeln am ordnungsgem\u00e4\u00dfen Zustand (\u00a713 ASTV)." },
  { id: 427, block: "F-Gase & Umweltrecht", question: "Mindeststandards der \u00dcberpr\u00fcfung nach \u00a713 ASTV?", answer: "Sichtpr\u00fcfung, Funktionspr\u00fcfung, Wartungspr\u00fcfung, Reinigung und Pr\u00fcfung der Aufzeichnungen." },
  { id: 428, block: "F-Gase & Umweltrecht", question: "Was wird in der Druckger\u00e4te\u00fcberwachungsverordnung DG\u00dcW-V geregelt?", answer: "Sicherheitstechnische Ma\u00dfnahmen f\u00fcr den Betrieb von Druckbeh\u00e4ltern und Rohrleitungen \u2013 Art und H\u00e4ufigkeit wiederkehrender Pr\u00fcfungen." },
  { id: 429, block: "F-Gase & Umweltrecht", question: "Was ist das Druckinhaltsprodukt?", answer: "Produkt aus PS (bar) \u00d7 Volumen (Liter) des gr\u00f6\u00dften integrierten Druckbeh\u00e4lters (dimensionslose Ma\u00dfzahl)." },
  { id: 430, block: "F-Gase & Umweltrecht", question: "Einteilung in hohes und niedriges Gefahrenpotential?", answer: "Einteilung erfolgt mit Druckinhaltsprodukt und Fluidgruppe. Anlagen mit hohem Gefahrenpotential: 1. Betriebspr\u00fcfung durch notifizierte Stelle erforderlich." },
  { id: 431, block: "F-Gase & Umweltrecht", question: "Was ist unter hohem/niedrigem Gefahrenpotential zu verstehen?", answer: "Hoch: Fluidgruppe 1 und Druckinhaltsprodukt >300, oder Fluidgruppe 2 und >1000. Niedrig: darunter." },
  { id: 432, block: "F-Gase & Umweltrecht", question: "Einteilung der K\u00e4lteanlagen aufgrund des Druckinhaltsprodukts?", answer: "\u2264700: Kleinanlage, >700 \u22643000: Kleingewerbeanlage, >3000 \u22646000: Gro\u00dfgewerbeanlage, >6000: Industrieanlage." },
  { id: 433, block: "F-Gase & Umweltrecht", question: "Grenzwerte f\u00fcr hohes Gefahrenpotential (Fluidgruppe 1 und 2)?", answer: "Fluidgruppe 1: Druckinhaltsprodukt >300. Fluidgruppe 2: >1000." },
  { id: 434, block: "F-Gase & Umweltrecht", question: "Wer muss die erste Betriebspr\u00fcfung bei hohem Gefahrenpotential durchf\u00fchren?", answer: "Eine Kesselpr\u00fcfstelle oder eine akkreditierte Pr\u00fcf-/\u00dcberwachungsstelle." },
  { id: 435, block: "F-Gase & Umweltrecht", question: "Wer kann die erste Betriebspr\u00fcfung bei niederem Gefahrenpotential durchf\u00fchren?", answer: "Der Betreiber oder dessen bevollm\u00e4chtigte, sachkundige Person." },
  { id: 436, block: "F-Gase & Umweltrecht", question: "Wovon handelt die Ozonschichtverordnung (EG 1005/2009)?", answer: "Produktion, Import, Export, Inverkehrbringen, Verwendung, R\u00fcckgewinnung, Recycling und Vernichtung von geregelten Stoffen (ODP)." },
  { id: 437, block: "F-Gase & Umweltrecht", question: "Welche Stoffe werden von der Ozonschichtverordnung geregelt?", answer: "Stoffe mit Ozonabbaupotential (ODP), v. a. FCKW (R-11, R-12, R-502) und HFCKW (R-22) sowie deren Gemische." },
  { id: 438, block: "F-Gase & Umweltrecht", question: "Was schreibt die Ozonschichtverordnung bzgl. Dichtheitskontrollen vor?", answer: "Wiederkehrende Kontrollen abh\u00e4ngig von der F\u00fcllmenge: \u22653 kg: 12 Monate, \u226530 kg: 6 Monate, \u2265300 kg: 3 Monate. Hermetisch geschlossene Systeme <6 kg sind ausgenommen." },
  { id: 439, block: "F-Gase & Umweltrecht", question: "Verl\u00e4ngert ein Leckageerkennungssystem das Intervall nach OzonschichtVO?", answer: "Nein, das ist dort nicht geregelt." },
  { id: 440, block: "F-Gase & Umweltrecht", question: "Ab welcher F\u00fcllmenge m\u00fcssen hermetisch geschlossene Systeme kontrolliert werden?", answer: "Ab 6 kg." },
  { id: 441, block: "F-Gase & Umweltrecht", question: "Zielsetzung der F-Gase-Verordnung?", answer: "Schrittweise Senkung der Menge fluorierter Treibhausgase bis 2030 (PhaseDown) durch Verbote und Produktionsverknappung." },
  { id: 442, block: "F-Gase & Umweltrecht", question: "Welche Stoffe regelt die F-Gase-Verordnung? Beispiele?", answer: "H-FKW mit GWP, z. B. R-134a, R-404A, R-507A, R-513A, R-448A, R-449A, R-410A, R-32, sowie Ersatzgemische (R-422D) und inzwischen auch HFO (R-1234yf) und nat\u00fcrliche KM (Propan, CO\u2082)." },
  { id: 443, block: "F-Gase & Umweltrecht", question: "Welche K\u00e4ltemittel mit hohem GWP sind nicht von der F-Gase-VO erfasst?", answer: "Stoffe, die unter die Ozonschichtverordnung fallen (R-22, R-12)." },
  { id: 444, block: "F-Gase & Umweltrecht", question: "Welche K\u00e4ltemittel mit niedrigem GWP werden jetzt auch behandelt?", answer: "Nat\u00fcrliche K\u00e4ltemittel (Propan, Isobutan, Ammoniak, CO\u2082) und HFO (R-1234yf, R-1234ze)." },
  { id: 445, block: "F-Gase & Umweltrecht", question: "Wie definiert die F-Gase-VO ein hermetisch geschlossenes System?", answer: "Alle KM-f\u00fchrenden Teile beim Hersteller dauerhaft verbunden (Schwei\u00dfen, L\u00f6ten), mit getesteter Leckagerate <3 g/Jahr bei mindestens 1/4 des max. zul\u00e4ssigen Drucks. Reparaturzug\u00e4nge zul\u00e4ssig." },
  { id: 446, block: "F-Gase & Umweltrecht", question: "Was ist das Phase-Down-Szenario?", answer: "Schrittweise Beschr\u00e4nkung der HFKW-Mengen, die in der EU in Verkehr gebracht werden d\u00fcrfen." },
  { id: 447, block: "F-Gase & Umweltrecht", question: "Ab welchem CO\u2082-\u00c4quivalent muss ein Leckageerkennungssystem eingebaut werden?", answer: "Ab 500 Tonnen CO\u2082-\u00c4quivalent." },
  { id: 448, block: "F-Gase & Umweltrecht", question: "Auswirkung eines Leckageerkennungssystems auf das Pr\u00fcfintervall?", answer: "Das Intervall verdoppelt sich (z. B. von 6 auf 12 Monate, von 12 auf 24 Monate)." },
  { id: 449, block: "F-Gase & Umweltrecht", question: "Wie oft muss das Leckageerkennungssystem gepr\u00fcft werden?", answer: "1\u00d7 j\u00e4hrlich, mit Dokumentation im Pr\u00fcf- und Anlagenbuch." },
  { id: 451, block: "EN 378 & Sicherheit", question: "Vorschriften zu K\u00e4ltemitteln mit GWP \u22652500?", answer: "Seit 01.01.2020 Verbot des Inverkehrbringens f\u00fcr neue Anlagen (R-404A, R-507A). Wartung nur noch bis 31.12.2029 mit aufbereitetem/recyceltem KM, wenn \u226540 t CO\u2082-\u00c4q." },
  { id: 452, block: "EN 378 & Sicherheit", question: "Zielsetzung der Zertifizierungsverordnung?", answer: "Alle Personen, die mit F-Gasen hantieren (Installation, Wartung, Dichtheitskontrolle, R\u00fcckgewinnung), m\u00fcssen zertifiziert sein. Ziel: Umweltschutz." },
  { id: 453, block: "EN 378 & Sicherheit", question: "Was sind Personenzertifikate?", answer: "Vorgeschriebene Zertifikate f\u00fcr nat\u00fcrliche Personen, die zertifizierungspflichtige T\u00e4tigkeiten an K\u00e4lteanlagen mit F-Gasen ausf\u00fchren." },
  { id: 454, block: "EN 378 & Sicherheit", question: "M\u00fcssen auch Unternehmen zertifiziert sein?", answer: "Ja, Unternehmenszertifikat erforderlich." },
  { id: 455, block: "EN 378 & Sicherheit", question: "Wie gelangt man in \u00d6sterreich zu einem Personenzertifikat?", answer: "Durch positive Lehrabschlusspr\u00fcfung K\u00e4lteanlagentechnik und Antrag bei der zust\u00e4ndigen Innung (kostenpflichtig)." },
  { id: 456, block: "EN 378 & Sicherheit", question: "Wie gelangt man in \u00d6sterreich zu einem Unternehmenszertifikat?", answer: "Antrag an das zust\u00e4ndige Bundesministerium mit Best\u00e4tigung, dass ausreichend viele zertifizierte Personen besch\u00e4ftigt sind und Werkzeuge/Verfahren zur Verf\u00fcgung stehen." },
  { id: 457, block: "EN 378 & Sicherheit", question: "Ist das Personenzertifikat gleichzusetzen mit der Lehrabschlusspr\u00fcfung?", answer: "Nein. Personenzertifikat = Anforderung der F-Gase-VO/Zertifizierungs-VO. Lehrabschlusspr\u00fcfung bescheinigt umfassende Fachkunde (nach KAV erforderlich)." },
  { id: 458, block: "EN 378 & Sicherheit", question: "Einteilung der K\u00e4ltemittel nach KAV?", answer: "Gruppe 1: nicht brennbar, gering toxisch (CO\u2082, FCKW). Gruppe 2: UEG \u2265 3,5 Vol. % oder toxisch/\u00e4tzend (Ammoniak). Gruppe 3: UEG < 3,5 Vol.% (Propan, Butan)." },
  { id: 459, block: "EN 378 & Sicherheit", question: "Fluidgruppe 1 und 2 nach Dualer-Druckger\u00e4teverordnung?", answer: "Gruppe 1: explosiv, entz\u00fcndbar, akut toxisch (Ammoniak, Propan, R-32). Gruppe 2: alle anderen (R-134a, R-744)." },
  { id: 460, block: "EN 378 & Sicherheit", question: "Einteilung der K\u00e4ltemittel nach ISO 817?", answer: "Klassifikation nach Toxizit\u00e4t (A = gering, B = erh\u00f6ht) und Brennbarkeit (1 = keine, 2L = schwer entflammbar, 2 = gering brennbar, 3 = h\u00f6her brennbar). Z. B. A1, A2L, A3, B2L." },
  { id: 461, block: "EN 378 & Sicherheit", question: "Bedeutung und Beispiele f\u00fcr A1, A2L, A3, B1, B2L, B2, B3?", answer: "A1 (R-513A, R-744): gering toxisch, nicht brennbar. A2L (R-32): gering toxisch, schwer entflammbar. A3 (Propan): gering toxisch, leicht brennbar. B2L (Ammoniak): h\u00f6her toxisch, schwer entflammbar." },
  { id: 462, block: "EN 378 & Sicherheit", question: "Was ist beim Transport gef\u00e4hrlicher G\u00fcter (Handwerkerbefreiung) zu beachten?", answer: "ADR gilt nicht f\u00fcr Bef\u00f6rderungen im Zusammenhang mit der Hauptt\u00e4tigkeit (Baustellen, Reparatur) bis 450 Liter je Verpackung und bestimmten H\u00f6chstmengen, solange die Bef\u00f6rderung nicht der internen/externen Versorgung dient." },
  { id: 463, block: "EN 378 & Sicherheit", question: "Welche gef\u00e4hrlichen Stoffe fallen unter die Handwerkerbefreiung?", answer: "Sauerstoff, Stickstoff, Luft, Argon (verdichtet), Formiergas, Acetylen, Propan, Stickstoff, Azeton, Kleber, Nitroverd\u00fcnnung etc." },
  { id: 464, block: "EN 378 & Sicherheit", question: "Was besagt die 1000-Punkte-Regel?", answer: "Summe der Gefahrenpunkte (Nettomasse \u00d7 Faktor oder Liter \u00d7 Faktor) \u2264 1000, dann kann die Handwerkerbefreiung in Anspruch genommen werden." },
  { id: 465, block: "EN 378 & Sicherheit", question: "Darf man gef\u00e4hrliche G\u00fcter einem Kollegen auf die Baustelle zustellen?", answer: "Nein, nur das fachkundige Personal selbst darf sie transportieren, um sie selbst zu verarbeiten." },
  { id: 466, block: "EN 378 & Sicherheit", question: "Zulieferung gef\u00e4hrlicher G\u00fcter in die Firma zur Zwischenlagerung erlaubt?", answer: "Nein, dies f\u00e4llt nicht unter die Handwerkerbefreiung \u2013 das ist innerbetriebliche Versorgung und unterliegt den vollen ADR-Vorschriften." },
  { id: 467, block: "EN 378 & Sicherheit", question: "Welche Sicherheitsvorschriften sind bei der Bef\u00f6rderung im Rahmen der Handwerkerbefreiung einzuhalten?", answer: "PSA (Warnweste, Handschuhe, Schutzbrille), Alkohol-/Rauchverbot, 2-kgPulverfeuerl\u00f6scher mitf\u00fchren, Gefahrenstoffe kennzeichnen und sichern, Beh\u00e4lter verschlossen und vor W\u00e4rme sch\u00fctzen, Bef\u00f6rderungspapier mitf\u00fchren." },
  { id: 468, block: "EN 378 & Sicherheit", question: "Unterschied gr\u00fcnes und blaues Pr\u00fcfbuch?", answer: "Gr\u00fcn: Kleinanlagen (Druck-Liter-Produkt \u2264700). Blau: f\u00fcr alle Anlagengr\u00f6\u00dfen geeignet. Blau kann immer verwendet werden." },
  { id: 469, block: "EN 378 & Sicherheit", question: "Pr\u00fcfbuch ist voll \u2013 was tun?", answer: "Kunden schriftlich informieren, Angebot f\u00fcr neues Pr\u00fcfbuch \u00fcbermitteln, Vermerk auf letzter Seite. Altes Pr\u00fcfbuch zusammen mit dem neuen ablegen." },
  { id: 470, block: "EN 378 & Sicherheit", question: "Wie ist der maximal zul\u00e4ssige Druck (PS) definiert?", answer: "Vom Hersteller angegebener h\u00f6chster Druck, f\u00fcr den das Ger\u00e4t ausgelegt ist. Entspricht dem Ansprechdruck des Sicherheitsventils oder Abschaltdruck des Sicherheitsdruckschalters." },
  { id: 471, block: "EN 378 & Sicherheit", question: "Was ist bei der Unterweisung zu machen? Dokumentation? Themen?", answer: "Bedienung, Funktion der Sicherheitseinrichtungen, Verhalten bei St\u00f6rf\u00e4llen/Unf\u00e4llen, Infos \u00fcber Wartungs-/\u00dcberpr\u00fcfungsma\u00dfnahmen. Im Pr\u00fcfund Anlagenbuch dokumentieren." },
  { id: 473, block: "EN 378 & Sicherheit", question: "Was ist ein Dampfpolster in K\u00e4ltemittelflaschen? Warum erforderlich?", answer: "Gasf\u00f6rmiger Raum \u00fcber der Fl\u00fcssigkeit. Verhindert Bersten der Flasche bei Temperaturerh\u00f6hung. Daher maximale F\u00fcllmenge nicht \u00fcberschreiten." },
  { id: 474, block: "EN 378 & Sicherheit", question: "Welche PSA bei Kontakt mit K\u00e4ltemittelspritzern? Erste Hilfe?", answer: "Schutzhandschuhe, Schutzbrille. Bei Hautkontakt: mit Wasser sp\u00fclen, Wunden versorgen, ggf. Arzt. Bei Augenkontakt: mit Wasser sp\u00fclen, sofort Arzt." },
  { id: 475, block: "EN 378 & Sicherheit", question: "Welche PSA bei Austausch von Klima-/L\u00fcftungsfiltern?", answer: "Schutzmaske, Schutzbrille, Schutzhandschuhe (Verunreinigungen k\u00f6nnen gesundheitssch\u00e4dlich sein)." },
  { id: 476, block: "EN 378 & Sicherheit", question: "Mit welchem Nenninnendurchmesser sind Sicherheitsdruckschalter anzuschlie\u00dfen?", answer: "Mindestens 4 mm (EN 378). Kapillarrohre sind nicht zul\u00e4ssig (Verstopfungsgefahr)." },
  { id: 477, block: "EN 378 & Sicherheit", question: "Welche Verantwortung hat das k\u00e4ltetechnische Personal?", answer: "Schutz von Mensch und Umwelt: K\u00e4lteanlagen enthalten Gase unter hohem Druck, die gesundheitsgef\u00e4hrdend und umweltsch\u00e4dlich sein k\u00f6nnen. Korrekte Installation, Dichtheitskontrollen, Wartung, R\u00fcckgewinnung." },
  { id: 478, block: "EN 378 & Sicherheit", question: "Unterschied Vollklimaanlage und Teilklimaanlage?", answer: "Vollklima: Heizen, K\u00fchlen, Be-/Entfeuchten, Filtern. Teilklima: Heizen, K\u00fchlen, Entfeuchten (z. B. Split-Ger\u00e4t)." },
  { id: 479, block: "EN 378 & Sicherheit", question: "Was ist eine Split-Klimaanlage?", answer: "Aufteilung in Innenger\u00e4t (Verdampfer) und Au\u00dfenger\u00e4t (Verdichter, Verfl\u00fcssiger, Drosselorgan), verbunden durch Kupferrohre. Drosselorgan im Au\u00dfenger\u00e4t (Ger\u00e4uschverlagerung)." },
  { id: 480, block: "EN 378 & Sicherheit", question: "Warum Drosselorgan bei Split-Klimaanlagen im Au\u00dfenger\u00e4t?", answer: "Einspritzger\u00e4usche werden nach au\u00dfen verlagert." },
  { id: 481, block: "EN 378 & Sicherheit", question: "Split-Klimaanlage k\u00fchlen und heizen \u2013 wie sichergestellt?", answer: "4-Wege-Ventil kehrt Kreislauf um (W\u00e4rmepumpenbetrieb)." },
  { id: 482, block: "EN 378 & Sicherheit", question: "Was ist eine Multi-Split-Klimaanlage?", answer: "Ein Au\u00dfenger\u00e4t versorgt mehrere Innenger\u00e4te, jedes mit eigener Kupferleitung." },
  { id: 483, block: "EN 378 & Sicherheit", question: "Was ist VRV/VRF? Unterschied zu Multi-Split?", answer: "VRV (Daikin) / VRF = variables K\u00e4ltemittelvolumen/-fluss. Ein Au\u00dfenger\u00e4t, viele Innenger\u00e4te, stufenlose Leistungsregelung durch Inverter." },
  { id: 484, block: "EN 378 & Sicherheit", question: "Warum Kondensatablauf \u00fcber Siphon anschlie\u00dfen?", answer: "Geruchsverschluss \u2013 verhindert, dass Bakterien, Pilze und Ger\u00fcche aus der Kanalisation ins Ger\u00e4t gelangen." },
  { id: 485, block: "EN 378 & Sicherheit", question: "Was ist ein Pr\u00e4zisionsklimaschrank? Anwendung?", answer: "Hochpr\u00e4zise Klimager\u00e4te f\u00fcr Serverr\u00e4ume/Rechenzentren. Temperaturregelung \u00b10,1 K, Feuchte \u00b10,5 % r.F." },
  { id: 486, block: "EN 378 & Sicherheit", question: "K\u00e4ltemittelmangel bei Inverter-Splitklima erkennen?", answer: "An steigender Raum-/Ausblastemperatur, nicht am Verdampfungsdruck (wird von der Regelung konstant gehalten)." },
  { id: 487, block: "EN 378 & Sicherheit", question: "Maximale Leitungsl\u00e4nge und H\u00f6henunterschied bei Split-Klimaanlagen?", answer: "Leitungsl\u00e4nge Split 15\u201325 m, Multi-Split 30\u201380 m. H\u00f6henunterschied Split bis 12 m, Multi-Split 10\u201315 m. Immer Herstellerangaben beachten!" },
  { id: 488, block: "EN 378 & Sicherheit", question: "Was ist eine W\u00e4rmepumpe?", answer: "Eine K\u00e4lteanlage, die die Verfl\u00fcssigungsenergie (Heizw\u00e4rme) nutzt. Nimmt W\u00e4rme bei niedrigem Temperaturniveau auf und gibt sie bei h\u00f6herem ab." },
  { id: 489, block: "EN 378 & Sicherheit", question: "Welche W\u00e4rmequellen gibt es f\u00fcr W\u00e4rmepumpen?", answer: "Luft, Wasser (Grundwasser, Abwasser), Erdw\u00e4rme (Flachkollektor, Tiefensonde), industrielle Abw\u00e4rme." },
  { id: 490, block: "EN 378 & Sicherheit", question: "Vor- und Nachteile Luft-Wasser-WP?", answer: "Vorteil: \u00fcberall verf\u00fcgbar, kosteng\u00fcnstig. Nachteil: tiefste Temperaturen bei gr\u00f6\u00dftem W\u00e4rmebedarf, COP niedriger, Abtauung n\u00f6tig." },
  { id: 491, block: "EN 378 & Sicherheit", question: "Vor- und Nachteile Grundwasser-WP?", answer: "Vorteil: konstante, relativ hohe Temperatur (7\u201313 \u00b0C) \u2192 hohe JAZ. Nachteil: nicht \u00fcberall verf\u00fcgbar, Genehmigungen n\u00f6tig." },
  { id: 492, block: "EN 378 & Sicherheit", question: "Vor- und Nachteile Erdreich-WP?", answer: "Vorteil: konstante Verf\u00fcgbarkeit, h\u00f6herer COP als Luft. Nachteil: gro\u00dfer Platzbedarf (Flachkollektor) oder teure Tiefenbohrung." },
  { id: 493, block: "EN 378 & Sicherheit", question: "Wie ver\u00e4ndert sich die Leistungszahl bei sinkender Au\u00dfentemperatur?", answer: "Sinkt, weil der Verdichter eine gr\u00f6\u00dfere Druckdifferenz \u00fcberwinden muss \u2192 mehr Strombedarf." },
  { id: 494, block: "EN 378 & Sicherheit", question: "Was ist die Jahresarbeitszahl (JAZ)?", answer: "JAZ = Heizarbeit pro Jahr / Stromverbrauch pro Jahr. Gibt die reale Effizienz \u00fcber ein Jahr an." },
  { id: 495, block: "EN 378 & Sicherheit", question: "Was ist W\u00e4rmer\u00fcckgewinnung?", answer: "Nutzung der Abw\u00e4rme (Verfl\u00fcssigungs-/Enthitzungsw\u00e4rme) einer K\u00e4lteanlage, z. B. zur Brauchwassererw\u00e4rmung." },
  { id: 496, block: "EN 378 & Sicherheit", question: "Welche elektrischen Betriebsmittel m\u00fcssen in einem Stromkreis mindestens vorhanden sein?", answer: "Spannungsquelle, Leitung, Schalter, Verbraucher." },
  { id: 497, block: "EN 378 & Sicherheit", question: "Wodurch ist elektrischer Strom erkennbar?", answer: "Ausschlie\u00dflich an seiner Wirkung (W\u00e4rme, Licht, Magnetismus)." },
  { id: 498, block: "EN 378 & Sicherheit", question: "Einheit und Formelzeichen des elektrischen Stroms?", answer: "Ampere, A, I." },
  { id: 499, block: "EN 378 & Sicherheit", question: "Einheit und Formelzeichen der elektrischen Spannung?", answer: "Volt, V, U." },
  { id: 500, block: "EN 378 & Sicherheit", question: "Einheit und Formelzeichen des ohmschen Widerstands?", answer: "Ohm, \u03a9, R." },
  { id: 501, block: "Montage & Inbetriebnahme", question: "Was versteht man unter einem ohmschen Widerstand?", answer: "Widerstand, dessen Wert unabh\u00e4ngig von Spannung und Strom ist. Es gilt U = R \u00d7 I." },
  { id: 502, block: "Montage & Inbetriebnahme", question: "Wovon ist der Widerstand eines elektrischen Leiters abh\u00e4ngig?", answer: "L\u00e4nge, Querschnitt, spezifischer Widerstand des Materials, Temperatur." },
  { id: 503, block: "Montage & Inbetriebnahme", question: "Wie \u00e4ndert sich der Widerstand eines Metalldrahtes bei Erw\u00e4rmung?", answer: "Der Widerstand steigt." },
  { id: 504, block: "Montage & Inbetriebnahme", question: "Was ist ein Vorwiderstand? Wo eingesetzt?", answer: "Widerstand in Reihe zum Verbraucher, um Spannung oder Strom zu begrenzen (Beispiel: LED an h\u00f6herer Spannung). Unwirtschaftlich f\u00fcr Spannungsreduktion (Verlustw\u00e4rme). Nicht f\u00fcr Schutzkleinspannung." },
  { id: 505, block: "Montage & Inbetriebnahme", question: "Welchen Nachteil hat die Spannungsreduktion mit Vorwiderst\u00e4nden?", answer: "Ein Teil der Leistung wird im Widerstand in W\u00e4rme umgewandelt \u2013 unwirtschaftlich." },
  { id: 506, block: "Montage & Inbetriebnahme", question: "Was besagt das ohmsche Gesetz?", answer: "U = R \u00d7 I." },
  { id: 507, block: "Montage & Inbetriebnahme", question: "Wie \u00e4ndert sich der Widerstandswert eines NTC-Widerstandes bei Erw\u00e4rmung?", answer: "Der Widerstand sinkt (Hei\u00dfleiter)." },
  { id: 508, block: "Montage & Inbetriebnahme", question: "Wie \u00e4ndert sich der Widerstandswert eines PTC-Widerstandes bei Erw\u00e4rmung?", answer: "Der Widerstand steigt (Kaltleiter)." },
  { id: 509, block: "Montage & Inbetriebnahme", question: "Einheit und Formelzeichen der elektrischen Leistung?", answer: "Watt, W, P." },
  { id: 510, block: "Montage & Inbetriebnahme", question: "Welche Gefahren gehen von einem elektrischen Kurzschluss aus?", answer: "Sehr hohe Str\u00f6me \u2192 starke Erw\u00e4rmung der Leiter \u2192 Brandgefahr." },
  { id: 511, block: "Montage & Inbetriebnahme", question: "Warum darf an einen Verbraucher nur die Nennspannung angelegt werden?", answer: "H\u00f6here Spannung = h\u00f6herer Strom (Ohmsches Gesetz) \u2192 \u00dcberlastung, Zerst\u00f6rung." },
  { id: 512, block: "Montage & Inbetriebnahme", question: "Warum werden elektrische Verbraucher in der Regel parallel angeschlossen?", answer: "Gleiche Spannung an allen Verbrauchern (230 V), unabh\u00e4ngiger Betrieb." },
  { id: 513, block: "Montage & Inbetriebnahme", question: "Was passiert in einer Reihenschaltung, wenn ein Verbraucher unterbricht?", answer: "Der gesamte Stromkreis ist unterbrochen \u2013 alle Verbraucher gehen aus." },
  { id: 514, block: "Montage & Inbetriebnahme", question: "Was passiert in einer Parallelschaltung, wenn ein Verbraucher unterbricht?", answer: "Nur dieser eine Pfad ist unterbrochen, die anderen Verbraucher arbeiten weiter." },
  { id: 515, block: "Montage & Inbetriebnahme", question: "Zusammenhang zwischen Leistung, Spannung und Strom bei ohmschen Verbrauchern?", answer: "P = U \u00d7 I." },
  { id: 516, block: "Montage & Inbetriebnahme", question: "Was ist bei elektrischen Ger\u00e4ten unter Nennleistung zu verstehen?", answer: "Die aufgenommene Leistung (Gl\u00fchlampe, Staubsauger). Bei Motoren: die abgegebene Wellenleistung." },
  { id: 517, block: "Montage & Inbetriebnahme", question: "Nennleistung bei Elektromotoren?", answer: "Die Leistung, die der Motor im Nennpunkt an der Welle abgibt (Typenschild)." },
  { id: 518, block: "Montage & Inbetriebnahme", question: "Warum darf der Spannungsabfall in Leitungen einen bestimmten Wert nicht \u00fcberschreiten?", answer: "Verluste (W\u00e4rme), geringere Spannung am Verbraucher \u2192 reduzierte Leistung, ineffizient." },
  { id: 519, block: "Montage & Inbetriebnahme", question: "Was ist unter Kapazit\u00e4t eines Kondensators zu verstehen?", answer: "Speicherverm\u00f6gen f\u00fcr elektrische Ladungen. Einheit: Farad (F). In der K\u00e4ltetechnik typisch \u00b5F." },
  { id: 520, block: "Montage & Inbetriebnahme", question: "Wie wird ein Kondensator auf Funktion gepr\u00fcft?", answer: "Mit einem Multimeter mit Kapazit\u00e4tsmessfunktion." },
  { id: 521, block: "Montage & Inbetriebnahme", question: "Was ist Wechselstrom?", answer: "Strom, dessen St\u00e4rke und Richtung sich periodisch mit der Zeit \u00e4ndert." },
  { id: 522, block: "Montage & Inbetriebnahme", question: "Kurvenform der Wechselspannung im \u00f6ffentlichen Netz?", answer: "Sinusf\u00f6rmig." },
  { id: 523, block: "Montage & Inbetriebnahme", question: "Was ist die Frequenz einer Wechselspannung?", answer: "Anzahl der Perioden pro Sekunde. Einheit: Hertz (Hz). Im \u00f6ffentlichen Netz: 50 Hz." },
  { id: 524, block: "Montage & Inbetriebnahme", question: "Was bedeutet es, wenn Strom und Spannung in Phase sind?", answer: "Sie erreichen gleichzeitig ihren Scheitelwert und Nulldurchgang." },
  { id: 525, block: "Montage & Inbetriebnahme", question: "Wie wird das Verh\u00e4ltnis Wirkleistung zu Scheinleistung bezeichnet?", answer: "Leistungsfaktor, cos \u03c6 (manchmal auch \u03bb)." },
  { id: 526, block: "Montage & Inbetriebnahme", question: "Was ist Dreiphasenwechselstrom (Drehstrom)?", answer: "Drei um 120\u00b0 phasenverschobene Wechselstr\u00f6me, miteinander verkettet." },
  { id: 527, block: "Montage & Inbetriebnahme", question: "Leiter-, Au\u00dfenleiter-, Stern-, Dreieckspannung?", answer: "Au\u00dfenleiterspannung: zwischen zwei Au\u00dfenleitern (z. B. L1\u2013L2). Sternspannung: zwischen Au\u00dfenleiter und Sternpunkt. Im 400/230V-Netz: 400 V/230 V." },
  { id: 528, block: "Montage & Inbetriebnahme", question: "Gef\u00e4hrliche Wirkungen des elektrischen Stroms auf den K\u00f6rper?", answer: "Verbrennungen, Muskelkr\u00e4mpfe, Ateml\u00e4hmung, Herzstillstand, Herzkammerflimmern, Herzrhythmusst\u00f6rungen." },
  { id: 529, block: "Montage & Inbetriebnahme", question: "Ab wann besteht Lebensgefahr durch Strom?", answer: "Ab ca. 10 mA (Krampfwirkung, Loslassen unm\u00f6glich). Wechselstrom ab 0,5 mA wahrnehmbar." },
  { id: 532, block: "Montage & Inbetriebnahme", question: "Sichtpr\u00fcfung von Elektrowerkzeugen \u2013 worauf achten?", answer: "Stecker, Anschlussleitung, Kabeleinf\u00fchrung, Knickschutzt\u00fclle, allgemeiner Zustand. Bei M\u00e4ngeln sofort durch befugte Person beheben lassen." },
  { id: 534, block: "Montage & Inbetriebnahme", question: "Was ist ein Kurzschluss?", answer: "Fast widerstandslose Verbindung zwischen zwei Spannungspolen \u2192 sehr hoher Strom." },
  { id: 535, block: "Montage & Inbetriebnahme", question: "Was ist ein K\u00f6rperschluss?", answer: "Leitende Verbindung zwischen aktiven Teilen und dem Geh\u00e4use eines Betriebsmittels." },
  { id: 536, block: "Montage & Inbetriebnahme", question: "Was ist ein Erdschluss?", answer: "Leitende Verbindung zwischen einem elektrischen Leiter und dem Erdpotential." },
  { id: 537, block: "Montage & Inbetriebnahme", question: "Was ist ein Isolationsfehler?", answer: "Fehlerhafter Zustand der Isolierung." },
  { id: 538, block: "Montage & Inbetriebnahme", question: "Was ist ein Leiterschluss?", answer: "Verbindung zwischen betriebsm\u00e4\u00dfig gegeneinander unter Spannung stehenden Leitern durch Isolationsfehler." },
  { id: 539, block: "Montage & Inbetriebnahme", question: "Was ist ein Schutzleiter? Abk\u00fcrzung, Farbe? PE (gr\u00fcn-gelb). Leiter zum Schutz gegen elektrischen Schlag, f\u00fchrt Erdpotential, darf niemals unterbrochen oder geschaltet werden.", answer: "540. 3-Stufen-Schutzkonzept der \u00d6VE? Basisschutz (Ber\u00fchrungsschutz), Fehlerschutz (indirektes Ber\u00fchren), Zusatzschutz (bei Versagen, z. B. FI)." },
  { id: 541, block: "Montage & Inbetriebnahme", question: "Schutzklasse eines Ger\u00e4tes? Unterschiede? I: Schutzleiter + Basisisolierung (Schuko). II: Schutzisolierung, kein PE (Konturen-/Flachstecker). III: Schutzkleinspannung <50 V.", answer: "542. 3 Schutzma\u00dfnahmen ohne Schutzleiter? Schutzisolierung, Schutzkleinspannung, Schutztrennung. 543. 3 Schutzma\u00dfnahmen mit Schutzleiter? Schutzerdung, Nullung, Fehlerstromschutzschaltung (FI)." },
  { id: 545, block: "Montage & Inbetriebnahme", question: "Wo wird die Schutzisolierung angewandt?", answer: "Haushaltsger\u00e4te, K\u00fcchenger\u00e4te, kleinere Handwerkzeuge." },
  { id: 546, block: "Montage & Inbetriebnahme", question: "Was ist die Schutzma\u00dfnahme Nullung?", answer: "K\u00f6rperschluss wird in einen Kurzschluss umgewandelt \u2192 \u00dcberstromausl\u00f6ser (Sicherung/LS) l\u00f6st aus \u2192 Ger\u00e4t vom Netz getrennt." },
  { id: 547, block: "Montage & Inbetriebnahme", question: "Kennfarben Neutralleiter und Schutzleiter?", answer: "N = hellblau, PE = gr\u00fcn-gelb." },
  { id: 548, block: "Montage & Inbetriebnahme", question: "Was ist beim Anschluss des Schutzleiters in einem Schutzkontaktstecker zu ber\u00fccksichtigen?", answer: "Muss l\u00e4nger sein als die Au\u00dfenleiter \u2013 rei\u00dft als Letztes aus der Verbindung." },
  { id: 549, block: "Montage & Inbetriebnahme", question: "Was ist unter der Schutzart zu verstehen?", answer: "Eignung von Betriebsmitteln f\u00fcr verschiedene Umgebungsbedingungen, z. B. IP54. 1. Ziffer: Schutz gegen Fremdk\u00f6rper/Ber\u00fchrung, 2. Ziffer: Schutz gegen Wasser." },
  { id: 550, block: "Montage & Inbetriebnahme", question: "F\u00fcr welche Schaltaufgaben sind Hauptsch\u00fctze und Hilfssch\u00fctze geeignet?", answer: "Hauptsch\u00fctz: Hauptstromkreise (Motoren, Verdichter). Hilfssch\u00fctz: Steuerstromkreise, Zeitrelais." },
  { id: 551, block: "Fehlerdiagnose & Wartung", question: "Unterschied zwischen Sch\u00fctz und Relais?", answer: "Sch\u00fctz: doppelt unterbrechende Kontakte, Funkenl\u00f6schkammer, h\u00f6here Schaltleistung. Relais: meist einfach unterbrechend, kleinere Leistung, kann Wechselkontakte haben." },
  { id: 552, block: "Fehlerdiagnose & Wartung", question: "Gebrauchskategorien von Sch\u00fctzen (AC-2, AC-3)?", answer: "AC-2: Schleifringl\u00e4ufer (Anlassen/Ausschalten). AC-3: K\u00e4figl\u00e4ufer (Anlassen, Ausschalten w\u00e4hrend des Laufs). AC-8a/b: hermetische Verdichtermotoren (manuell/automatisch r\u00fcckstellend)." },
  { id: 553, block: "Fehlerdiagnose & Wartung", question: "Aufgabe des L\u00fcfters auf der Motorwelle?", answer: "K\u00fchlung des Motors, W\u00e4rmeabfuhr." },
  { id: 554, block: "Fehlerdiagnose & Wartung", question: "Warum muss die Motorw\u00e4rme abgef\u00fchrt werden?", answer: "Hohe Temperaturen sch\u00e4digen Isolierung und Lager." },
  { id: 555, block: "Fehlerdiagnose & Wartung", question: "Wichtige Angaben auf dem Leistungsschild eines Motors?", answer: "Nennspannung, Nennstrom, Nennleistung, Nenndrehzahl, Nennfrequenz, cos \u03c6, Anschlussart (Stern/Dreieck)." },
  { id: 556, block: "Fehlerdiagnose & Wartung", question: "Aufgabe des Anlaufkondensators bei 1-phasigen Verdichtermotoren?", answer: "Phasenverschiebung erzeugen (Drehfeld f\u00fcr Hilfswicklung) \u2192 Anlaufmoment." },
  { id: 557, block: "Fehlerdiagnose & Wartung", question: "Wozu zwei Kondensatoren bei Einphasenmotoren? Anlaufkondensator (hohes Moment, schaltet nach Start ab) + Betriebskondensator (bleibt in Betrieb, st\u00fctzt Drehmoment).", answer: "558. 3 Arten von Anlaufvorrichtungen f\u00fcr 1-phasige Motoren? Stromabh\u00e4ngiges Anlaufrelais, spannungsabh\u00e4ngiges Anlaufrelais, PTCAnlassvorrichtung (je mit Anlaufkondensator)." },
  { id: 559, block: "Fehlerdiagnose & Wartung", question: "Wie funktioniert ein stromabh\u00e4ngiges Startrelais?", answer: "Spule in Reihe mit Hauptwicklung. Hoher Anlaufstrom l\u00e4sst Relais anziehen \u2192 Anlaufkondensator zugeschaltet. Bei Nennstrom f\u00e4llt Relais ab." },
  { id: 560, block: "Fehlerdiagnose & Wartung", question: "Verfahren zur Anlaufstrombegrenzung bei Drehstrommotoren?", answer: "Stern-Dreieck-Anlauf, Teilwicklungsanlauf, Widerstandsanlauf, Sanftanlauf (Phasenanschnitt), FU." },
  { id: 561, block: "Fehlerdiagnose & Wartung", question: "Wie wird die Drehrichtung eines Drehstromasynchronmotors ge\u00e4ndert?", answer: "Zwei Au\u00dfenleiter tauschen (z. B. L1 und L2)." },
  { id: 562, block: "Fehlerdiagnose & Wartung", question: "Warum gr\u00f6\u00dfere Motoren nicht direkt anlaufen lassen?", answer: "Hoher Anlaufstrom verursacht Spannungsabfall (Lichtflackern) \u2013 Netzbelastung. EVU-Vorschriften beachten." },
  { id: 563, block: "Fehlerdiagnose & Wartung", question: "Anschluss f\u00fcr Rechtslauf Drehstromasynchronmotor?", answer: "Im Dreieck: L1\u2013U1, L2\u2013V1, L3\u2013W1." },
  { id: 564, block: "Fehlerdiagnose & Wartung", question: "Welche Motorarten werden in der K\u00e4ltetechnik verwendet?", answer: "Drehstromasynchronmotor, Kondensatormotor, EC-Ventilator, Schrittmotor (EEV), Spaltpolmotor." },
  { id: 565, block: "Fehlerdiagnose & Wartung", question: "Wozu dienen Leitungsschutzschalter (LS-Schalter)?", answer: "Schutz vor \u00dcberlast (thermisch, verz\u00f6gert) und Kurzschluss (magnetisch, unverz\u00f6gert). Zus\u00e4tzlich manuelle Schaltfunktion." },
  { id: 566, block: "Fehlerdiagnose & Wartung", question: "Was ist Freiausl\u00f6sung bei LS-Schaltern?", answer: "LS-Schalter l\u00f6st auch dann aus, wenn der Schalthebel in der EIN-Stellung festgehalten wird." },
  { id: 567, block: "Fehlerdiagnose & Wartung", question: "Zwei Ausl\u00f6semechanismen eines LS-Schalters?", answer: "Thermischer Ausl\u00f6ser (Bimetall, \u00dcberlast) und magnetischer Ausl\u00f6ser (Spule, Kurzschluss)." },
  { id: 568, block: "Fehlerdiagnose & Wartung", question: "Wozu dient die Pr\u00fcftaste eines FI-Schutzschalters?", answer: "Erzeugt k\u00fcnstlichen Fehlerstrom \u2192 l\u00f6st FI aus \u2192 Funktionstest. Die dahinterliegende Schutzma\u00dfnahme wird damit nicht gepr\u00fcft." },
  { id: 569, block: "Fehlerdiagnose & Wartung", question: "Wichtige Kenndaten eines FI-Schutzschalters?", answer: "Bemessungsstrom (A), Bemessungsfehlstrom (z. B. 30 mA), Sensitivit\u00e4t (AC, A, B), Bemessungsspannung." },
  { id: 570, block: "Fehlerdiagnose & Wartung", question: "Zwei FI in Serie \u2013 worauf achten?", answer: "Selektivit\u00e4t! Ausl\u00f6sekennlinien abstimmen, sodass nur der nachgeschaltete ausl\u00f6st (Staffelung)." },
  { id: 571, block: "Fehlerdiagnose & Wartung", question: "Ausl\u00f6secharakteristik von LS-Schaltern?", answer: "B (3\u20135\u00d7 In, Haushalt), C (5\u201310\u00d7 In, Motorstromkreise), D (10\u201320\u00d7 In, hohe Einschaltstr\u00f6me)." },
  { id: 572, block: "Fehlerdiagnose & Wartung", question: "Funktion eines Motorschutzschalters?", answer: "Schutz vor \u00dcberlastung durch thermische Ausl\u00f6ser (Bimetall) und vor Kurzschluss durch elektromagnetische Ausl\u00f6ser. Einstellung auf Motorbemessungsstrom." },
  { id: 573, block: "Fehlerdiagnose & Wartung", question: "Ausl\u00f6searten des Motorschutzschalters?", answer: "Thermisch (\u00dcberstromausl\u00f6sung) und elektromagnetisch (Kurzschlussausl\u00f6sung)." },
  { id: 574, block: "Fehlerdiagnose & Wartung", question: "Worin unterscheidet sich ein Motorschutzrelais von einem Motorschutzschalter?", answer: "Motorschutzrelais hat keinen Kurzschlussausl\u00f6ser und schaltet nicht den Hauptstromkreis, sondern einen \u00d6ffnerkontakt (95/96) im Steuerstromkreis." },
  { id: 575, block: "Fehlerdiagnose & Wartung", question: "Warum m\u00fcssen bei einem Motorschutzrelais f\u00fcr 1-phasige Motoren alle drei Anschl\u00fcsse belegt sein?", answer: "Damit sich alle drei Bimetalle gleichm\u00e4\u00dfig erw\u00e4rmen und die Ausl\u00f6sekennlinie stimmt. Alle Pfade in Reihe schalten." },
  { id: 576, block: "Fehlerdiagnose & Wartung", question: "Wie funktioniert ein Thermistormotorschutz (Motorvollschutz)?", answer: "PTC-F\u00fchler in den Wicklungen messen die Temperatur. Bei \u00dcberschreitung steigt der Widerstand sprunghaft \u2192 Ausl\u00f6seger\u00e4t schaltet Verdichter ab." },
  { id: 577, block: "Fehlerdiagnose & Wartung", question: "Was ist ein Druckgas\u00fcberhitzungsschutz?", answer: "Wie Thermistorschutz, aber F\u00fchler misst Druckgastemperatur im Zylinder. Sch\u00fctzt vor zu hoher Verdichtungsendtemperatur." },
  { id: 578, block: "Fehlerdiagnose & Wartung", question: "Was ist ein \u00dcbertemperaturschalter (Klixon)?", answer: "Selbstr\u00fcckstellender Bimetallschalter direkt im Motoranschlusskasten. Motorstrom erw\u00e4rmt Bimetall \u2192 bei zu hohem Strom unterbricht es." },
  { id: 579, block: "Fehlerdiagnose & Wartung", question: "Was ist Selektivit\u00e4t?", answer: "Bei Reihenschaltung mehrerer \u00dcberstromschutzorgane l\u00f6st nur das der Fehlerquelle n\u00e4chstgelegene aus. Die anderen Stromkreise bleiben in Betrieb. Erreicht durch abgestufte Ausl\u00f6sekennlinien." },
  { id: 580, block: "Fehlerdiagnose & Wartung", question: "Welche zwei Arten von Leitungsschutzorganen gibt es?", answer: "Schmelzsicherungen und Leitungsschutzschalter." },
  { id: 581, block: "Fehlerdiagnose & Wartung", question: "Gebr\u00e4uchlichste Schmelzsicherungssysteme?", answer: "St\u00f6pselsicherungen (Schraubsicherungen) und NH-Sicherungen." },
  { id: 582, block: "Fehlerdiagnose & Wartung", question: "Wie werden die beiden Schraubsicherungssysteme bezeichnet?", answer: "D-System (Diazed) und DO-System (Neozed)." },
  { id: 583, block: "Fehlerdiagnose & Wartung", question: "Was ist ein PT100-F\u00fchler?", answer: "Platin-Messwiderstand mit 100 \u03a9 bei 0 \u00b0C." },
  { id: 584, block: "Fehlerdiagnose & Wartung", question: "Was ist ein PT1000-F\u00fchler?", answer: "Platin-Messwiderstand mit 1000 \u03a9 bei 0 \u00b0C." },
  { id: 585, block: "Fehlerdiagnose & Wartung", question: "Was ist ein PTC-F\u00fchler?", answer: "Kaltleiter \u2013 Widerstand steigt mit der Temperatur." },
  { id: 586, block: "Fehlerdiagnose & Wartung", question: "Was ist ein NTC-F\u00fchler?", answer: "Hei\u00dfleiter \u2013 Widerstand sinkt mit steigender Temperatur." },
  { id: 587, block: "Fehlerdiagnose & Wartung", question: "Was sind Drucktransmitter?", answer: "Bauteile, die einen Druck in ein elektrisches Ausgangssignal umwandeln (z. B. 4\u201320 mA, 0\u201310 V) zur Verwendung in Steuerungen/Reglern." },
  { id: 588, block: "Fehlerdiagnose & Wartung", question: "Was ist die Sicherheitskette?", answer: "Serienschaltung von \u00d6ffner-/Wechslerkontakten sicherheitsrelevanter Komponenten (Motorschutz, HD/ND-Pressostat, \u00d6ldiff.-Schalter etc.) im Steuerstromkreis des Verdichtersch\u00fctzes. Bei Ausl\u00f6sung f\u00e4llt das Sch\u00fctz ab." },
  { id: 589, block: "Fehlerdiagnose & Wartung", question: "Welche Betriebsmittel befinden sich in der Sicherheitskette?", answer: "Motorschutzrelais, Thermistorschutz, HD-/ND-Pressostat, \u00d6ldifferenzdruckschalter, Druckgas\u00fcberhitzungsschutz, Str\u00f6mungsw\u00e4chter, Frostschutzthermostat, Phasenfolgerelais." },
  { id: 590, block: "Fehlerdiagnose & Wartung", question: "Wie funktioniert ein elektronisches Expansionsventil elektrotechnisch?", answer: "Drucktransmitter, Temperaturf\u00fchler und \u00dcberhitzungsregler verarbeiten Signale und senden Impulse an den Schrittmotor des Ventils \u2192 stufenlose, pr\u00e4zise \u00d6ffnung." },
  { id: 591, block: "Fehlerdiagnose & Wartung", question: "Warum Kupfer als Werkstoff in der K\u00e4ltetechnik?", answer: "Einfach zu verarbeiten (biegen, l\u00f6ten), z\u00e4h auch bei tiefen Temperaturen." },
  { id: 592, block: "Fehlerdiagnose & Wartung", question: "Warum nicht l\u00f6sbare Verbindungen (L\u00f6ten) bevorzugen?", answer: "Weniger Undichtheiten als l\u00f6sbare Verbindungen \u2192 bessere Hermetisierung." },
  { id: 593, block: "Fehlerdiagnose & Wartung", question: "Unterschied L\u00f6ten und Schwei\u00dfen?", answer: "L\u00f6ten: kein Anschmelzen des Grundwerkstoffs. Schwei\u00dfen: Grundwerkstoff wird verfl\u00fcssigt und vermischt sich mit dem Zusatz." },
  { id: 594, block: "Fehlerdiagnose & Wartung", question: "Notwendigkeit der Reinigung einer L\u00f6tstelle? Reinigungsmittel?", answer: "Oxid- und Fremdschichten m\u00fcssen mechanisch (Schmirgelleinen, Kunststoffvlies) oder chemisch (Aceton) entfernt werden, sonst keine gute Benetzung." },
  { id: 595, block: "Fehlerdiagnose & Wartung", question: "Wie soll die Oberfl\u00e4che einer L\u00f6tstelle beschaffen sein?", answer: "Metallisch blank, fett-, \u00f6l- und oxidfrei. Keine Stahlwolle verwenden." },
  { id: 596, block: "Fehlerdiagnose & Wartung", question: "Welche Lote werden f\u00fcr Cu\u2013Cu verwendet?", answer: "Silber-Phosphor-Lote \u2013 keine Flussmittel n\u00f6tig, Phosphor entfernt Oxide." },
  { id: 597, block: "Fehlerdiagnose & Wartung", question: "Welche Lote f\u00fcr Cu\u2013Messing?", answer: "Silberhartlote mit Flussmittel erforderlich." },
  { id: 598, block: "Fehlerdiagnose & Wartung", question: "Was sind Flussmittel? Wof\u00fcr erforderlich?", answer: "Reinigen die Oberfl\u00e4che von Oxiden beim L\u00f6ten, verhindern Neubildung, verbessern Benetzung und Flie\u00dff\u00e4higkeit des Lotes." },
  { id: 599, block: "Fehlerdiagnose & Wartung", question: "Gefahren beim Umgang mit Flussmitteln?", answer: "\u00c4tzend (Hautreizung), D\u00e4mpfe reizend/gesundheitssch\u00e4dlich \u2192 Absaugung vorsehen." },
  { id: 600, block: "Fehlerdiagnose & Wartung", question: "Kann die L\u00f6tstelle mit Flussmittel gereinigt werden?", answer: "Nein, Flussmittel entfernen keine Fette, \u00d6le oder sonstige Fremdschichten." },
  { id: 601, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Warum m\u00fcssen Flussmittelreste nach dem L\u00f6ten entfernt werden?", answer: "Sie sind korrosiv und k\u00f6nnen zu Korrosion des Kupferrohrs f\u00fchren. Mit Wasser/B\u00fcrste entfernen." },
  { id: 602, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist Schutzgas/Formiergas? Wie wird es beim L\u00f6ten eingesetzt?", answer: "Gas zum Sp\u00fclen der Rohrleitung w\u00e4hrend des L\u00f6tens zur Verhinderung von Zunderbildung (Oxidation). Verwendet werden Stickstoff oder Formiergas (95 % N\u2082, 5 % H\u2082)." },
  { id: 603, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Konsequenz, wenn ohne Schutzgas gel\u00f6tet wird? Zunderbildung im Rohrinneren \u2192 dieser bleibt in der Anlage und verunreinigt den Kreislauf.", answer: "604. 5 Sicherheitsregeln im Umgang mit Sauerstoff und Acetylen?" },
  { id: 605, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet \u201el\u00f6ten mit harter Flamme\u201c? Warum verhindern?", answer: "Kurzer, bl\u00e4ulicher Flammkegel = Sauerstoff\u00fcberschuss \u2192 Oxidation an der L\u00f6tstelle." },
  { id: 606, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was passiert bei starker \u00dcberhitzung der L\u00f6tstelle?", answer: "Erhebliche Oxidbildung, Gef\u00fcgever\u00e4nderung \u2192 schlechte L\u00f6tqualit\u00e4t." },
  { id: 607, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was kann passieren, wenn HFKW bei L\u00f6tarbeiten stark erhitzt werden?", answer: "Giftige Zersetzungsprodukte (Chlorwasserstoff, Fluorwasserstoff) entstehen." },
  { id: 608, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Stechender Geruch beim L\u00f6ten an R-134a-Anlage \u2013 Grund und Ma\u00dfnahme?", answer: "Vermutlich Fluorwasserstoff durch KM-Zersetzung. L\u00f6tarbeit sofort beenden, Raum l\u00fcften, verlassen." },
  { id: 609, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Unterschied Weich- und Hartl\u00f6ten bzgl. Temperatur?", answer: "Hochtemperaturl\u00f6ten? Weichl\u00f6ten <450 \u00b0C, Hartl\u00f6ten >450 \u00b0C, Hochtemperaturl\u00f6ten >900 \u00b0C (Vakuum/Schutzgas)." },
  { id: 610, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Welche L\u00f6ttechnik bei technischen Gasleitungen?", answer: "Spaltl\u00f6ten: enger, definierter Spalt (0,05\u20130,3 mm) zwischen den F\u00fcgepartnern, Lot zieht durch Kapillarwirkung ein." },
  { id: 611, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Welches L\u00f6tverfahren kommt standardm\u00e4\u00dfig in der K\u00e4ltetechnik zur Anwendung?", answer: "Hartl\u00f6tung (>450 \u00b0C) \u2013 hohe Festigkeit und Dichtheit." },
  { id: 612, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Wie entsteht eine L\u00f6tverbindung?", answer: "Benetzung \u2192 Kapillarwirkung \u2192 Diffusion. Das Lot schmilzt am erw\u00e4rmten Grundwerkstoff und dringt in den L\u00f6tspalt ein." },
  { id: 613, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Optimaler L\u00f6tspalt f\u00fcr sichere Verbindung?", answer: "0,05\u20130,3 mm, parallel." },
  { id: 614, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Welche Form muss der L\u00f6tspalt haben?", answer: "Parallel \u2013 sonst ungleichm\u00e4\u00dfige F\u00fcllung, Poren, Undichtigkeiten." },
  { id: 615, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Oberfl\u00e4chenvorbereitung der F\u00fcgepartner?", answer: "Metallisch blank, fett-, \u00f6l- und oxidfrei. Reinigung mit Kunststoffvlies, nicht mit Stahlwolle." },
  { id: 616, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Gefahren von Stahlwolle zur Kupferreinigung?", answer: "Stahlsp\u00e4ne werden eingedr\u00fcckt \u2192 elektrochemische Korrosion (Lochfra\u00df), unerw\u00fcnschte Aufrauung." },
  { id: 617, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "L\u00f6tfehler durch falsche Rohrschneider-Handhabung?", answer: "Grate und Querschnittsverengung \u2192 L\u00f6tspalt wird unma\u00dfhaltig \u2192 Hohlr\u00e4ume, Undichtigkeiten." },
  { id: 618, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Aufgabe von Silber in der Lotlegierung?", answer: "Erh\u00f6ht Z\u00e4higkeit und Festigkeit, verbessert Flie\u00dff\u00e4higkeit und Benetzung." },
  { id: 619, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Funktion von Phosphor in der Lotlegierung?", answer: "Reduziert Kupferoxide, erm\u00f6glicht flussmittelfreies L\u00f6ten von Cu\u2013Cu. Wirkt nicht bei Messing." },
  { id: 620, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Vorteil von Phosphorloten gegen\u00fcber Silberhartloten?", answer: "Kein Flussmittel n\u00f6tig bei Cu\u2013Cu, keine korrosiven R\u00fcckst\u00e4nde, einfachere Verarbeitung." },
  { id: 621, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist bei der Verl\u00f6tung von Kupfer mit Messing zu beachten?", answer: "Immer mit Flussmittel arbeiten \u2013 Messing oxidiert stark." },
  { id: 622, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Wirktemperaturbereich von Flussmitteln f\u00fcr Gasleitungen?", answer: "Ca. 500\u2013800 \u00b0C." },
  { id: 623, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist der Wirktemperaturbereich eines Flussmittels?", answer: "Temperaturfenster, in dem es Oxide l\u00f6st und Neubildung verhindert. Unterhalb inaktiv, oberhalb zersetzt/verbrannt." },
  { id: 624, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Warum m\u00fcssen Flussmittelreste vollst\u00e4ndig entfernt werden?", answer: "Chemisch aktiv \u2192 Korrosion, Lochfra\u00df, Undichtigkeiten." },
  { id: 625, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Bedeutung der Arbeitstemperatur beim L\u00f6ten?", answer: "Temperatur, bei der das Lot am Grundwerkstoff schmilzt und benetzt. Das Werkst\u00fcck muss diese Temperatur erreichen, nicht die Flamme direkt das Lot." },
  { id: 626, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Wie muss die Erw\u00e4rmung beim Spaltl\u00f6ten durchgef\u00fchrt werden?", answer: "Gleichm\u00e4\u00dfig, beide F\u00fcgepartner gleichzeitig auf Temperatur bringen \u2192 homogener Temperaturzustand, optimales Einziehen." },
  { id: 627, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Richtiger Temperaturverlauf am Werkst\u00fcck?", answer: "Aufw\u00e4rmen \u2192 Durchw\u00e4rmen \u2192 L\u00f6ten \u2192 Temperatur halten \u2192 Abk\u00fchlen." },
  { id: 628, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Wie muss die Brennerflamme beim Hartl\u00f6ten eingestellt werden?", answer: "Reduzierende Flamme (leichter Gas\u00fcberschuss) \u2013 minimiert Oxidation, verbessert Benetzung." },
  { id: 629, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Folgen des \u00dcberhitzens der L\u00f6tstelle?", answer: "Starke Oxidation, zerst\u00f6rtes Flussmittel, mangelhafte Benetzung, por\u00f6se/spr\u00f6de Verbindung." },
  { id: 630, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Woran erkennt man eine \u00fcberhitzte L\u00f6tstelle?", answer: "Por\u00f6se, unebene Naht, mattes Erscheinungsbild, Anlauffarben." },
  { id: 632, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Physikalische Grundlage f\u00fcr das Einsaugen des Lots in den Spalt?", answer: "Kapillarer F\u00fclldruck, resultierend aus der Oberfl\u00e4chenspannung des fl\u00fcssigen Lots und der engen Spaltbreite." },
  { id: 633, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Ist Weichl\u00f6ten f\u00fcr Gasleitungen zugelassen?", answer: "Nein, nur Hartl\u00f6ten." },
  { id: 634, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Warum werden R\u00fcckschlagssicherungen eingesetzt?", answer: "Verhindern Flammenr\u00fcckschlag/R\u00fcckz\u00fcndung in Schl\u00e4uche, Druckminderer oder die Gasflasche. Kombinieren Flammensperre, Gasr\u00fccktrittsventil und Temperaturausl\u00f6ser." },
  { id: 635, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Welche PSA muss beim Umgang mit brennbaren Gasen immer vorhanden sein?", answer: "Schutzhandschuhe." },
  { id: 636, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Wie m\u00fcssen Gasflaschen fachgerecht gelagert werden?", answer: "Aufrecht, gegen Umfallen gesichert (Ketten, Wagen), gut bel\u00fcftet. Brenngase und Sauerstoff getrennt lagern." },
  { id: 637, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist beim Umgang mit Sauerstoffflaschen besonders zu beachten?", answer: "Strikt fernhalten von \u00d6l und Fett (explosionsartige Reaktion)! Keine gefetteten Werkzeuge/Handschuhe." },
  { id: 638, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Gefahr durch schlecht gewarteten Brenner?", answer: "Flammenr\u00fcckschlag/R\u00fcckz\u00fcndung, instabile Flamme, Explosionsgefahr." },
  { id: 640, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was regelt die F-Gase-Verordnung?", answer: "Umgang mit fluorierten Treibhausgasen \u2013 Ziel: Emissionen verringern." },
  { id: 641, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet GWP?", answer: "Global Warming Potential \u2013 Treibhauspotenzial im Vergleich zu CO\u2082." },
  { id: 642, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Warum ist das GWP wichtig?", answer: "K\u00e4ltemittel mit hohem GWP belasten das Klima st\u00e4rker. Daher werden K\u00e4ltemittel mit niedrigerem GWP bevorzugt." },
  { id: 643, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist CO\u2082-\u00c4quivalent?", answer: "Masseneinheit, die die Klimawirkung einer bestimmten Menge eines Treibhausgases ausdr\u00fcckt (Masse \u00d7 GWP / 1000 in t)." },
  { id: 644, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Pflichten des Betreibers einer K\u00e4lteanlage?", answer: "Anlage dicht halten, regelm\u00e4\u00dfige Dichtheitskontrollen durchf\u00fchren lassen, Leckagen umgehend beheben lassen, Arbeiten dokumentieren (Pr\u00fcfbuch)." },
  { id: 645, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist eine Dichtheitskontrolle?", answer: "Pr\u00fcfung, ob K\u00e4ltemittel aus der Anlage austritt." },
  { id: 646, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist EN 378?", answer: "Europ\u00e4ische Norm f\u00fcr Sicherheit und Umweltschutz bei K\u00e4lteanlagen und W\u00e4rmepumpen (Planung, Bau, Betrieb, Wartung, R\u00fcckgewinnung)." },
  { id: 647, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was regelt EN 378 grunds\u00e4tzlich?", answer: "Sicherheits- und Umweltschutzanforderungen \u00fcber den gesamten Lebenszyklus von K\u00e4lteanlagen." },
  { id: 648, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist ISO 5149?", answer: "Internationale Norm f\u00fcr K\u00e4lteanlagen und W\u00e4rmepumpen mit Schwerpunkt Sicherheit und Umweltschutz (\u00e4hnlich EN 378)." },
  { id: 649, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Unterschied EN 378 und ISO 5149?", answer: "EN 378 ist die europ\u00e4ische, ISO 5149 die internationale Norm. Beide behandeln \u00e4hnliche Themen." },
  { id: 650, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet Sicherheitsklasse A1?", answer: "Niedrige Toxizit\u00e4t, keine Flammenausbreitung (nicht brennbar)." },
  { id: 651, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet Sicherheitsklasse A2L?", answer: "Niedrige Toxizit\u00e4t, schwer entflammbares K\u00e4ltemittel mit geringer Flammgeschwindigkeit." },
  { id: 652, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet Sicherheitsklasse A3?", answer: "Niedrige Toxizit\u00e4t, hohe Brennbarkeit." },
  { id: 653, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist die Druckger\u00e4terichtlinie?", answer: "Legt Sicherheitsanforderungen f\u00fcr Druckger\u00e4te (Rohrleitungen, Beh\u00e4lter, Komponenten) fest." },
  { id: 654, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet CE-Kennzeichnung?", answer: "Produkt erf\u00fcllt die europ\u00e4ischen Sicherheits- und Gesundheitsanforderungen." },
  { id: 655, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist ATEX?", answer: "Regelwerk f\u00fcr explosionsgef\u00e4hrdete Bereiche (Atmosph\u00e8res Explosibles) \u2013 Schutz vor Z\u00fcndquellen." },
  { id: 656, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist eine Gef\u00e4hrdungsbeurteilung?", answer: "Systematische Bewertung m\u00f6glicher Gefahren zur Festlegung passender Schutzma\u00dfnahmen." },
  { id: 657, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was bedeutet R\u00fcckgewinnung von K\u00e4ltemittel?", answer: "KM wird aus der Anlage sicher abgesaugt und in einem Beh\u00e4lter gesammelt." },
  { id: 658, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Was ist bei brennbaren K\u00e4ltemitteln besonders wichtig?", answer: "Z\u00fcndquellen vermeiden, gut l\u00fcften, geeignete Ger\u00e4te (Ex-Schutz) verwenden, Sicherheitsvorschriften genau einhalten." },
  { id: 659, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Ordnen Sie die K\u00e4ltemittel R-32, R-134a, R-404A, R-717, R-744, R-513A, R-449A steigend nach ihrem GWP-Wert.", answer: "R-717 (0) < R-744 (1) < R-513A (631) < R-32 (675) < R-449A (1391) < R-134a (1430) < R-404A (3922)." },

  // ── Grundlagen (Kern) ─────────────────────────────────────────────────
  { id: 700, block: "Grundlagen der K\u00e4ltetechnik", question: "In welcher Einheit werden Druck und Temperatur in der K\u00e4ltetechnik angegeben?", answer: "Druck in der Praxis in bar, f\u00fcr Berechnungen in Pascal (1 bar = 100.000 Pa). Temperatur in \u00b0C; Temperaturdifferenzen immer in Kelvin (K)." },
  { id: 701, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist Absolutdruck?", answer: "Der Absolutdruck ist der Druck bezogen auf das absolute Vakuum (0 bar abs). Auf Meereesh\u00f6he liegt der Atmosph\u00e4rendruck bei ca. 1 bar \u2013 Absolutdruck = Manometerdruck + 1 bar." },
  { id: 702, block: "K\u00e4ltekreislauf & Diagramme", question: "Was besagt der 1. Hauptsatz der Thermodynamik?", answer: "Energie kann weder erzeugt noch vernichtet werden, nur in andere Formen umgewandelt. In der K\u00e4lteanlage gilt: Q\u2080 + P = Qc (Kälteleistung + Verdichterarbeit = Verflüssigungsleistung)." },
  { id: 703, block: "K\u00e4ltekreislauf & Diagramme", question: "Was besagt der 2. Hauptsatz der Thermodynamik?", answer: "W\u00e4rme flie\u00dft von selbst nur von warm nach kalt. F\u00fcr den umgekehrten Prozess (K\u00e4lteanlage) ist mechanische Arbeit n\u00f6tig." },
  { id: 704, block: "K\u00e4ltekreislauf & Diagramme", question: "Was ist Enthalpie und in welcher Einheit wird sie angegeben?", answer: "Enthalpie beschreibt den thermischen Energieinhalt eines Stoffes. In der K\u00e4ltetechnik rechnet man mit der spezifischen Enthalpie in kJ/kg und arbeitet stets mit Enthalpiedifferenzen." },
  { id: 705, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist \u00dcberhitzung und welchen Schutz bietet sie?", answer: "Erw\u00e4rmung des gasf\u00f6rmigen K\u00e4ltemittels \u00fcber die Verdampfungstemperatur hinaus. Sie stellt sicher, dass nur trockener Dampf in den Verdichter gelangt und sch\u00fctzt so vor Fl\u00fcssigkeitsschl\u00e4gen." },
  { id: 706, block: "Grundlagen der K\u00e4ltetechnik", question: "Was ist Unterk\u00fchlung und welchen Vorteil bringt sie?", answer: "Abk\u00fchlung der fl\u00fcssigen K\u00e4ltemittels unter die Verfl\u00fcssigungstemperatur. Sie verhindert Flashgas vor dem Expansionsorgan und erh\u00f6ht dadurch die nutzbare K\u00e4lteleistung." },
  { id: 707, block: "Verdichter", question: "Warum darf keine Fl\u00fcssigkeit in den Verdichter gelangen?", answer: "Fl\u00fcssigkeit ist nicht kompressibel. Ein Fl\u00fcssigkeitsschlag kann Ventile, Kolben und Pleuelstangen zerst\u00f6ren \u2013 der Verdichter kann irreparabel besch\u00e4digt werden." },
  { id: 708, block: "Verfl\u00fcssiger & Verdampfer", question: "Welche Aufgabe hat der Verfl\u00fcssiger im K\u00e4ltekreislauf?", answer: "Im Verfl\u00fcssiger gibt das hei\u00dfe K\u00e4ltemittelgas W\u00e4rme an die Umgebung oder ein K\u00fchlmedium ab und kondensiert dabei von gasf\u00f6rmig zu fl\u00fcssig." },
  { id: 709, block: "Expansionsorgane & Regelung", question: "Was macht das Thermostatische Expansionsventil (TEV)?", answer: "Das TEV regelt die Einspritzmenge des K\u00e4ltemittels in den Verdampfer so, dass am Verdampferaustritt eine definierte \u00dcberhitzung (typisch 7\u20138 K) erreicht wird." },
  { id: 710, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist GWP und wie ist es definiert?", answer: "GWP (Global Warming Potential) ist das Treibhauspotenzial eines Kältemittels. Als Referenz gilt CO\u2082 mit GWP = 1. Je h\u00f6her der GWP-Wert, desto klimasch\u00e4dlicher das K\u00e4ltemittel." },
  { id: 711, block: "K\u00e4ltemittel & K\u00e4ltemaschinen\u00f6le", question: "Was ist ODP und wie ist es definiert?", answer: "ODP (Ozone Depletion Potential) beschreibt das Ozonabbaupotenzial. Als Referenz gilt R-11 mit ODP = 1. HFKW-K\u00e4ltemittel haben ODP = 0, FCKW und HFCKW k\u00f6nnen ODP > 0 haben." },
  { id: 712, block: "F-Gase & Umweltrecht", question: "Was regelt die F-Gase-Verordnung (EU 517/2014)?", answer: "Sie regelt den Umgang mit fluorierten Treibhausgasen: Phase-down der verf\u00fcgbaren Mengen, Dichtheitskontrollen, R\u00fcckgewinnung, Kennzeichnung, Zertifizierungspflicht f\u00fcr Personal und Betriebe." },
  { id: 713, block: "Montage & Inbetriebnahme", question: "Warum m\u00fcssen Saugleitungen isoliert werden?", answer: "Isolation verhindert Kondensatbildung auf der Rohroberfl\u00e4che und minimiert den unerw\u00fcnschten W\u00e4rmeeintrag, der die \u00dcberhitzung erh\u00f6hen und die Effizienz senken w\u00fcrde." },
  { id: 714, block: "Fehlerdiagnose & Wartung", question: "Was ist Hunting und wie \u00e4u\u00dft es sich?", answer: "Hunting bezeichnet das periodische Auf- und Zuschwingen des Expansionsventils. Es \u00e4u\u00dft sich in schwankenden Saugdr\u00fccken und Temperaturen; ursache ist meist \u00fcbergro\u00dfes Ventil oder falsch eingestellte \u00dcberhitzung." },
  { id: 715, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Was macht eine W\u00e4rmepumpe und wie unterscheidet sie sich von einer K\u00e4lteanlage?", answer: "Eine W\u00e4rmepumpe nutzt denselben Kreislauf wie eine K\u00e4lteanlage, aber die Nutzw\u00e4rme wird auf der Hochdruckseite (Verfl\u00fcssiger) abgenommen. Sie hebt Umweltw\u00e4rme auf ein h\u00f6heres Temperaturniveau." },
  { id: 716, block: "Elektrotechnik & Steuerung", question: "Was besagt das Ohmsche Gesetz?", answer: "U = R \u00d7 I. Spannung (V) = Widerstand (\u03a9) \u00d7 Strom (A). Daraus folgen: R = U/I und I = U/R." },
  { id: 717, block: "Montage & Inbetriebnahme", question: "Warum hartl\u00f6ten statt weichl\u00f6ten in der K\u00e4ltetechnik?", answer: "Hartgel\u00f6tete Verbindungen (Schmelztemperatur > 450 \u00b0C) sind temperatur- und druckbest\u00e4ndiger und halten den Betriebsbedingungen in K\u00e4lteanlagen dauerhaft stand." },
  { id: 718, block: "K\u00e4ltekreislauf & Diagramme", question: "Wozu dient das log(p)-h-Diagramm?", answer: "Es dient zur grafischen Darstellung und energetischen Auswertung von K\u00e4ltekreisprozessen. Auf der X-Achse die spezifische Enthalpie (kJ/kg), auf der logarithmischen Y-Achse der Absolutdruck." },
  { id: 719, block: "Pr\u00fcfungsvorbereitung & Meisterfragen", question: "Welche Positionen geh\u00f6ren zur Berechnung der K\u00e4ltelast?", answer: "Transmission (W\u00e4nde, Decke, Boden), L\u00fcftung (Au\u00dfenluft), Personenw\u00e4rme, Beleuchtungsw\u00e4rme, Maschinenw\u00e4rme und die Abk\u00fchlungsw\u00e4rme des eingelegten K\u00fchlguts." },

  // ── Vertiefung (Deep) ─────────────────────────────────────────────────
  { id: 720, block: "K\u00e4ltekreislauf & Diagramme", question: "Was ist Entropie und welche Rolle spielt sie in realen Prozessen?", answer: "Entropie ist ein Ma\u00df f\u00fcr die Unordnung und Energieverteilung in einem System. Reale Prozesse sind irreversibel \u2013 Reibung und W\u00e4rme\u00fcbertragung erzeugen Entropie und senken die Effizienz." },
  { id: 721, block: "K\u00e4ltekreislauf & Diagramme", question: "Warum steigt Entropie bei realen Verdichtungsprozessen?", answer: "Reibungsverluste, W\u00e4rme\u00fcbergang und mechanische Verluste machen den Verdichtungsprozess irreversibel. Dadurch steigt die Entropie und die Verdichtungsendtemperatur ist h\u00f6her als ideal." },
  { id: 722, block: "K\u00e4ltekreislauf & Diagramme", question: "Was bedeutet isenthalp und wo tritt es auf?", answer: "Isenthalp = konstante Enthalpie. Das Drosseln im Expansionsorgan ist n\u00e4herungsweise isenthalp: keine W\u00e4rme\u00fcbertragung, keine Arbeit, Enthalpie bleibt konstant, Temperatur und Druck sinken." },
  { id: 723, block: "K\u00e4ltekreislauf & Diagramme", question: "Was bedeutet isentrop und wo wird es angenommen?", answer: "Isentrop = verlustfreier, adiabatischer Prozess mit konstanter Entropie. Der ideale Verdichtungsprozess wird als isentrop angenommen. Reale Verdichtung weicht durch Verluste davon ab." },
  { id: 724, block: "K\u00e4ltekreislauf & Diagramme", question: "Warum sinkt der COP bei tieferer Verdampfungstemperatur?", answer: "Niedrigere Verdampfungstemperatur erfordert niedrigeren Verdampfungsdruck. Das Druckverh\u00e4ltnis zum Verfl\u00fcssigerr steigt, der Verdichter verbraucht mehr Energie \u2013 der COP sinkt." },
  { id: 725, block: "K\u00e4ltekreislauf & Diagramme", question: "Warum verbessert eine h\u00f6here Verdampfungstemperatur den COP?", answer: "H\u00f6here Verdampfungstemperatur erh\u00f6ht den Verdampfungsdruck, senkt das Druckverh\u00e4ltnis und reduziert so die Verdichterarbeit. Pro Kelvin Erh\u00f6hung verbessert sich der COP um ca. 3\u20134 %." },
  { id: 726, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum ist Unterk\u00fchlung energetisch vorteilhaft?", answer: "Sie stellt sicher, dass vor dem Expansionsorgan reine Fl\u00fcssigkeit anliegt. So entsteht kein Flashgas, die gesamte Kälteleistung des Verdampfers wird genutzt und der COP steigt." },
  { id: 727, block: "Grundlagen der K\u00e4ltetechnik", question: "Warum kann zu viel \u00dcberhitzung im Verdampfer schaden?", answer: "Ein gro\u00dfer \u00dcberhitzungsbereich bedeutet, dass viel Verdampferfl\u00e4che nur noch sensible W\u00e4rme aufnimmt statt latenter. Die Kälteleistung sinkt, weil die Fl\u00e4che nicht optimal genutzt wird." },
  { id: 728, block: "Verdichter", question: "Was ist der sch\u00e4dliche Raum im Hubkolbenverdichter?", answer: "Das Restvolumen zwischen Kolbenkopf und Ventilen, in dem nach dem Verdichten Hochdruckgas verbleibt. Dieses Gas muss erst rückexpandieren, bevor neues Sauggas angesaugt werden kann." },
  { id: 729, block: "Verdichter", question: "Warum sinkt der Liefergrad bei h\u00f6herem Druckverh\u00e4ltnis?", answer: "Mit steigendem Druckverhältnis expandiert das Gas im sch\u00e4dlichen Raum weiter zur\u00fcck, bevor Ansaugung m\u00f6glich ist. Der effektiv angesaugte Volumenstrom sinkt \u2013 der Liefergrad nimmt ab." },
  { id: 730, block: "K\u00e4ltekreislauf & Diagramme", question: "Was zeigt die Siedelinie im log(p)-h-Diagramm?", answer: "Die Siedelinie begrenzt das Nassdampfgebiet auf der fl\u00fcssigen Seite. Links davon: untergekühlte Fl\u00fcssigkeit. Auf der Linie: ges\u00e4ttigte Fl\u00fcssigkeit (Dampfgehalt x = 0)." },
  { id: 731, block: "K\u00e4ltekreislauf & Diagramme", question: "Was zeigt die Taulinie im log(p)-h-Diagramm?", answer: "Die Taulinie begrenzt das Nassdampfgebiet auf der Dampfseite. Auf der Linie: ges\u00e4ttigter Dampf (Dampfgehalt x = 1). Rechts davon: \u00fcberhitzter Dampf." },
  { id: 732, block: "F-Gase & Umweltrecht", question: "Warum sind Dichtheitskontrolle in der K\u00e4ltetechnik wichtig?", answer: "Leckagen setzen K\u00e4ltemittel mit hohem GWP frei und sch\u00e4digen das Klima. Sie f\u00fchren zu Betriebsausf\u00e4llen, Kompressorsch\u00e4den und hohen Kosten. Rechtlich sind sie vorgeschrieben (F-Gase-VO)." },
  { id: 733, block: "F-Gase & Umweltrecht", question: "Warum ist die Dokumentation in der K\u00e4ltetechnik so wichtig?", answer: "Sie ist gesetzlich vorgeschrieben (F-Gase-VO, EN 378) und dient dem Nachweis von Dichtheitspr\u00fcfungen, K\u00e4ltemittelf\u00fcllmengen, Wartungen und Reparaturen gegen\u00fcber Beh\u00f6rden." },
  { id: 734, block: "Fehlerdiagnose & Wartung", question: "Was deutet eine hohe Verdichtungsendtemperatur an?", answer: "Hohes Druckverh\u00e4ltnis, zu hohe Sauggasüberhitzung, unzureichende Verdichterk\u00fchlung oder falsches K\u00e4ltemittel. Sie kann Schmierstoffabbrand, Ventilsch\u00e4den und Verdichterausfall verursachen." },
  { id: 735, block: "Fehlerdiagnose & Wartung", question: "Warum sch\u00e4umt \u00d6l beim Kompressorstart und was sind die Folgen?", answer: "Gel\u00f6stes K\u00e4ltemittel im \u00d6l ausgast schlagartig beim Druckabfall. Das \u00d6l sch\u00e4umt, die Schmierung verschlechtert sich. Es kann zu Kolbenfressern und Verdichterausfall kommen." },
  { id: 736, block: "Elektrotechnik & Steuerung", question: "Was ist Drehstrom und warum wird er in K\u00e4lteanlagen verwendet?", answer: "Drehstrom besteht aus drei um 120\u00b0 phasenverschobenen Wechselstr\u00f6men. Er erzeugt ein Drehfeld f\u00fcr Elektromotoren, erm\u00f6glicht h\u00f6here Leistungen und gleichm\u00e4\u00dfigere Energieabnahme als Einphasenwechselstrom." },
  { id: 737, block: "Elektrotechnik & Steuerung", question: "Wozu dient der FI-Schalter und bei welchem Strom l\u00f6st er aus?", answer: "Der FI-Schalter (RCD) sch\u00fctzt Personen vor gef\u00e4hrlichen Fehlerstr\u00f6men. Er l\u00f6st bei einem Differenzstrom von i.d.R. 30 mA innerhalb von Millisekunden aus." },
  { id: 738, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum sinkt die Effizienz einer Luft-Wasser-W\u00e4rmepumpe bei starkem Frost?", answer: "Bei niedrigen Au\u00dfentemperaturen muss die W\u00e4rmepumpe gegen einen gr\u00f6\u00dferen Temperaturhub arbeiten. Das Druckverh\u00e4ltnis steigt, der COP sinkt \u2013 bei \u2013 15 \u00b0C oft unter 2." },
  { id: 739, block: "W\u00e4rme\u00fcbertragung & Isolierung", question: "Warum ist Abtauung bei Luft-W\u00e4rmepumpen n\u00f6tig und wie funktioniert sie?", answer: "Feuchte Kaltluft vereist den Au\u00dfenverdampfer. Regelm\u00e4\u00dfige Abtauung (meist Hei\u00dfgas-Umkehr oder elektrisch) stellt sicher, dass die W\u00e4rme\u00fcbertragungsfl\u00e4che frei bleibt." },

  // ── Fallenfragen & Fehleranalyse ──────────────────────────────────────
  { id: 740, block: "Fallenfragen & Fehleranalyse", question: "Was ist der h\u00e4ufigste Denkfehler bei \u00dcberhitzung und Unterk\u00fchlung?", answer: "\u00dcberhitzung betrifft gasf\u00f6rmiges K\u00e4ltemittel nach dem Verdampfer (Saugseite). Unterk\u00fchlung betrifft fl\u00fcssiges K\u00e4ltemittel nach dem Verfl\u00fcssiger. Beide Begriffe werden h\u00e4ufig verwechselt." },
  { id: 741, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zur K\u00e4ltelast ist typisch in Pr\u00fcfungen?", answer: "Typischer Denkfehler: Nur Beleuchtungsw\u00e4rme z\u00e4hlt. Richtig: K\u00e4ltelast setzt sich aus Transmission, L\u00fcftung, Personen, Beleuchtung, Maschinen und K\u00fchlgut zusammen." },
  { id: 742, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu Dichtheitskontrollen ist gef\u00e4hrlich?", answer: "Gefährlicher Irrglaube: Kleine Leckagen k\u00f6nnen ignoriert werden. Richtig: Jede Leckage muss sofort lokalisiert, behoben und dokumentiert werden \u2013 gesetzliche Pflicht laut F-Gase-VO." },
  { id: 743, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zum Verdichter ist besonders gef\u00e4hrlich?", answer: "Irrtum: Fl\u00fcssigkeit im Verdichter verbessert die Schmierung. Richtig: Fl\u00fcssigkeit ist nicht kompressibel und verursacht Fl\u00fcssigkeitsschl\u00e4ge, die den Verdichter sofort zerst\u00f6ren k\u00f6nnen." },
  { id: 744, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu Verfl\u00fcssigerst\u00f6rungen ist typisch?", answer: "Irrtum: Verfl\u00fcssigerverschmutzung senkt den Verfl\u00fcssigungsdruck. Richtig: Verschmutzung verschlechtert die W\u00e4rmeabgabe \u2013 der Verfl\u00fcssigungsdruck steigt, was den Verdichter \u00fcberbelastet." },
  { id: 745, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zum TEV wird oft als richtig angenommen?", answer: "Irrtum: Das TEV regelt die Verdichterdrehzahl. Richtig: Das TEV regelt ausschlie\u00dflich die K\u00e4ltemitteleinspritzung und die \u00dcberhitzung am Verdampferaustritt." },
  { id: 746, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu R290 (Propan) ist h\u00e4ufig?", answer: "Irrtum: R290 hat hohes GWP und ist nicht brennbar. Richtig: R290 hat ein extrem niedriges GWP (3) ist aber brennbar (Sicherheitsklasse A3) und erfordert besondere Sicherheitsma\u00dfnahmen." },
  { id: 747, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zum 2. Hauptsatz der Thermodynamik tritt auf?", answer: "Irrtum: Der 2. Hauptsatz gilt nur f\u00fcr Elektroanlagen. Richtig: Er beschreibt die Richtung aller thermodynamischen Prozesse \u2013 W\u00e4rme flie\u00dft von selbst nur von warm nach kalt." },
  { id: 748, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu Druckverlusten in Rohrleitungen ist falsch?", answer: "Irrtum: Druckverluste in der Saugleitung verbessern die Effizienz. Richtig: Druckverluste in der Saugleitung senken den Saugdruck, erh\u00f6hen das Druckverh\u00e4ltnis und verschlechtern den COP." },
  { id: 749, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu W\u00e4rmepumpen ist verbreitet?", answer: "Irrtum: Eine W\u00e4rmepumpe erzeugt Energie aus dem Nichts. Richtig: Sie verschiebt W\u00e4rme von einem niedrigen auf ein h\u00f6heres Temperaturniveau \u2013 Energie bleibt erhalten (1. Hauptsatz)." },
  { id: 750, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zum FI-Schalter wird oft gemacht?", answer: "Irrtum: Der FI-Schalter sch\u00fctzt nur Ger\u00e4te. Richtig: Der FI-Schalter (RCD) dient prim\u00e4r dem Personenschutz \u2013 er trennt bei Fehlerstrom \u00fcber 30 mA den Stromkreis." },
  { id: 751, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zum Hartl\u00f6ten ist typisch?", answer: "Irrtum: Schutzgas (Stickstoff) beim L\u00f6ten ist unn\u00f6tig. Richtig: Ohne Schutzgassp\u00fclung bilden sich Oxidschichten im Rohrinneren, die sp\u00e4ter Filter und Expansionsorgane verstopfen k\u00f6nnen." },
  { id: 752, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zum log(p)-h-Diagramm wird oft gemacht?", answer: "Irrtum: Drosseln erh\u00f6ht die Enthalpie. Richtig: Drosseln ist n\u00e4herungsweise isenthalp \u2013 die Enthalpie bleibt konstant, Druck und Temperatur sinken, der Dampfgehalt steigt." },
  { id: 753, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu \u00d6l im Verdampfer tritt in Pr\u00fcfungen auf?", answer: "Irrtum: \u00d6l im Verdampfer verbessert die W\u00e4rme\u00fcbertragung. Richtig: \u00d6l bildet einen isolierenden Film auf der Rohrinnenfl\u00e4che und verschlechtert den W\u00e4rme\u00fcbergang erheblich." },
  { id: 754, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu Sicherheitsventilen ist gef\u00e4hrlich?", answer: "Irrtum: Sicherheitsventile sind optionale Schutzeinrichtungen. Richtig: Sicherheitsventile sind gesetzlich vorgeschrieben und sch\u00fctzen das System bei unzul\u00e4ssigem Druckanstieg vor Bersten." },
  { id: 755, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zu GWP und ODP wird oft verwechselt?", answer: "Irrtum: ODP beschreibt die Klimawirkung wie CO\u2082. Richtig: ODP beschreibt den Ozonabbau (Referenz R-11 = 1), GWP beschreibt die Klimawirkung (Referenz CO\u2082 = 1) \u2013 zwei unterschiedliche Gr\u00f6\u00dfen." },
  { id: 756, block: "Fallenfragen & Fehleranalyse", question: "Welche Falschaussage zur Saugdruckseite bei Verdichterstart ist falsch?", answer: "Irrtum: Ein tiefer Saugdruck beim Start ist normal und unbedenklich. Richtig: Anhaltend niedriger Saugdruck deutet auf Kältemittelmangel, verstopftes Expansionsorgan oder schlechte W\u00e4rme\u00fcbertragung hin." },

  // ── Rechenaufgaben & Berechnungen ─────────────────────────────────────
  { id: 757, block: "Rechenaufgaben & Berechnungen", question: "Berechne die Transmissionslast: k = 0,35 W/m\u00b2K, A = 120 m\u00b2, \u0394T = 18 K.", answer: "Q\u0307 = k \u00d7 A \u00d7 \u0394T = 0,35 \u00d7 120 \u00d7 18 = 756 W." },
  { id: 758, block: "Rechenaufgaben & Berechnungen", question: "Berechne den COP bei 8 kW K\u00e4lteleistung und 2,5 kW elektrischer Leistung.", answer: "COP = Q\u0307\u2080 / P = 8 / 2,5 = 3,2. Der Verdichter wandelt 2,5 kW in 8 kW K\u00e4lteleistung um." },
  { id: 759, block: "Rechenaufgaben & Berechnungen", question: "Was ist die Temperaturdifferenz, wenn der Raum 2 \u00b0C und die Verdampfungstemperatur \u201310 \u00b0C hat? Warum ist \u0394T 12 K und nicht 12 \u00b0C?", answer: "\u0394T = 2 \u2013 (\u201310) = 12 K. Temperaturdifferenzen werden immer in Kelvin angegeben (1 K = 1 \u00b0C Differenz), aber die Einheit ist Kelvin." },
  { id: 760, block: "Rechenaufgaben & Berechnungen", question: "Wie viel W\u00e4rme muss abgef\u00fchrt werden: 50 kg K\u00fchlgut, cp = 3,8 kJ/(kg\u00b7K), \u0394T = 12 K?", answer: "Q = m \u00d7 cp \u00d7 \u0394T = 50 \u00d7 3,8 \u00d7 12 = 2 280 kJ." },
  { id: 761, block: "Rechenaufgaben & Berechnungen", question: "Berechne den Absolutdruck bei 1,6 bar \u00dcberdruck.", answer: "Absolutdruck = \u00dcberdruck + Atmosph\u00e4rendruck = 1,6 + 1,0 = 2,6 bar abs." },
  { id: 762, block: "Rechenaufgaben & Berechnungen", question: "Berechne die Unterk\u00fchlung: Verfl\u00fcssigungstemperatur 40 \u00b0C, Fl\u00fcssigkeitsrohrtemperatur 32 \u00b0C.", answer: "Unterk\u00fchlung = tC \u2013 t\u2098\u1d4f\u02e2 = 40 \u2013 32 = 8 K." },
  { id: 763, block: "Rechenaufgaben & Berechnungen", question: "Berechne die \u00dcberhitzung: Verdampfungstemperatur \u201310 \u00b0C, Sauggastemperatur 2 \u00b0C.", answer: "\u00dcberhitzung = t\u209b\u2090\u1d58\u1d4f \u2013 t\u2080 = 2 \u2013 (\u201310) = 12 K." },
  { id: 764, block: "Rechenaufgaben & Berechnungen", question: "Berechne die L\u00fcftungsw\u00e4rmelast: m\u0307 = 0,8 kg/s, cp = 1,0 kJ/(kg\u00b7K), \u0394T = 9 K.", answer: "Q\u0307 = m\u0307 \u00d7 cp \u00d7 \u0394T = 0,8 \u00d7 1,0 \u00d7 9 = 7,2 kW." },
  { id: 765, block: "Rechenaufgaben & Berechnungen", question: "Berechne die Personenw\u00e4rmelast bei 6 Personen \u00e0 120 W.", answer: "Q\u0307 = 6 \u00d7 120 W = 720 W = 0,72 kW." },
  { id: 766, block: "Rechenaufgaben & Berechnungen", question: "Berechne die Beleuchtungslast: 18 Leuchten \u00e0 35 W.", answer: "Q\u0307 = 18 \u00d7 35 = 630 W = 0,63 kW." },
  { id: 767, block: "Rechenaufgaben & Berechnungen", question: "Berechne die Maschinenwärmelast: 2,4 kW Antriebsleistung, 75 % gehen als W\u00e4rme in den Raum.", answer: "Q\u0307 = 2,4 \u00d7 0,75 = 1,8 kW." },
  { id: 768, block: "Rechenaufgaben & Berechnungen", question: "Berechne den Absolutdruck: 1,2 bar Manometerdruck, Umgebungsdruck 1,0 bar.", answer: "Absolutdruck = 1,2 + 1,0 = 2,2 bar abs." },
  { id: 769, block: "Rechenaufgaben & Berechnungen", question: "Berechne den COP: K\u00e4lteleistung 12 kW, Verdichterleistung 3 kW.", answer: "COP = 12 / 3 = 4. Interpretation: F\u00fcr jedes eingesetzte kW Strom liefert die Anlage 4 kW K\u00e4lteleistung." },
  { id: 770, block: "Rechenaufgaben & Berechnungen", question: "Berechne die Transmissionslast: A = 90 m\u00b2, k = 0,22 W/(m\u00b2K), \u0394T = 20 K.", answer: "Q\u0307 = 0,22 \u00d7 90 \u00d7 20 = 396 W." },
  { id: 771, block: "Rechenaufgaben & Berechnungen", question: "Berechne die K\u00fchlgutlast: m = 100 kg, cp = 2,1 kJ/(kg\u00b7K), \u0394T = 15 K.", answer: "Q = 100 \u00d7 2,1 \u00d7 15 = 3 150 kJ. (F\u00fcr eine Leistung wird noch die Zeitdauer ben\u00f6tigt.)" },
];

// Apply explanations to matching questions
allQuestions.forEach((q) => {
  if (_explanations[q.id]) q.explanation = _explanations[q.id];
});

export const totalCount = 711;